INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.1', 1, 1, 'Dhritarashtra', '0f6ece3b971831356f6d814e63b8fe8d6f0c28998831b58f046accf3a8e52a07', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.1', 'original', 'sa', 'Deva', 'धृतराष्ट्र उवाच।
धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः।
मामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.1', 'transliteration', 'sa', 'Latn', 'dhṛtarāṣṭra uvāca
dharmakṣetre kurukṣetre samavetā yuyutsavaḥ
māmakāḥ pāṇḍavāścaiva kimakurvata sañjaya', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.1', 'translation', 'en', 'Latn', 'What did my (people) and the Pāṇḍavas do, O Sañjaya! when they assembled together on the holy field of Kurukṣetra , desirous to do battle?', 'telang-1882');
