INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.2', 'original', 'sa', 'Deva', 'सञ्जय उवाच।
दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा।
आचार्यमुपसंगम्य राजा वचनमब्रवीत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.2', 'transliteration', 'sa', 'Latn', 'sañjaya uvāca
dṛṣṭvā tu pāṇḍavānīkaṃ vyūḍhaṃ duryodhanastadā
ācāryamupasaṃgamya rājā vacanamabravīt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.2', 'translation', 'en', 'Latn', 'Seeing the army of the Pāṇḍavas drawn up in battle-array the prince Duryodhana approached the preceptor', 'telang-1882');
