INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.3', 'original', 'sa', 'Deva', 'पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।
व्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.3', 'transliteration', 'sa', 'Latn', 'paśyaitāṃ pāṇḍuputrāṇāmācārya mahatīṃ camūm
vyūḍhāṃ drupadaputreṇa tava śiṣyeṇa dhīmatā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.3', 'translation', 'en', 'Latn', 'and spoke (these) words: ''O preceptor! observe this grand army of the sons of Pāṇḍu drawn up in battle-array by your talented pupil the son of Drupada. In it are heroes (bearing) large bows', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.3', 'vedic-scriptures', 'BG1.3', 'Devanagari and IAST digital witness');
