INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.4', 'translation', 'en', 'Latn', 'the equals of Bhīma and Arjuna in battle—(namely) Yuyudhāna Virāṭa and Drupada the master of a great car and Dhṛṣṭaketu', 'telang-1882');
