INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.6', 'translation', 'en', 'Latn', 'and that eminent man Śaibya the heroic Yudhāmanyu, the valiant Uttamaujas, the son of Subhadrā , and the sons of Draupadī—all masters of great cars. And now, O best of Brāhmaṇas!', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.6', 'vedic-scriptures', 'BG1.6', 'Devanagari and IAST digital witness');
