INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.7', 'original', 'sa', 'Deva', 'अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम।
नायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.7', 'transliteration', 'sa', 'Latn', 'asmākaṃ tu viśiṣṭā ye tānnibodha dvijottama
nāyakā mama sainyasya saṃjñārthaṃ tānbravīmi te', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.7', 'translation', 'en', 'Latn', 'learn who are most distinguished among us, and are leaders of my army. I will name them to you, in order that you may know them well. Yourself, and Bhīṣma, and Karṇa , and Kṛpa the victor of (many) battles Aśvatthāman', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.7', 'vedic-scriptures', 'BG1.7', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.7', 'telang-1882', 'Chapter 1; aligned against BG1.7', 'English translation witness');
