INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.9', 'original', 'sa', 'Deva', 'अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।
