INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.9', 'transliteration', 'sa', 'Latn', 'anye ca bahavaḥ śūrā madarthe tyaktajīvitāḥ
nānāśastrapraharaṇāḥ sarve yuddhaviśāradāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.9', 'translation', 'en', 'Latn', 'and many other brave men who have given up their lives for me who fight with various weapons, (and are) all dexterous in battle.', 'telang-1882');
