INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.9', 'telang-1882', 'Chapter 1; aligned against BG1.9', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.1.9', 'अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।
नानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः ॥', 'anye ca bahavaḥ śūrā madarthe tyaktajīvitāḥ
nānāśastrapraharaṇāḥ sarve yuddhaviśāradāḥ', 'and many other brave men who have given up their lives for me who fight with various weapons, (and are) all dexterous in battle.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.10', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.10', 1, 10, 'Sanjaya', '6ac58488737679d3f7d69e4f85a50234b2f0f416f2246581241a89270632a06a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.10', 'original', 'sa', 'Deva', 'अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।
पर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.10', 'transliteration', 'sa', 'Latn', 'aparyāptaṃ tadasmākaṃ balaṃ bhīṣmābhirakṣitam
paryāptaṃ tvidameteṣāṃ balaṃ bhīmābhirakṣitam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.10', 'translation', 'en', 'Latn', 'Thus our army which is protected by Bhīṣma is unlimited', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.10', 'vedic-scriptures', 'BG1.10', 'Devanagari and IAST digital witness');
