INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.11', 'original', 'sa', 'Deva', 'अयनेषु च सर्वेषु यथाभागमवस्थिताः।
भीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.11', 'transliteration', 'sa', 'Latn', 'ayaneṣu ca sarveṣu yathābhāgamavasthitāḥ
bhīṣmamevābhirakṣantu bhavantaḥ sarva eva hi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.11', 'translation', 'en', 'Latn', 'while this army of theirs which is protected by Bhīma is very limited. And therefore do ye all, occupying respectively the positions assigned to you, protect Bhīṣma only.''', 'telang-1882');
