INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.12', 'original', 'sa', 'Deva', 'तस्य सञ्जनयन्हर्षं कुरुवृद्धः पितामहः।
सिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.12', 'transliteration', 'sa', 'Latn', 'tasya sañjanayanharṣaṃ kuruvṛddhaḥ pitāmahaḥ
siṃhanādaṃ vinadyoccaiḥ śaṅkhaṃ dadhmau pratāpavān', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.12', 'translation', 'en', 'Latn', 'Then his powerful grandsire Bhīṣma the oldest of the Kauravas roaring aloud like a lion blew his conch, (thereby) affording delight to Duryodhana. And then all at once', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.12', 'vedic-scriptures', 'BG1.12', 'Devanagari and IAST digital witness');
