INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.13', 'transliteration', 'sa', 'Latn', 'tataḥ śaṅkhāśca bheryaśca paṇavānakagomukhāḥ
