INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.14', 'translation', 'en', 'Latn', 'and trumpets were played upon and there was a tumultuous din. Then, too, Mādhava and the son of Pāṇḍu (Arjuna), seated in a grand chariot to which white steeds were yoked, blew their heavenly conchs.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.14', 'vedic-scriptures', 'BG1.14', 'Devanagari and IAST digital witness');
