INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.15', 'original', 'sa', 'Deva', 'पाञ्चजन्यं हृषीकेशो देवदत्तं धनञ्जयः।
