INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.15', 'transliteration', 'sa', 'Latn', 'pāñcajanyaṃ hṛṣīkeśo devadattaṃ dhanañjayaḥ
