INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.15', 'translation', 'en', 'Latn', 'Hṛṣīkeśa blew the Pāñcajanya, and Dhanañjaya the Devadatta, and Bhīma, (the doer) of fearful deeds, blew the great conch Pauṇḍra . King Yudhiṣṭhira', 'telang-1882');
