INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.19', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.19', 1, 19, 'Sanjaya', 'f46b58ef0ea055e06826639c5c6d47202af95b4b7aa49f22d6afb4a2042224d8', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.19', 'original', 'sa', 'Deva', 'स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत्।
नभश्च पृथिवीं चैव तुमुलोऽभ्यनुनादयन् (or लोव्यनु) ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.19', 'transliteration', 'sa', 'Latn', 'sa ghoṣo dhārtarāṣṭrāṇāṃ hṛdayāni vyadārayat
nabhaśca pṛthivīṃ caiva tumulo.abhyanunādayan (lo vyanu)', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.19', 'translation', 'en', 'Latn', 'O king of the earth! That tumultuous din rent the hearts of all (the people) of Dhṛtarāṣṭra''s (party)', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.19', 'vedic-scriptures', 'BG1.19', 'Devanagari and IAST digital witness');
