INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.20', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.20', 1, 20, 'Sanjaya', 'c6bf6bb25c6c65b924ca3f741b36e0d51fd12b151fa26615f65f7b9b77b85759', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.20', 'original', 'sa', 'Deva', 'अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान् कपिध्वजः।
प्रवृत्ते शस्त्रसम्पाते धनुरुद्यम्य पाण्डवः।
हृषीकेशं तदा वाक्यमिदमाह महीपते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.20', 'transliteration', 'sa', 'Latn', 'atha vyavasthitāndṛṣṭvā dhārtarāṣṭrān kapidhvajaḥ
pravṛtte śastrasampāte dhanurudyamya pāṇḍavaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.20', 'translation', 'en', 'Latn', 'causing reverberations throughout heaven and earth. Then seeing (the people of ) Dhṛtarāṣṭra''s party regularly marshalled the son of Pāṇḍu whose standard is the ape raised his bow after the discharge of missiles had commenced', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.20', 'vedic-scriptures', 'BG1.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.20', 'telang-1882', 'Chapter 1; aligned against BG1.20', 'English translation witness');
