INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.28', 'original', 'sa', 'Deva', 'कृपया परयाविष्टो विषीदन्निदमब्रवीत्।
अर्जुन उवाच।
दृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.28', 'transliteration', 'sa', 'Latn', 'kṛpayā parayāviṣṭo viṣīdannidamabravīt
arjuna uvāca
dṛṣṭvemaṃ svajanaṃ kṛṣṇa yuyutsuṃ samupasthitam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.28', 'translation', 'en', 'Latn', 'and spake thus despondingly. Seeing these kinsmen, O Kṛṣṇa ! standing (here) desirous to engage in battle, my limbs droop down my mouth is quite dried up a tremor comes on my body', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.28', 'vedic-scriptures', 'BG1.28', 'Devanagari and IAST digital witness');
