INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.30', 'original', 'sa', 'Deva', 'गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।
न च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.30', 'transliteration', 'sa', 'Latn', 'gāṇḍīvaṃ sraṃsate hastāttvakcaiva paridahyate
na ca śaknomyavasthātuṃ bhramatīva ca me manaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.30', 'translation', 'en', 'Latn', 'the Gāṇḍīva (bow) slips from my hand my skin burns intensely. I am unable, too, to stand up my mind whirls round, as it were', 'telang-1882');
