INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.31', 'original', 'sa', 'Deva', 'निमित्तानि च पश्यामि विपरीतानि केशव।
न च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.31', 'transliteration', 'sa', 'Latn', 'nimittāni ca paśyāmi viparītāni keśava
na ca śreyo.anupaśyāmi hatvā svajanamāhave', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.31', 'translation', 'en', 'Latn', 'O Keśava! I see adverse omens and I do not perceive any good (to accrue) after killing (my) kinsmen in the battle.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.31', 'vedic-scriptures', 'BG1.31', 'Devanagari and IAST digital witness');
