INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.33', 'original', 'sa', 'Deva', 'येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।
त इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.33', 'transliteration', 'sa', 'Latn', 'yeṣāmarthe kāṅkṣitaṃ no rājyaṃ bhogāḥ sukhāni ca
ta ime.avasthitā yuddhe prāṇāṃstyaktvā dhanāni ca', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.33', 'translation', 'en', 'Latn', 'for whose sake we desire sovereignty enjoyments and pleasures are standing here for battle abandoning life and wealth-preceptors fathers', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.33', 'vedic-scriptures', 'BG1.33', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.33', 'telang-1882', 'Chapter 1; aligned against BG1.33', 'English translation witness');
