INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.34', 'original', 'sa', 'Deva', 'आचार्याः पितरः पुत्रास्तथैव च पितामहाः।
मातुलाः श्वशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.34', 'transliteration', 'sa', 'Latn', 'ācāryāḥ pitaraḥ putrāstathaiva ca pitāmahāḥ
mātulāḥ śvaśurāḥ pautrāḥ śyālāḥ sambandhinastathā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.34', 'translation', 'en', 'Latn', 'sons as well as grandfathers maternal uncles fathers-in-law grandsons brothers-in-law as also (other) relatives.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.34', 'vedic-scriptures', 'BG1.34', 'Devanagari and IAST digital witness');
