INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.35', 'original', 'sa', 'Deva', 'एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।
अपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.35', 'transliteration', 'sa', 'Latn', 'etānna hantumicchāmi ghnato.api madhusūdana
api trailokyarājyasya hetoḥ kiṃ nu mahīkṛte', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.35', 'translation', 'en', 'Latn', 'These I do not wish to kill though they kill (me) O destroyer of Madhu! even for the sake of sovereignty over the three worlds how much less then for this earth (alone)?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.35', 'vedic-scriptures', 'BG1.35', 'Devanagari and IAST digital witness');
