INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.37', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.37', 1, 37, 'Arjuna', '8970fc531ca2dcf4cc08b08f8f4b64f018b9b81047cd66e96bbf71ec1229eedc', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.37', 'original', 'sa', 'Deva', 'तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान्।
स्वजनं हि कथं हत्वा सुखिनः स्याम माधव ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.37', 'transliteration', 'sa', 'Latn', 'tasmānnārhā vayaṃ hantuṃ dhārtarāṣṭrānsvabāndhavān
svajanaṃ hi kathaṃ hatvā sukhinaḥ syāma mādhava', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.37', 'translation', 'en', 'Latn', 'Therefore it is not proper for us to kill our own kinsmen the sons of Dhṛtarāṣṭra. For how O Mādhava! shall we be happy after killing our own relatives?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.37', 'vedic-scriptures', 'BG1.37', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.37', 'telang-1882', 'Chapter 1; aligned against BG1.37', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.1.37', 'तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान्।
स्वजनं हि कथं हत्वा सुखिनः स्याम माधव ॥', 'tasmānnārhā vayaṃ hantuṃ dhārtarāṣṭrānsvabāndhavān
svajanaṃ hi kathaṃ hatvā sukhinaḥ syāma mādhava', 'Therefore it is not proper for us to kill our own kinsmen the sons of Dhṛtarāṣṭra. For how O Mādhava! shall we be happy after killing our own relatives?');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.38', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.38', 1, 38, 'Arjuna', '097efc683c1e8feb733f06f3477d782fafc3e9cf4786d0618f29d84111418a1d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.38', 'original', 'sa', 'Deva', 'यद्यप्येते न पश्यन्ति लोभोपहतचेतसः।
कुलक्षयकृतं दोषं मित्रद्रोहे च पातकम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.38', 'transliteration', 'sa', 'Latn', 'yadyapyete na paśyanti lobhopahatacetasaḥ
