INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.38', 'translation', 'en', 'Latn', 'Although having their consciences corrupted by avarice they do not see the evils flowing from the extinction of a family and the sin in treachery to friends still', 'telang-1882');
