INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.40', 'translation', 'en', 'Latn', 'who do see the evils flowing from the extinction of a family learn to refrain from that sin? On the extinction of a family', 'telang-1882');
