INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.41', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.41', 1, 41, 'Arjuna', '09487c4900e732b508665f935c37604b5be6978bf6971de69d5a1fa12271b711', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.41', 'original', 'sa', 'Deva', 'अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।
स्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.41', 'transliteration', 'sa', 'Latn', 'adharmābhibhavātkṛṣṇa praduṣyanti kulastriyaḥ
strīṣu duṣṭāsu vārṣṇeya jāyate varṇasaṅkaraḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.41', 'translation', 'en', 'Latn', 'the eternal rites of families are destroyed. Those rites being destroyed, impiety predominates over the whole family. In consequence of the predominance of impiety, O Kṛṣṇa! the women of the family become corrupt and the women becoming corrupt, O descendant of Vṛṣṇi! intermingling of castes results', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.41', 'vedic-scriptures', 'BG1.41', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.41', 'telang-1882', 'Chapter 1; aligned against BG1.41', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.1.41', 'अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।
स्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः ॥', 'adharmābhibhavātkṛṣṇa praduṣyanti kulastriyaḥ
strīṣu duṣṭāsu vārṣṇeya jāyate varṇasaṅkaraḥ', 'the eternal rites of families are destroyed. Those rites being destroyed, impiety predominates over the whole family. In consequence of the predominance of impiety, O Kṛṣṇa! the women of the family become corrupt and the women becoming corrupt, O descendant of Vṛṣṇi! intermingling of castes results');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.1.42', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.1.42', 1, 42, 'Arjuna', '09a669263e0b114b27dc6c7fc4391586aff04dcdeb3319cd9a4a4ce4d41df2c8', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.42', 'original', 'sa', 'Deva', 'सङ्करो नरकायैव कुलघ्नानां कुलस्य च।
पतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.42', 'transliteration', 'sa', 'Latn', 'saṅkaro narakāyaiva kulaghnānāṃ kulasya ca
patanti pitaro hyeṣāṃ luptapiṇḍodakakriyāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.42', 'translation', 'en', 'Latn', 'that intermingling necessarily leads the family and the destroyers of the family to hell for when the ceremonies of (offering) the balls of food and water (to them) fail, their ancestors fall down (to hell). By these transgressions of the destroyers of families which occasion interminglings of castes', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.42', 'vedic-scriptures', 'BG1.42', 'Devanagari and IAST digital witness');
