INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.45', 'transliteration', 'sa', 'Latn', 'aho bata mahatpāpaṃ kartuṃ vyavasitā vayam
