INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.45', 'translation', 'en', 'Latn', 'must necessarily live in hell. Alas! we are engaged in committing a heinous sin, seeing that we are making efforts for killing our own kinsmen out of greed of the pleasures of sovereignty.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.45', 'vedic-scriptures', 'BG1.45', 'Devanagari and IAST digital witness');
