INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.46', 'original', 'sa', 'Deva', 'यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः।
