INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.46', 'translation', 'en', 'Latn', 'If the sons of Dhṛtarāṣṭra, weapon in hand, should kill me in battle, me weaponless and not defending (myself), that would be better for me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.1.46', 'vedic-scriptures', 'BG1.46', 'Devanagari and IAST digital witness');
