INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.47', 'original', 'sa', 'Deva', 'सञ्जय उवाच।
एवमुक्त्वार्जुनः सङ्ख्ये रथोपस्थ उपाविशत्।
विसृज्य सशरं चापं शोकसंविग्नमानसः ॥', 'vedic-scriptures');
