INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.1.47', 'translation', 'en', 'Latn', 'Having spoken thus, Arjuna cast aside his bow together with the arrows, on the battle-field, and sat down in (his) chariot, with a mind agitated by grief.', 'telang-1882');
