INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.1', 'translation', 'en', 'Latn', 'To him, who was thus overcome with pity, and dejected, and whose eyes were full of tears and turbid, the destroyer of Madhu spoke these words. How (comes it that) this delusion O Arjuna ! which is discarded by the good', 'telang-1882');
