INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.3', 'original', 'sa', 'Deva', 'क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते।
क्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.3', 'transliteration', 'sa', 'Latn', 'klaibyaṃ mā sma gamaḥ pārtha naitattvayyupapadyate
kṣudraṃ hṛdayadaurbalyaṃ tyaktvottiṣṭha parantapa', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.3', 'translation', 'en', 'Latn', 'and occasions infamy has overtaken you in this (place of) peril? Be not effeminate, O son of Pṛthā! it is not worthy of you. Cast off this base weakness of heart, and arise, O terror of (your) foes!', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.3', 'vedic-scriptures', 'BG2.3', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.3', 'telang-1882', 'Chapter 2; aligned against BG2.3', 'English translation witness');
