INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.4', 2, 4, 'Arjuna', '859307bb699afafa1a68a8444f74b7d8491141c908bea164959d9c5d508c807f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.4', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
कथं भीष्ममहं सङ्ख्ये द्रोणं च मधुसूदन।
इषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.4', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
kathaṃ bhīṣmamahaṃ saṅkhye droṇaṃ ca madhusūdana
iṣubhiḥ pratiyotsyāmi pūjārhāvarisūdana', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.4', 'translation', 'en', 'Latn', 'How, O destroyer of Madhu! shall I encounter with arrows in the battle Bhīṣma and Droṇa —both, O destroyer of enemies! entitled to reverence?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.4', 'vedic-scriptures', 'BG2.4', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.4', 'telang-1882', 'Chapter 2; aligned against BG2.4', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.4', 'अर्जुन उवाच।
कथं भीष्ममहं सङ्ख्ये द्रोणं च मधुसूदन।
इषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन ॥', 'arjuna uvāca
