INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.6', 'original', 'sa', 'Deva', 'न चैतद्विद्मः कतरन्नो गरीयो
यद्वा जयेम यदि वा नो जयेयुः।
यानेव हत्वा न जिजीविषामस्-
तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.6', 'transliteration', 'sa', 'Latn', 'na caitadvidmaḥ kataranno garīyo yadvā jayema yadi vā no jayeyuḥ
yāneva hatvā na jijīviṣāmaḥ te.avasthitāḥ pramukhe dhārtarāṣṭrāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.6', 'translation', 'en', 'Latn', 'or that they should vanquish us. Even those', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.6', 'vedic-scriptures', 'BG2.6', 'Devanagari and IAST digital witness');
