INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.7', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.7', 2, 7, 'Arjuna', '610c909d8cbab0f0744774c5317a33cd94ca881d45f57d1bec5f189b2c7799b2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.7', 'original', 'sa', 'Deva', 'कार्पण्यदोषोपहतस्वभावः
पृच्छामि त्वां धर्मसम्मूढचेताः।
यच्छ्रेयः स्यान्निश्चितं ब्रूहि तन्मे
शिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.7', 'transliteration', 'sa', 'Latn', 'kārpaṇyadoṣopahatasvabhāvaḥ pṛcchāmi tvāṃ dharmasammūḍhacetāḥ
yacchreyaḥ syānniścitaṃ brūhi tanme śiṣyaste.ahaṃ śādhi māṃ tvāṃ prapannam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.7', 'translation', 'en', 'Latn', 'whom having killed we do not wish to live—even those sons of Dhṛtarāṣṭra stand (arrayed) against us. With a heart contaminated by the taint of helplessness with a mind confounded about my duty I ask you. Tell me what is assuredly good for me. I am your disciple instruct me', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.7', 'vedic-scriptures', 'BG2.7', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.7', 'telang-1882', 'Chapter 2; aligned against BG2.7', 'English translation witness');
