INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.8', 'original', 'sa', 'Deva', 'न हि प्रपश्यामि ममापनुद्याद्
यच्छोकमुच्छोषणमिन्द्रियाणाम्।
अवाप्य भूमावसपत्नमृद्धं
राज्यं सुराणामपि चाधिपत्यम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.8', 'transliteration', 'sa', 'Latn', 'na hi prapaśyāmi mamāpanudyād yacchokamucchoṣaṇamindriyāṇām
avāpya bhūmāvasapatnamṛddhaṃ rājyaṃ surāṇāmapi cādhipatyam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.8', 'translation', 'en', 'Latn', 'who have thrown myself on your (indulgence). For I do not perceive what is to dispel that grief which will dry up my organs after I shall have obtained a prosperous kingdom on earth without a foe or even the sovereignty of the gods.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.8', 'vedic-scriptures', 'BG2.8', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.8', 'telang-1882', 'Chapter 2; aligned against BG2.8', 'English translation witness');
