INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.11', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
अशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे।
गतासूनगतासूंश्च नानुशोचन्ति पण्डिताः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.11', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
aśocyānanvaśocastvaṃ prajñāvādāṃśca bhāṣase
gatāsūnagatāsūṃśca nānuśocanti paṇḍitāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.11', 'translation', 'en', 'Latn', 'You have grieved for those who deserve no grief, and you talk words of wisdom. Learned men grieve not for the living nor the dead. Never did I not exist, nor you, nor these rulers of men', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.11', 'vedic-scriptures', 'BG2.11', 'Devanagari and IAST digital witness');
