INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.12', 'original', 'sa', 'Deva', 'न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः।
