INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.12', 'transliteration', 'sa', 'Latn', 'na tvevāhaṃ jātu nāsaṃ na tvaṃ neme janādhipāḥ
