INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.14', 'original', 'sa', 'Deva', 'मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः।
आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.14', 'transliteration', 'sa', 'Latn', 'mātrāsparśāstu kaunteya śītoṣṇasukhaduḥkhadāḥ
āgamāpāyino.anityāstāṃstitikṣasva bhārata', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.14', 'translation', 'en', 'Latn', 'O son of Kuntī ! which produce cold and heat pleasure and pain are not permanent they are ever coming and going.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.14', 'vedic-scriptures', 'BG2.14', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.14', 'telang-1882', 'Chapter 2; aligned against BG2.14', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.14', 'मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः।
आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत ॥', 'mātrāsparśāstu kaunteya śītoṣṇasukhaduḥkhadāḥ
āgamāpāyino.anityāstāṃstitikṣasva bhārata', 'O son of Kuntī ! which produce cold and heat pleasure and pain are not permanent they are ever coming and going.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.15', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.15', 2, 15, 'Krishna', '00a04533d1eacd9291bf18bd7a19c16ed18ca4d8457ba47651b20fc69ce7c48d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.15', 'original', 'sa', 'Deva', 'यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ।
समदुःखसुखं धीरं सोऽमृतत्वाय कल्पते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.15', 'transliteration', 'sa', 'Latn', 'yaṃ hi na vyathayantyete puruṣaṃ puruṣarṣabha
samaduḥkhasukhaṃ dhīraṃ so.amṛtatvāya kalpate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.15', 'translation', 'en', 'Latn', 'Bear them, O descendant of Bharata! For, O chief of men! that sensible man whom they (pain and pleasure being alike to him) afflict not, he merits immortality.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.15', 'vedic-scriptures', 'BG2.15', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.15', 'telang-1882', 'Chapter 2; aligned against BG2.15', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.15', 'यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ।
