INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.17', 2, 17, 'Krishna', '1f32254b82daa5e5bf26c78c1991cf7ce860f7e179135733d213b779e44e6ee3', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.17', 'original', 'sa', 'Deva', 'अविनाशि तु तद्विद्धि येन सर्वमिदं ततम्।
विनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.17', 'transliteration', 'sa', 'Latn', 'avināśi tu tadviddhi yena sarvamidaṃ tatam
vināśamavyayasyāsya na kaścitkartumarhati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.17', 'translation', 'en', 'Latn', 'Know that to be indestructible which pervades all this the destruction of that inexhaustible (principle) none can bring about.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.17', 'vedic-scriptures', 'BG2.17', 'Devanagari and IAST digital witness');
