INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.18', 'original', 'sa', 'Deva', 'अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः।
