INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.18', 'transliteration', 'sa', 'Latn', 'antavanta ime dehā nityasyoktāḥ śarīriṇaḥ
anāśino.aprameyasya tasmādyudhyasva bhārata', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.18', 'translation', 'en', 'Latn', 'These bodies appertaining to the embodied (self) which is eternal, indestructible, and indefinable, are said to be perishable therefore do engage in battle, O descendant of Bharata!', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.18', 'vedic-scriptures', 'BG2.18', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.18', 'telang-1882', 'Chapter 2; aligned against BG2.18', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.18', 'अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः।
अनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत ॥', 'antavanta ime dehā nityasyoktāḥ śarīriṇaḥ
anāśino.aprameyasya tasmādyudhyasva bhārata', 'These bodies appertaining to the embodied (self) which is eternal, indestructible, and indefinable, are said to be perishable therefore do engage in battle, O descendant of Bharata!');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.19', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.19', 2, 19, 'Krishna', 'e2ecb040951957cb3fb14ca4b327e085e2e084e3a4f2e94465c3b772d5e689ca', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.19', 'original', 'sa', 'Deva', 'य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम्।
उभौ तौ न विजानीतो नायं हन्ति न हन्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.19', 'transliteration', 'sa', 'Latn', 'ya enaṃ vetti hantāraṃ yaścainaṃ manyate hatam ubhau tau na vijānīto nāyaṃ hanti na hanyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.19', 'translation', 'en', 'Latn', 'He who thinks it to be the killer and he who thinks it to be killed, both know nothing. It kills not, is not killed.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.19', 'vedic-scriptures', 'BG2.19', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.19', 'telang-1882', 'Chapter 2; aligned against BG2.19', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.19', 'य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम्।
उभौ तौ न विजानीतो नायं हन्ति न हन्यते ॥', 'ya enaṃ vetti hantāraṃ yaścainaṃ manyate hatam ubhau tau na vijānīto nāyaṃ hanti na hanyate', 'He who thinks it to be the killer and he who thinks it to be killed, both know nothing. It kills not, is not killed.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.20', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.20', 2, 20, 'Krishna', 'dd4f537a8f07e098b83616f6b399efe9910c22e5f741631d82451bad7475b643', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.20', 'original', 'sa', 'Deva', 'न जायते म्रियते वा कदाचिन्
नायं भूत्वा भविता वा न भूयः।
अजो नित्यः शाश्वतोऽयं पुराणो
न हन्यते हन्यमाने शरीरे ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.20', 'transliteration', 'sa', 'Latn', 'na jāyate mriyate vā kadācin nāyaṃ bhūtvā bhavitā vā na bhūyaḥ
ajo nityaḥ śāśvato.ayaṃ purāṇo na hanyate hanyamāne śarīre', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.20', 'translation', 'en', 'Latn', 'It is not born, nor does it ever die, nor, having existed, does it exist no more. Unborn, everlasting, unchangeable, and primeval, it is not killed when the body is killed. O son of Pṛthā! how can that man who knows it thus to be indestructible everlasting unborn', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.20', 'vedic-scriptures', 'BG2.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.20', 'telang-1882', 'Chapter 2; aligned against BG2.20', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.20', 'न जायते म्रियते वा कदाचिन्
नायं भूत्वा भविता वा न भूयः।
अजो नित्यः शाश्वतोऽयं पुराणो
न हन्यते हन्यमाने शरीरे ॥', 'na jāyate mriyate vā kadācin nāyaṃ bhūtvā bhavitā vā na bhūyaḥ
ajo nityaḥ śāśvato.ayaṃ purāṇo na hanyate hanyamāne śarīre', 'It is not born, nor does it ever die, nor, having existed, does it exist no more. Unborn, everlasting, unchangeable, and primeval, it is not killed when the body is killed. O son of Pṛthā! how can that man who knows it thus to be indestructible everlasting unborn');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.21', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.21', 2, 21, 'Krishna', '447e01aa0417d2385035eb1b3b9ba4bb6b38007153a39edef1b4345bc8224cf1', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.21', 'original', 'sa', 'Deva', 'वेदाविनाशिनं नित्यं य एनमजमव्ययम्।
कथं स पुरुषः पार्थ कं घातयति हन्ति कम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.21', 'transliteration', 'sa', 'Latn', 'vedāvināśinaṃ nityaṃ ya enamajamavyayam
kathaṃ sa puruṣaḥ pārtha kaṃ ghātayati hanti kam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.21', 'translation', 'en', 'Latn', 'and inexhaustible how and whom can he kill whom can he cause to be killed? As a man', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.21', 'vedic-scriptures', 'BG2.21', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.21', 'telang-1882', 'Chapter 2; aligned against BG2.21', 'English translation witness');
