INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.22', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.22', 2, 22, 'Krishna', '179160977a8cb9c592c04b71e10f66e526a2bf3e37e770622d13cbb9ff781881', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.22', 'original', 'sa', 'Deva', 'वासांसि जीर्णानि यथा विहाय
नवानि गृह्णाति नरोऽपराणि।
तथा शरीराणि विहाय जीर्णा-
न्यन्यानि संयाति नवानि देही ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.22', 'transliteration', 'sa', 'Latn', 'vāsāṃsi jīrṇāni yathā vihāya navāni gṛhṇāti naro.aparāṇi
tathā śarīrāṇi vihāya jīrṇāni anyāni saṃyāti navāni dehī', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.22', 'translation', 'en', 'Latn', 'casting off old clothes puts on others and new ones so the embodied (self) casting off old bodies goes to others and new ones.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.22', 'vedic-scriptures', 'BG2.22', 'Devanagari and IAST digital witness');
