INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.23', 'original', 'sa', 'Deva', 'नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः।
न चैनं क्लेदयन्त्यापो न शोषयति मारुतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.23', 'transliteration', 'sa', 'Latn', 'nainaṃ chindanti śastrāṇi nainaṃ dahati pāvakaḥ
na cainaṃ kledayantyāpo na śoṣayati mārutaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.23', 'translation', 'en', 'Latn', 'Weapons do not divide it (into pieces) fire does not burn it, waters do not moisten it the wind does not dry it up. It is not divisible it is not combustible it is not to be moistened', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.23', 'vedic-scriptures', 'BG2.23', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.23', 'telang-1882', 'Chapter 2; aligned against BG2.23', 'English translation witness');
