INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.24', 'translation', 'en', 'Latn', 'it is not to be dried up. It is everlasting, all-pervading, stable, firm, and eternal.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.24', 'vedic-scriptures', 'BG2.24', 'Devanagari and IAST digital witness');
