INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.25', 'original', 'sa', 'Deva', 'अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते।
तस्मादेवं विदित्वैनं नानुशोचितुमर्हसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.25', 'transliteration', 'sa', 'Latn', 'avyakto.ayamacintyo.ayamavikāryo.ayamucyate
