INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.25', 'translation', 'en', 'Latn', 'It is said to be unperceived, to be unthinkable, to be unchangeable. Therefore knowing it to be such', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.25', 'vedic-scriptures', 'BG2.25', 'Devanagari and IAST digital witness');
