INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.26', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.26', 2, 26, 'Krishna', '76a81c338cc1df224bb00804ca286718baebd46f0abd5affa30b109f434d5e52', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.26', 'original', 'sa', 'Deva', 'अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम्।
तथापि त्वं महाबाहो नैवं शोचितुमर्हसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.26', 'transliteration', 'sa', 'Latn', 'atha cainaṃ nityajātaṃ nityaṃ vā manyase mṛtam
tathāpi tvaṃ mahābāho naivaṃ śocitumarhasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.26', 'translation', 'en', 'Latn', 'you ought not to grieve But even if you think that it is constantly born and constantly dies still O you of mighty arms! you ought not to grieve thus. For to one that is born', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.26', 'vedic-scriptures', 'BG2.26', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.26', 'telang-1882', 'Chapter 2; aligned against BG2.26', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.26', 'अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम्।
