INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.27', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.27', 2, 27, 'Krishna', '41d9741ac5053197bada45d57880323995d71be1c8c4ba6872f5de0bfd717e23', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.27', 'original', 'sa', 'Deva', 'जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च।
तस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.27', 'transliteration', 'sa', 'Latn', 'jātasya hi dhruvo mṛtyurdhruvaṃ janma mṛtasya ca
tasmādaparihārye.arthe na tvaṃ śocitumarhasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.27', 'translation', 'en', 'Latn', 'death is certain and to one that dies, birth is certain. Therefore about (this) unavoidable thing, you ought not to grieve. The source of things, O descendant of Bharata! is unperceived', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.27', 'vedic-scriptures', 'BG2.27', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.27', 'telang-1882', 'Chapter 2; aligned against BG2.27', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.27', 'जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च।
तस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि ॥', 'jātasya hi dhruvo mṛtyurdhruvaṃ janma mṛtasya ca
tasmādaparihārye.arthe na tvaṃ śocitumarhasi', 'death is certain and to one that dies, birth is certain. Therefore about (this) unavoidable thing, you ought not to grieve. The source of things, O descendant of Bharata! is unperceived');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.28', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.28', 2, 28, 'Krishna', '63dbed3ad1e19e6f93ba50e9d0b6b4e58e2a7a31df71aa68b19ce9bcbd0901b2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.28', 'original', 'sa', 'Deva', 'अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत।
अव्यक्तनिधनान्येव तत्र का परिदेवना ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.28', 'transliteration', 'sa', 'Latn', 'avyaktādīni bhūtāni vyaktamadhyāni bhārata
avyaktanidhanānyeva tatra kā paridevanā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.28', 'translation', 'en', 'Latn', 'their middle state is perceived and their end again is unperceived. What (occasion is there for any) lamentation regarding them?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.28', 'vedic-scriptures', 'BG2.28', 'Devanagari and IAST digital witness');
