INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.29', 'original', 'sa', 'Deva', 'आश्चर्यवत्पश्यति कश्चिदेन-
माश्चर्यवद्वदति तथैव चान्यः।
आश्चर्यवच्चैनमन्यः शृणोति
श्रुत्वाप्येनं वेद न चैव कश्चित् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.29', 'transliteration', 'sa', 'Latn', 'āścaryavatpaśyati kaścidenam āścaryavadvadati tathaiva cānyaḥ
āścaryavaccainamanyaḥ śṛṇoti śrutvāpyenaṃ veda na caiva kaścit', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.29', 'translation', 'en', 'Latn', 'One looks upon it as a wonder another similarly speaks of it as a wonder another too hears of it as a wonder and even after having heard of it, no one does really know it.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.29', 'vedic-scriptures', 'BG2.29', 'Devanagari and IAST digital witness');
