INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.30', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.30', 2, 30, 'Krishna', '14c975d5eab672b5d7678e931e655cd881bd6379bb0d1ecf6eebcf45aed5a93b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.30', 'original', 'sa', 'Deva', 'देही नित्यमवध्योऽयं देहे सर्वस्य भारत।
तस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.30', 'transliteration', 'sa', 'Latn', 'dehī nityamavadhyo.ayaṃ dehe sarvasya bhārata
tasmātsarvāṇi bhūtāni na tvaṃ śocitumarhasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.30', 'translation', 'en', 'Latn', 'This embodied (self), O descendant of Bharata! within every one''s body is ever indestructible. Therefore you ought not to grieve for any being.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.30', 'vedic-scriptures', 'BG2.30', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.30', 'telang-1882', 'Chapter 2; aligned against BG2.30', 'English translation witness');
