INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.31', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.31', 2, 31, 'Krishna', '2a40a785bd9895e41b20f74ef0d45396a4030e3b84ba1ae41c6680e1788779fb', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.31', 'original', 'sa', 'Deva', 'स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि।
धर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.31', 'transliteration', 'sa', 'Latn', 'svadharmamapi cāvekṣya na vikampitumarhasi
dharmyāddhi yuddhācchreyo.anyatkṣatriyasya na vidyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.31', 'translation', 'en', 'Latn', 'Having regard to your own duty also, you ought not to falter, for there is nothing better for a Kṣatriya than a righteous battle.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.31', 'vedic-scriptures', 'BG2.31', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.31', 'telang-1882', 'Chapter 2; aligned against BG2.31', 'English translation witness');
