INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.32', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.32', 2, 32, 'Krishna', '44ff4d3f72b07d5475f08360bf2bb3f41090222f4d036afe6171cafd737f5623', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.32', 'original', 'sa', 'Deva', 'यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम्।
सुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.32', 'transliteration', 'sa', 'Latn', 'yadṛcchayā copapannaṃ svargadvāramapāvṛtam
sukhinaḥ kṣatriyāḥ pārtha labhante yuddhamīdṛśam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.32', 'translation', 'en', 'Latn', 'Happy those Kṣatriyas O son of Pṛthā! who can find such a battle (to fight)—come of itself—an open door to heaven! But if you will not fight this righteous battle', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.32', 'vedic-scriptures', 'BG2.32', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.32', 'telang-1882', 'Chapter 2; aligned against BG2.32', 'English translation witness');
