INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.35', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.35', 2, 35, 'Krishna', '15babbad0407617c60e9bb6aeb8ec868b25e6560c3d8e2c4db802458acb248c7', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.35', 'original', 'sa', 'Deva', 'भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः।
येषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.35', 'transliteration', 'sa', 'Latn', 'bhayādraṇāduparataṃ maṃsyante tvāṃ mahārathāḥ
yeṣāṃ ca tvaṃ bahumato bhūtvā yāsyasi lāghavam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.35', 'translation', 'en', 'Latn', '(Warriors who are) masters of great cars will think that you abstained from the battle through fear and having been highly thought of by them', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.35', 'vedic-scriptures', 'BG2.35', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.35', 'telang-1882', 'Chapter 2; aligned against BG2.35', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.35', 'भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः।
येषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम् ॥', 'bhayādraṇāduparataṃ maṃsyante tvāṃ mahārathāḥ
yeṣāṃ ca tvaṃ bahumato bhūtvā yāsyasi lāghavam', '(Warriors who are) masters of great cars will think that you abstained from the battle through fear and having been highly thought of by them');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.36', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.36', 2, 36, 'Krishna', '05d5d57f0be7b359b97b07ae8b5b3137cca28373ec78401df6ac6df9099d850c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.36', 'original', 'sa', 'Deva', 'अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः।
निन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.36', 'transliteration', 'sa', 'Latn', 'avācyavādāṃśca bahūnvadiṣyanti tavāhitāḥ
nindantastava sāmarthyaṃ tato duḥkhataraṃ nu kim', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.36', 'translation', 'en', 'Latn', 'you will fall down to littleness. Your enemies, too, decrying your power, will speak much about you that should not be spoken. And what, indeed, more lamentable than that?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.36', 'vedic-scriptures', 'BG2.36', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.36', 'telang-1882', 'Chapter 2; aligned against BG2.36', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.36', 'अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः।
