INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.37', 'original', 'sa', 'Deva', 'हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम्।
तस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.37', 'transliteration', 'sa', 'Latn', 'hato vā prāpsyasi svargaṃ jitvā vā bhokṣyase mahīm
tasmāduttiṣṭha kaunteya yuddhāya kṛtaniścayaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.37', 'translation', 'en', 'Latn', 'Killed, you will obtain heaven victorious, you will enjoy the earth. Therefore arise, O son of Kuntī! resolved to (engage in) battle.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.37', 'vedic-scriptures', 'BG2.37', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.37', 'telang-1882', 'Chapter 2; aligned against BG2.37', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.37', 'हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम्।
तस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः ॥', 'hato vā prāpsyasi svargaṃ jitvā vā bhokṣyase mahīm
tasmāduttiṣṭha kaunteya yuddhāya kṛtaniścayaḥ', 'Killed, you will obtain heaven victorious, you will enjoy the earth. Therefore arise, O son of Kuntī! resolved to (engage in) battle.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.38', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.38', 2, 38, 'Krishna', '94b93df3f1cfefcb02783c559b375d9f42c07928b1b5988a773edd7ddc74bf6f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.38', 'original', 'sa', 'Deva', 'सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ।
ततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.38', 'transliteration', 'sa', 'Latn', 'sukhaduḥkhe same kṛtvā lābhālābhau jayājayau
tato yuddhāya yujyasva naivaṃ pāpamavāpsyasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.38', 'translation', 'en', 'Latn', 'Looking alike on pleasure and pain, on gain and loss, on victory and defeat, then prepare for battle, and thus you will not incur sin.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.38', 'vedic-scriptures', 'BG2.38', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.38', 'telang-1882', 'Chapter 2; aligned against BG2.38', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.38', 'सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ।
ततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि ॥', 'sukhaduḥkhe same kṛtvā lābhālābhau jayājayau
tato yuddhāya yujyasva naivaṃ pāpamavāpsyasi', 'Looking alike on pleasure and pain, on gain and loss, on victory and defeat, then prepare for battle, and thus you will not incur sin.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.39', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.39', 2, 39, 'Krishna', '2e78882ba21f93dcec11aae3b92153ac83c466e8303c7277d2af4900c7aad41c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.39', 'original', 'sa', 'Deva', 'एषा तेऽभिहिता साङ्ख्ये बुद्धिर्योगे त्विमां शृणु।
बुद्ध्या युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.39', 'transliteration', 'sa', 'Latn', 'eṣā te.abhihitā sāṅkhye buddhiryoge tvimāṃ śṛṇu
buddhyā yukto yayā pārtha karmabandhaṃ prahāsyasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.39', 'translation', 'en', 'Latn', 'The knowledge here declared to you is that relating to the Sāṅkhya,. Now hear that relating to the Yoga . Possessed of this knowledge, O son of Pṛthā! you will cast off the bonds of action. In this (path to final emancipation) nothing that is commenced becomes abortive', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.39', 'vedic-scriptures', 'BG2.39', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.39', 'telang-1882', 'Chapter 2; aligned against BG2.39', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.39', 'एषा तेऽभिहिता साङ्ख्ये बुद्धिर्योगे त्विमां शृणु।
बुद्ध्या युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि ॥', 'eṣā te.abhihitā sāṅkhye buddhiryoge tvimāṃ śṛṇu
buddhyā yukto yayā pārtha karmabandhaṃ prahāsyasi', 'The knowledge here declared to you is that relating to the Sāṅkhya,. Now hear that relating to the Yoga . Possessed of this knowledge, O son of Pṛthā! you will cast off the bonds of action. In this (path to final emancipation) nothing that is commenced becomes abortive');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.40', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.40', 2, 40, 'Krishna', 'ddbec8037778b8cedcb4367ddf260e81ad9266744db99a49a6003fac76a283f5', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.40', 'original', 'sa', 'Deva', 'नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते।
स्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.40', 'transliteration', 'sa', 'Latn', 'nehābhikramanāśo.asti pratyavāyo na vidyate
svalpamapyasya dharmasya trāyate mahato bhayāt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.40', 'translation', 'en', 'Latn', 'no obstacles exist and even a little of this (form of ) piety protects one from great danger.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.40', 'vedic-scriptures', 'BG2.40', 'Devanagari and IAST digital witness');
