INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.41', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.41', 2, 41, 'Krishna', '6c02ebc982e23d220044a24ed9d5e720019a9c429c8c542fd18866e67055e720', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.41', 'original', 'sa', 'Deva', 'व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन।
बहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.41', 'transliteration', 'sa', 'Latn', 'vyavasāyātmikā buddhirekeha kurunandana
bahuśākhā hyanantāśca buddhayo.avyavasāyinām', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.41', 'translation', 'en', 'Latn', 'There is here O descendant of Kuru ! but one state of mind consisting in firm understanding. But the states of mind of those who have no firm understanding are many-branched and endless. The state of mind consisting in firm understanding regarding steady contemplation does not belong to those O son of Pṛthā! who are strongly attached to (worldly) pleasures and power and whose minds are drawn away by that flowery talk which is full of (ordinances of) specific acts for the attainment of (those) pleasures and (that) power and which promises birth as the fruit of acts—(that flowery talk) which those unwise ones utter who are enamoured of Vedic words', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.41', 'vedic-scriptures', 'BG2.41', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.41', 'telang-1882', 'Chapter 2; aligned against BG2.41', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.41', 'व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन।
बहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम् ॥', 'vyavasāyātmikā buddhirekeha kurunandana
bahuśākhā hyanantāśca buddhayo.avyavasāyinām', 'There is here O descendant of Kuru ! but one state of mind consisting in firm understanding. But the states of mind of those who have no firm understanding are many-branched and endless. The state of mind consisting in firm understanding regarding steady contemplation does not belong to those O son of Pṛthā! who are strongly attached to (worldly) pleasures and power and whose minds are drawn away by that flowery talk which is full of (ordinances of) specific acts for the attainment of (those) pleasures and (that) power and which promises birth as the fruit of acts—(that flowery talk) which those unwise ones utter who are enamoured of Vedic words');
