INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.45', 'original', 'sa', 'Deva', 'त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन।
निर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.45', 'transliteration', 'sa', 'Latn', 'traiguṇyaviṣayā vedā nistraiguṇyo bhavārjuna
nirdvandvo nityasattvastho niryogakṣema ātmavān', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.45', 'translation', 'en', 'Latn', 'do you O Arjuna! rise above those effects of the three qualities and be free from the pairs of opposites always preserve courage be free from anxiety for new acquisitions or protection of old acquisitions', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.45', 'vedic-scriptures', 'BG2.45', 'Devanagari and IAST digital witness');
