INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.46', 'original', 'sa', 'Deva', 'यावानर्थ उदपाने सर्वतः सम्प्लुतोदके।
तावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.46', 'transliteration', 'sa', 'Latn', 'yāvānartha udapāne sarvataḥ samplutodake
tāvānsarveṣu vedeṣu brāhmaṇasya vijānataḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.46', 'translation', 'en', 'Latn', 'and be self-controlled. To the instructed Brāhmaṇa there is in all the Vedas as much utility as in a reservoir of water into which waters flow from all sides.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.46', 'vedic-scriptures', 'BG2.46', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.46', 'telang-1882', 'Chapter 2; aligned against BG2.46', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.46', 'यावानर्थ उदपाने सर्वतः सम्प्लुतोदके।
तावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः ॥', 'yāvānartha udapāne sarvataḥ samplutodake
tāvānsarveṣu vedeṣu brāhmaṇasya vijānataḥ', 'and be self-controlled. To the instructed Brāhmaṇa there is in all the Vedas as much utility as in a reservoir of water into which waters flow from all sides.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.47', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.47', 2, 47, 'Krishna', '532a9a9398f860961c45f3a7585e458f098ddc681c7954d10675184a5f554302', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.47', 'original', 'sa', 'Deva', 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।
मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.47', 'transliteration', 'sa', 'Latn', 'karmaṇyevādhikāraste mā phaleṣu kadācana
mā karmaphalaheturbhūrmā te saṅgo.astvakarmaṇi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.47', 'translation', 'en', 'Latn', 'Your business is with action alone not by any means with fruit. Let not the fruit of action be your motive (to action). Let not your attachment be (fixed) on inaction.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.47', 'vedic-scriptures', 'BG2.47', 'Devanagari and IAST digital witness');
