INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.48', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.48', 2, 48, 'Krishna', 'c27d61e6400be9c71425cc6b75def7ce762e16f2c2edc46302c1b5068839add3', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.48', 'original', 'sa', 'Deva', 'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।
सिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.48', 'transliteration', 'sa', 'Latn', 'yogasthaḥ kuru karmāṇi saṅgaṃ tyaktvā dhanañjaya
siddhyasiddhyoḥ samo bhūtvā samatvaṃ yoga ucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.48', 'translation', 'en', 'Latn', 'Having recourse to devotion, O Dhanañjaya ! perform actions, casting off (all) attachment, and being equable in success or ill-success (such) equability is called devotion.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.48', 'vedic-scriptures', 'BG2.48', 'Devanagari and IAST digital witness');
