INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.49', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.49', 2, 49, 'Krishna', '7d0edbf3a3bcb606e504b9b8b9996853455c122e32ee693142733067e3604124', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.49', 'original', 'sa', 'Deva', 'दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय।
बुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.49', 'transliteration', 'sa', 'Latn', 'dūreṇa hyavaraṃ karma buddhiyogāddhanañjaya
buddhau śaraṇamanviccha kṛpaṇāḥ phalahetavaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.49', 'translation', 'en', 'Latn', 'Action, O Dhanañjaya! is far inferior to the devotion of the mind. In that devotion seek shelter. Wretched are those whose motive (to action) is the fruit (of action).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.49', 'vedic-scriptures', 'BG2.49', 'Devanagari and IAST digital witness');
