INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.50', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.50', 2, 50, 'Krishna', '9b8573314b8183428980160e753784ef087aa37f3ead8d2fb8d55d6dd1d82d8e', 'first review verified; second review pending', 0);
