INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.50', 'transliteration', 'sa', 'Latn', 'buddhiyukto jahātīha ubhe sukṛtaduṣkṛte
