INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.50', 'translation', 'en', 'Latn', 'He who has obtained devotion in this world casts off both merit and sin. Therefore apply yourself to devotion devotion in (all) actions is wisdom.', 'telang-1882');
