INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.51', 'original', 'sa', 'Deva', 'कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः।
