INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.51', 'translation', 'en', 'Latn', 'The wise who have obtained devotion cast off the fruit of action and released from the shackles of (repeated)births repair to that seat where there is no unhappiness. When your mind shall have crossed beyond the taint of delusion then will you become indifferent to all that you have heard or will heard. When your mind', 'telang-1882');
