INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.54', 'translation', 'en', 'Latn', 'then will you acquire devotion. What are the characteristics, O Kesava! of one whose mind is steady, and who is intent on contemplation? How should one of steady mind speak, how sit, how move?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.54', 'vedic-scriptures', 'BG2.54', 'Devanagari and IAST digital witness');
