INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.56', 'transliteration', 'sa', 'Latn', 'duḥkheṣvanudvignamanāḥ sukheṣu vigataspṛhaḥ
vītarāgabhayakrodhaḥ sthitadhīrmunirucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.56', 'translation', 'en', 'Latn', 'He whose heart is not agitated in the midst of calamities who has no longing for pleasures and from whom (the feelings of) affection fear and wrath have departed is called a sage of steady mind.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.56', 'vedic-scriptures', 'BG2.56', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.56', 'telang-1882', 'Chapter 2; aligned against BG2.56', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.56', 'दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः।
वीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते ॥', 'duḥkheṣvanudvignamanāḥ sukheṣu vigataspṛhaḥ
vītarāgabhayakrodhaḥ sthitadhīrmunirucyate', 'He whose heart is not agitated in the midst of calamities who has no longing for pleasures and from whom (the feelings of) affection fear and wrath have departed is called a sage of steady mind.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.57', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.57', 2, 57, 'Krishna', '4a05b8a1a810fe110af6a2a5073f070760937b0d5c2becc85870767de2d496d2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.57', 'original', 'sa', 'Deva', 'यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम्।
नाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.57', 'transliteration', 'sa', 'Latn', 'yaḥ sarvatrānabhisnehastattatprāpya śubhāśubham
nābhinandati na dveṣṭi tasya prajñā pratiṣṭhitā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.57', 'translation', 'en', 'Latn', 'His mind is steady, who, being without attachments anywhere, feels no exultation and no aversion on encountering the various agreeable and disagreeable (things of this world).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.57', 'vedic-scriptures', 'BG2.57', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.57', 'telang-1882', 'Chapter 2; aligned against BG2.57', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.57', 'यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम्।
नाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता ॥', 'yaḥ sarvatrānabhisnehastattatprāpya śubhāśubham
nābhinandati na dveṣṭi tasya prajñā pratiṣṭhitā', 'His mind is steady, who, being without attachments anywhere, feels no exultation and no aversion on encountering the various agreeable and disagreeable (things of this world).');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.58', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.58', 2, 58, 'Krishna', '34c397d4351dee96f5b8bcee48967dec1513b91597e36442a63f332103a9f5cc', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.58', 'original', 'sa', 'Deva', 'यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।
इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.58', 'transliteration', 'sa', 'Latn', 'yadā saṃharate cāyaṃ kūrmo.aṅgānīva sarvaśaḥ
indriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.58', 'translation', 'en', 'Latn', 'A man''s mind is steady, when he withdraws his senses from (all) objects of sense, as the tortoise (withdraws) its limbs from all sides.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.58', 'vedic-scriptures', 'BG2.58', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.58', 'telang-1882', 'Chapter 2; aligned against BG2.58', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.58', 'यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।
इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥', 'yadā saṃharate cāyaṃ kūrmo.aṅgānīva sarvaśaḥ
indriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā', 'A man''s mind is steady, when he withdraws his senses from (all) objects of sense, as the tortoise (withdraws) its limbs from all sides.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.59', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.59', 2, 59, 'Krishna', '1a17e2887eeca134fabf5a2704ef277cb86276b94665fb2a7627981afe618377', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.59', 'original', 'sa', 'Deva', 'विषया विनिवर्तन्ते निराहारस्य देहिनः।
रसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.59', 'transliteration', 'sa', 'Latn', 'viṣayā vinivartante nirāhārasya dehinaḥ
rasavarjaṃ raso.apyasya paraṃ dṛṣṭvā nivartate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.59', 'translation', 'en', 'Latn', 'Objects of sense draw back from a person who is abstinent not so the taste (for those objects). But even the taste departs from him, when he has seen the Supreme.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.59', 'vedic-scriptures', 'BG2.59', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.59', 'telang-1882', 'Chapter 2; aligned against BG2.59', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.59', 'विषया विनिवर्तन्ते निराहारस्य देहिनः।
रसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते ॥', 'viṣayā vinivartante nirāhārasya dehinaḥ
rasavarjaṃ raso.apyasya paraṃ dṛṣṭvā nivartate', 'Objects of sense draw back from a person who is abstinent not so the taste (for those objects). But even the taste departs from him, when he has seen the Supreme.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.60', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.60', 2, 60, 'Krishna', '5ef5b55ee91c887440f8ffe63995fd38859df9f4ff6efd6fe180f270ffb277a1', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.60', 'original', 'sa', 'Deva', 'यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः।
इन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.60', 'transliteration', 'sa', 'Latn', 'yatato hyapi kaunteya puruṣasya vipaścitaḥ
indriyāṇi pramāthīni haranti prasabhaṃ manaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.60', 'translation', 'en', 'Latn', 'The boisterous senses, O son of Kuntī! carry away by force the mind even of a wise man, who exerts himself (for final emancipation).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.60', 'vedic-scriptures', 'BG2.60', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.60', 'telang-1882', 'Chapter 2; aligned against BG2.60', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.60', 'यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः।
इन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः ॥', 'yatato hyapi kaunteya puruṣasya vipaścitaḥ
indriyāṇi pramāthīni haranti prasabhaṃ manaḥ', 'The boisterous senses, O son of Kuntī! carry away by force the mind even of a wise man, who exerts himself (for final emancipation).');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.61', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.61', 2, 61, 'Krishna', '83629a5143c63980ebd96e7d7bcbf76e6f5d768da7a94fe3daeec098f799e7c2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.61', 'original', 'sa', 'Deva', 'तानि सर्वाणि संयम्य युक्त आसीत मत्परः।
वशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.61', 'transliteration', 'sa', 'Latn', 'tāni sarvāṇi saṃyamya yukta āsīta matparaḥ
vaśe hi yasyendriyāṇi tasya prajñā pratiṣṭhitā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.61', 'translation', 'en', 'Latn', 'Restraining them all, a man should remain engaged in devotion, making me his only resort. For his mind is steady whose senses are under his control.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.61', 'vedic-scriptures', 'BG2.61', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.61', 'telang-1882', 'Chapter 2; aligned against BG2.61', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.61', 'तानि सर्वाणि संयम्य युक्त आसीत मत्परः।
वशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता ॥', 'tāni sarvāṇi saṃyamya yukta āsīta matparaḥ
vaśe hi yasyendriyāṇi tasya prajñā pratiṣṭhitā', 'Restraining them all, a man should remain engaged in devotion, making me his only resort. For his mind is steady whose senses are under his control.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.62', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.62', 2, 62, 'Krishna', 'c424e91ead208bd5be32dcef312f5a6752025cabf5946b2c5a6ca423c1fb88fc', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.62', 'original', 'sa', 'Deva', 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते।
सङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.62', 'transliteration', 'sa', 'Latn', 'dhyāyato viṣayānpuṃsaḥ saṅgasteṣūpajāyate
saṅgātsañjāyate kāmaḥ kāmātkrodho.abhijāyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.62', 'translation', 'en', 'Latn', 'The man who ponders over objects of sense forms an attachment to them from (that) attachment is produced desire and from desire anger is produced', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.62', 'vedic-scriptures', 'BG2.62', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.62', 'telang-1882', 'Chapter 2; aligned against BG2.62', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.62', 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते।
सङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते ॥', 'dhyāyato viṣayānpuṃsaḥ saṅgasteṣūpajāyate
