INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.63', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.63', 2, 63, 'Krishna', 'a2ae01b83af079e5db64b4b2f9a6cd447f7715781ad63ea592cbeb9c64a4b473', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.63', 'original', 'sa', 'Deva', 'क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः।
स्मृतिभ्रंशाद् बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.63', 'transliteration', 'sa', 'Latn', 'krodhādbhavati sammohaḥ sammohātsmṛtivibhramaḥ
smṛtibhraṃśād buddhināśo buddhināśātpraṇaśyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.63', 'translation', 'en', 'Latn', 'from anger results want of discrimination from want of discrimination, confusion of the memory from confusion of the memory, loss of reason', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.63', 'vedic-scriptures', 'BG2.63', 'Devanagari and IAST digital witness');
