INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.64', 'original', 'sa', 'Deva', 'रागद्वेषविमुक्तैस्तु विषयानिन्द्रियैश्चरन् | (or वियुक्तैस्तु)
आत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.64', 'transliteration', 'sa', 'Latn', 'rāgadveṣavimuktaistu viṣayānindriyaiścaran
orviyuktaistu ātmavaśyairvidheyātmā prasādamadhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.64', 'translation', 'en', 'Latn', 'and in consequence of loss of reason. he is utterly ruined. But the self-restrained man who moves among objects with senses under the control of his own self and free from affection and aversion obtains tranquillity. When there is tranquillity', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.64', 'vedic-scriptures', 'BG2.64', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.64', 'telang-1882', 'Chapter 2; aligned against BG2.64', 'English translation witness');
