INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.65', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.65', 2, 65, 'Krishna', '1021d89b587d155d41e835288830e0e24db6e8b096bff482aa0682a76df1fb41', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.65', 'original', 'sa', 'Deva', 'प्रसादे सर्वदुःखानां हानिरस्योपजायते।
प्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.65', 'transliteration', 'sa', 'Latn', 'prasāde sarvaduḥkhānāṃ hānirasyopajāyate
prasannacetaso hyāśu buddhiḥ paryavatiṣṭhate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.65', 'translation', 'en', 'Latn', 'all his miseries are destroyed for the mind of him whose heart is tranquil soon becomes steady.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.65', 'vedic-scriptures', 'BG2.65', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.65', 'telang-1882', 'Chapter 2; aligned against BG2.65', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.65', 'प्रसादे सर्वदुःखानां हानिरस्योपजायते।
प्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते ॥', 'prasāde sarvaduḥkhānāṃ hānirasyopajāyate
prasannacetaso hyāśu buddhiḥ paryavatiṣṭhate', 'all his miseries are destroyed for the mind of him whose heart is tranquil soon becomes steady.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.66', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.66', 2, 66, 'Krishna', '68b4069d9aa96b6e78f14370fd8658314ed0051a36a42c319f85a0ca304e046d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.66', 'original', 'sa', 'Deva', 'नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना।
न चाभावयतः शान्तिरशान्तस्य कुतः सुखम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.66', 'transliteration', 'sa', 'Latn', 'nāsti buddhirayuktasya na cāyuktasya bhāvanā
na cābhāvayataḥ śāntiraśāntasya kutaḥ sukham', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.66', 'translation', 'en', 'Latn', 'He who is not self-restrained has no steadiness of mind nor has he who is not self-restrained perseverance in the pursuit of self-knowledge there is no tranquillity for him who does not persevere in the pursuit of self-knowledge and whence can there be happiness for one who is not tranquil? For the heart which follows the rambling senses leads away his judgment', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.66', 'vedic-scriptures', 'BG2.66', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.66', 'telang-1882', 'Chapter 2; aligned against BG2.66', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.66', 'नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना।
न चाभावयतः शान्तिरशान्तस्य कुतः सुखम् ॥', 'nāsti buddhirayuktasya na cāyuktasya bhāvanā
na cābhāvayataḥ śāntiraśāntasya kutaḥ sukham', 'He who is not self-restrained has no steadiness of mind nor has he who is not self-restrained perseverance in the pursuit of self-knowledge there is no tranquillity for him who does not persevere in the pursuit of self-knowledge and whence can there be happiness for one who is not tranquil? For the heart which follows the rambling senses leads away his judgment');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.67', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.67', 2, 67, 'Krishna', 'ef3f82271bb37754910091e08aa5d9a1e6f5b32c3c982ceae6b42ecd22686c78', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.67', 'original', 'sa', 'Deva', 'इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते।
तदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.67', 'transliteration', 'sa', 'Latn', 'indriyāṇāṃ hi caratāṃ yanmano.anuvidhīyate
tadasya harati prajñāṃ vāyurnāvamivāmbhasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.67', 'translation', 'en', 'Latn', 'as the wind leads a boat astray upon the waters.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.67', 'vedic-scriptures', 'BG2.67', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.67', 'telang-1882', 'Chapter 2; aligned against BG2.67', 'English translation witness');
