INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.68', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.68', 2, 68, 'Krishna', '5c5f9125e9e543c65e2ae84c7ea245cda4bfe5f37675c031576d57dc2d26d454', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.68', 'original', 'sa', 'Deva', 'तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः।
इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.68', 'transliteration', 'sa', 'Latn', 'tasmādyasya mahābāho nigṛhītāni sarvaśaḥ
indriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.68', 'translation', 'en', 'Latn', 'Therefore, O you of mighty arms! his mind is steady whose senses are restrained on all sides from objects of sense.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.68', 'vedic-scriptures', 'BG2.68', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.68', 'telang-1882', 'Chapter 2; aligned against BG2.68', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.68', 'तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः।
इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥', 'tasmādyasya mahābāho nigṛhītāni sarvaśaḥ
indriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā', 'Therefore, O you of mighty arms! his mind is steady whose senses are restrained on all sides from objects of sense.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.69', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.69', 2, 69, 'Krishna', '8e2ada54f68e4431e951dce0c46dc9dd5c3e78ac53d39373492f6c5ddaf17f5b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.69', 'original', 'sa', 'Deva', 'या निशा सर्वभूतानां तस्यां जागर्ति संयमी।
यस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.69', 'transliteration', 'sa', 'Latn', 'yā niśā sarvabhūtānāṃ tasyāṃ jāgarti saṃyamī
yasyāṃ jāgrati bhūtāni sā niśā paśyato muneḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.69', 'translation', 'en', 'Latn', 'The self-restrained man is awake, when it is night for all beings and when all beings are awake, that is the night of the right-seeing sage.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.69', 'vedic-scriptures', 'BG2.69', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.69', 'telang-1882', 'Chapter 2; aligned against BG2.69', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.69', 'या निशा सर्वभूतानां तस्यां जागर्ति संयमी।
यस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः ॥', 'yā niśā sarvabhūtānāṃ tasyāṃ jāgarti saṃyamī
yasyāṃ jāgrati bhūtāni sā niśā paśyato muneḥ', 'The self-restrained man is awake, when it is night for all beings and when all beings are awake, that is the night of the right-seeing sage.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.70', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.70', 2, 70, 'Krishna', '99bfa2a31022aae39e35d04169c1b49a429bbe1824ac85a6b16640867f62c4cd', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.70', 'original', 'sa', 'Deva', 'आपूर्यमाणमचलप्रतिष्ठं
समुद्रमापः प्रविशन्ति यद्वत्।
तद्वत्कामा यं प्रविशन्ति सर्वे
स शान्तिमाप्नोति न कामकामी ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.70', 'transliteration', 'sa', 'Latn', 'āpūryamāṇamacalapratiṣṭhaṃ samudramāpaḥ praviśanti yadvat
tadvatkāmā yaṃ praviśanti sarve sa śāntimāpnoti na kāmakāmī', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.70', 'translation', 'en', 'Latn', 'He into whom all objects of desire enter, as waters enter the ocean, which, (though) replenished, (still) keeps its position unmoved,-he only obtains tranquillity not he who desires (those) objects of desire.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.70', 'vedic-scriptures', 'BG2.70', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.70', 'telang-1882', 'Chapter 2; aligned against BG2.70', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.70', 'आपूर्यमाणमचलप्रतिष्ठं
समुद्रमापः प्रविशन्ति यद्वत्।
तद्वत्कामा यं प्रविशन्ति सर्वे
स शान्तिमाप्नोति न कामकामी ॥', 'āpūryamāṇamacalapratiṣṭhaṃ samudramāpaḥ praviśanti yadvat
tadvatkāmā yaṃ praviśanti sarve sa śāntimāpnoti na kāmakāmī', 'He into whom all objects of desire enter, as waters enter the ocean, which, (though) replenished, (still) keeps its position unmoved,-he only obtains tranquillity not he who desires (those) objects of desire.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.71', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.71', 2, 71, 'Krishna', '33ada40caefd2c2735cbee7c3ecf7e65c95d022a60cd6182fe458751b95f4c15', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.71', 'original', 'sa', 'Deva', 'विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः।
निर्ममो निरहङ्कारः स शान्तिमधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.71', 'transliteration', 'sa', 'Latn', 'vihāya kāmānyaḥ sarvānpumāṃścarati niḥspṛhaḥ
nirmamo nirahaṅkāraḥ sa śāntimadhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.71', 'translation', 'en', 'Latn', 'The man who, casting off all desires, lives free from attachments, who is free from egoism, and from (the feeling that this or that is) mine, obtains tranquillity.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.71', 'vedic-scriptures', 'BG2.71', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.71', 'telang-1882', 'Chapter 2; aligned against BG2.71', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.71', 'विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः।
