INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.2.72', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.2.72', 2, 72, 'Krishna', 'bcd99ab07e71987dd60eb04d02547a130e40110de899bbaed53d5417e8c46854', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.72', 'original', 'sa', 'Deva', 'एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति।
स्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.72', 'transliteration', 'sa', 'Latn', 'eṣā brāhmī sthitiḥ pārtha naināṃ prāpya vimuhyati
sthitvāsyāmantakāle.api brahmanirvāṇamṛcchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.2.72', 'translation', 'en', 'Latn', 'This, O son of Pṛthā! is the Brahmic state attaining to this, one is never deluded and remaining in it in (one''s) last moments, one attains ( brahma - nirvāṇa ) the Brahmic bliss.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.72', 'vedic-scriptures', 'BG2.72', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.2.72', 'telang-1882', 'Chapter 2; aligned against BG2.72', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.2.72', 'एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति।
स्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति ॥', 'eṣā brāhmī sthitiḥ pārtha naināṃ prāpya vimuhyati
