INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.1', 3, 1, 'Arjuna', 'a75f49404a47eb756945032a7635b65f6894947c8f9db1bd46f5663331a0dfb2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.1', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
ज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन।
तत्किं कर्मणि घोरे मां नियोजयसि केशव ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.1', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
jyāyasī cetkarmaṇaste matā buddhirjanārdana
tatkiṃ karmaṇi ghore māṃ niyojayasi keśava', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.1', 'translation', 'en', 'Latn', 'If, O Ganārdana! devotion is deemed by you to be superior to action, then why, O Kesava! do you prompt me to (this) fearful action?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.1', 'vedic-scriptures', 'BG3.1', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.1', 'telang-1882', 'Chapter 3; aligned against BG3.1', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.1', 'अर्जुन उवाच।
ज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन।
तत्किं कर्मणि घोरे मां नियोजयसि केशव ॥', 'arjuna uvāca
jyāyasī cetkarmaṇaste matā buddhirjanārdana
tatkiṃ karmaṇi ghore māṃ niyojayasi keśava', 'If, O Ganārdana! devotion is deemed by you to be superior to action, then why, O Kesava! do you prompt me to (this) fearful action?');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.2', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.2', 3, 2, 'Arjuna', '4597097c54f91a26eb1e3a818de92b8adcee3949ceb86bef813c2e424aecc5f7', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.2', 'original', 'sa', 'Deva', 'व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे।
तदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.2', 'transliteration', 'sa', 'Latn', 'vyāmiśreṇeva vākyena buddhiṃ mohayasīva me
tadekaṃ vada niścitya yena śreyo.ahamāpnuyām', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.2', 'translation', 'en', 'Latn', 'You seem, indeed, to confuse my mind by equivocal words. Therefore, declare one thing determinately, by which I may attain the highest good.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.2', 'vedic-scriptures', 'BG3.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.2', 'telang-1882', 'Chapter 3; aligned against BG3.2', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.2', 'व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे।
तदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् ॥', 'vyāmiśreṇeva vākyena buddhiṃ mohayasīva me
tadekaṃ vada niścitya yena śreyo.ahamāpnuyām', 'You seem, indeed, to confuse my mind by equivocal words. Therefore, declare one thing determinately, by which I may attain the highest good.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.3', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.3', 3, 3, 'Krishna', '186ce5784b5531be1c8fc49b52ed37ef4eb6870b18d92a6eaa35985f9144614c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.3', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
लोकेऽस्मिन् द्विविधा निष्ठा पुरा प्रोक्ता मयानघ।
ज्ञानयोगेन साङ्ख्यानां कर्मयोगेन योगिनाम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.3', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
