INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.3', 'translation', 'en', 'Latn', 'O sinless one! I have already declared, that in this world there is a twofold path—that of the Sāṅkhyas by devotion in the shape of (true) knowledge and that of the Yogins by devotion in the shape of action.', 'telang-1882');
