INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.4', 'transliteration', 'sa', 'Latn', 'na karmaṇāmanārambhānnaiṣkarmyaṃ puruṣo.aśnute
