INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.4', 'translation', 'en', 'Latn', 'A man does not attain freedom from action merely by not engaging in action nor does he attain perfection by mere renunciation. For nobody ever remains even for an instant without performing some action', 'telang-1882');
