INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.8', 'original', 'sa', 'Deva', 'नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः।
शरीरयात्रापि च ते न प्रसिद्ध्येदकर्मणः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.8', 'transliteration', 'sa', 'Latn', 'niyataṃ kuru karma tvaṃ karma jyāyo hyakarmaṇaḥ
śarīrayātrāpi ca te na prasiddhyedakarmaṇaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.8', 'translation', 'en', 'Latn', 'is far superior. Do you perform prescribed action, for action is better than inaction, and the support of your body, too, cannot be accomplished with inaction.', 'telang-1882');
