INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.9', 'transliteration', 'sa', 'Latn', 'yajñārthātkarmaṇo.anyatra loko.ayaṃ karmabandhanaḥ
