INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.9', 'translation', 'en', 'Latn', 'This world is fettered by all action other than action for the purpose of the sacrifice. Therefore, O son of Kuntī ! do you, casting off attachment, perform action for that purpose.', 'telang-1882');
