INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.10', 'translation', 'en', 'Latn', 'The Creator, having in olden times created men together with the sacrifice, said: ''Propagate with this. May it be the giver to you of the things you desire.', 'telang-1882');
