INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.12', 'original', 'sa', 'Deva', 'इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः।
