INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.12', 'transliteration', 'sa', 'Latn', 'iṣṭānbhogānhi vo devā dāsyante yajñabhāvitāḥ
tairdattānapradāyaibhyo yo bhuṅkte stena eva saḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.12', 'translation', 'en', 'Latn', 'the gods will give you the enjoyments you desire. And he who enjoys himself without giving them what they have given is indeed a thief.''', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.12', 'vedic-scriptures', 'BG3.12', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.12', 'telang-1882', 'Chapter 3; aligned against BG3.12', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.12', 'इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः।
तैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः ॥', 'iṣṭānbhogānhi vo devā dāsyante yajñabhāvitāḥ
tairdattānapradāyaibhyo yo bhuṅkte stena eva saḥ', 'the gods will give you the enjoyments you desire. And he who enjoys himself without giving them what they have given is indeed a thief.''');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.13', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.13', 3, 13, 'Krishna', '78fffc55da21000067e73a0f176b871ca98f2fe1fd63061fe527af4eec120d90', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.13', 'original', 'sa', 'Deva', 'यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः।
भुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.13', 'transliteration', 'sa', 'Latn', 'yajñaśiṣṭāśinaḥ santo mucyante sarvakilbiṣaiḥ
bhuñjate te tvaghaṃ pāpā ye pacantyātmakāraṇāt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.13', 'translation', 'en', 'Latn', 'The good who eat the leavings of a sacrifice are released from all sins. But the unrighteous ones who prepare food for themselves only', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.13', 'vedic-scriptures', 'BG3.13', 'Devanagari and IAST digital witness');
