INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.15', 'original', 'sa', 'Deva', 'कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम्।
