INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.15', 'transliteration', 'sa', 'Latn', 'karma brahmodbhavaṃ viddhi brahmākṣarasamudbhavam
