INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.15', 'translation', 'en', 'Latn', 'know that action has its source in the Vedas the Vedas come from the Indestructible. Therefore the all-comprehending Vedas are always concerned with sacrifices.', 'telang-1882');
