INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.16', 'original', 'sa', 'Deva', 'एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः।
अघायुरिन्द्रियारामो मोघं पार्थ स जीवति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.16', 'transliteration', 'sa', 'Latn', 'evaṃ pravartitaṃ cakraṃ nānuvartayatīha yaḥ
