INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.16', 'translation', 'en', 'Latn', 'He who in this world does not turn round the wheel revolving thus is of sinful life indulging his senses', 'telang-1882');
