INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.17', 'translation', 'en', 'Latn', 'and O son of Pṛthā! he lives in vain. But the man who is attached to his self only who is contented in his self and is pleased with his self has nothing to do.', 'telang-1882');
