INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.18', 'original', 'sa', 'Deva', 'नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन।
न चास्य सर्वभूतेषु कश्चिदर्थव्यपाश्रयः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.18', 'transliteration', 'sa', 'Latn', 'naiva tasya kṛtenārtho nākṛteneha kaścana
