INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.18', 'translation', 'en', 'Latn', 'He has no interest at all in what is done, and none whatever in what is not done, in this world nor is any interest of his dependent on any being.', 'telang-1882');
