INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.19', 'translation', 'en', 'Latn', 'Therefore always perform action, which must be performed, without attachment. For a man, performing action without attachment, attains the Supreme.', 'telang-1882');
