INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.20', 'transliteration', 'sa', 'Latn', 'karmaṇaiva hi saṃsiddhimāsthitā janakādayaḥ
