INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.20', 'translation', 'en', 'Latn', 'By action alone, did Janaka and the rest work for perfection. And having regard also to the keeping of people (to their duties) you should perform action.', 'telang-1882');
