INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.22', 'original', 'sa', 'Deva', 'न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किञ्चन।
नानवाप्तमवाप्तव्यं वर्त एव च कर्मणि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.22', 'transliteration', 'sa', 'Latn', 'na me pārthāsti kartavyaṃ triṣu lokeṣu kiñcana
nānavāptamavāptavyaṃ varta eva ca karmaṇi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.22', 'translation', 'en', 'Latn', 'There is nothing, O son of Pṛthā! for me to do in (all) the three worlds, nothing to acquire which has not been acquired. Still I do engage in action. For should I at any time not engage without sloth in action', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.22', 'vedic-scriptures', 'BG3.22', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.22', 'telang-1882', 'Chapter 3; aligned against BG3.22', 'English translation witness');
