INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.23', 'original', 'sa', 'Deva', 'यदि ह्यहं न वर्तेयं जातु कर्मण्यतन्द्रितः।
मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.23', 'transliteration', 'sa', 'Latn', 'yadi hyahaṃ na varteyaṃ jātu karmaṇyatandritaḥ
mama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.23', 'translation', 'en', 'Latn', 'men would follow in my path from all sides', 'telang-1882');
