INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.24', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.24', 3, 24, 'Krishna', '315069397f510b6e35a154b60e5653793712868a11c88fe0709d6d2da7cc2386', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.24', 'original', 'sa', 'Deva', 'उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम्।
सङ्करस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.24', 'transliteration', 'sa', 'Latn', 'utsīdeyurime lokā na kuryāṃ karma cedaham
saṅkarasya ca kartā syāmupahanyāmimāḥ prajāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.24', 'translation', 'en', 'Latn', 'O son of Pṛthā! If I did not perform actions, these worlds would be destroyed, I should be the cause of caste interminglings and I should be ruining these people. As the ignorant act', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.24', 'vedic-scriptures', 'BG3.24', 'Devanagari and IAST digital witness');
