INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.26', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.26', 3, 26, 'Krishna', 'f2f6e297b1c9e9a21794be42815207fff540cff101b490a26716c958518f64ae', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.26', 'original', 'sa', 'Deva', 'न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम्।
जोषयेत्सर्वकर्माणि विद्वान्युक्तः समाचरन् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.26', 'transliteration', 'sa', 'Latn', 'na buddhibhedaṃ janayedajñānāṃ karmasaṅginām
joṣayetsarvakarmāṇi vidvānyuktaḥ samācaran', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.26', 'translation', 'en', 'Latn', 'wishing to keep the people (to their duties). A wise man should not shake the convictions of the ignorant who are attached to action but acting with devotion (himself ) should make them apply themselves to all action.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.26', 'vedic-scriptures', 'BG3.26', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.26', 'telang-1882', 'Chapter 3; aligned against BG3.26', 'English translation witness');
