INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.27', 'original', 'sa', 'Deva', 'प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः।
अहङ्कारविमूढात्मा कर्ताहमिति मन्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.27', 'transliteration', 'sa', 'Latn', 'prakṛteḥ kriyamāṇāni guṇaiḥ karmāṇi sarvaśaḥ
ahaṅkāravimūḍhātmā kartāhamiti manyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.27', 'translation', 'en', 'Latn', 'He whose mind is deluded by egoism thinks himself the doer of the actions which', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.27', 'vedic-scriptures', 'BG3.27', 'Devanagari and IAST digital witness');
