INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.29', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.29', 3, 29, 'Krishna', 'f65149239d5af4eae7afeb9532eebec519c0810b20ce2ccb5f1b0884d6117105', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.29', 'original', 'sa', 'Deva', 'प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु।
तानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.29', 'transliteration', 'sa', 'Latn', 'prakṛterguṇasammūḍhāḥ sajjante guṇakarmasu
tānakṛtsnavido mandānkṛtsnavinna vicālayet', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.29', 'translation', 'en', 'Latn', 'believing that qualities deal with qualities. But those who are deluded by the qualities of nature form attachments to the actions of the qualities. A man of perfect knowledge should not shake these men of imperfect knowledge (in their convictions).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.29', 'vedic-scriptures', 'BG3.29', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.29', 'telang-1882', 'Chapter 3; aligned against BG3.29', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.29', 'प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु।
