INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.31', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.31', 3, 31, 'Krishna', '93b4922f379bc917a92e2de1b555e7534f385cbd8919be0fdd4be7bd3eca0038', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.31', 'original', 'sa', 'Deva', 'ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः।
श्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.31', 'transliteration', 'sa', 'Latn', 'ye me matamidaṃ nityamanutiṣṭhanti mānavāḥ
śraddhāvanto.anasūyanto mucyante te.api karmabhiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.31', 'translation', 'en', 'Latn', 'Even those men who always act on this opinion of mine full of faith and without carping are released from all actions. But those who carp at my opinion and do not act upon it', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.31', 'vedic-scriptures', 'BG3.31', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.31', 'telang-1882', 'Chapter 3; aligned against BG3.31', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.31', 'ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः।
श्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः ॥', 'ye me matamidaṃ nityamanutiṣṭhanti mānavāḥ
śraddhāvanto.anasūyanto mucyante te.api karmabhiḥ', 'Even those men who always act on this opinion of mine full of faith and without carping are released from all actions. But those who carp at my opinion and do not act upon it');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.32', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.32', 3, 32, 'Krishna', '0d8c951a5fbf7c1c7620cc8eed8b19338392f184e45cceaa163f3b4db09beef9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.32', 'original', 'sa', 'Deva', 'ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम्।
सर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.32', 'transliteration', 'sa', 'Latn', 'ye tvetadabhyasūyanto nānutiṣṭhanti me matam
sarvajñānavimūḍhāṃstānviddhi naṣṭānacetasaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.32', 'translation', 'en', 'Latn', 'know them to be devoid of discrimination deluded as regards all knowledge', 'telang-1882');
