INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.33', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.33', 3, 33, 'Krishna', '25f269a1952a33c08e12e9ae5fb4a26959bdeab28c2fec5310e57302762c3677', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.33', 'original', 'sa', 'Deva', 'सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि।
प्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.33', 'transliteration', 'sa', 'Latn', 'sadṛśaṃ ceṣṭate svasyāḥ prakṛterjñānavānapi
prakṛtiṃ yānti bhūtāni nigrahaḥ kiṃ kariṣyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.33', 'translation', 'en', 'Latn', 'and ruined. Even a man of knowledge acts consonantly to his own nature. All beings follow nature. What will restraint effect?', 'telang-1882');
