INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.34', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.34', 3, 34, 'Krishna', '6a3a1eeb0c1311d048dc7fa53627b89169a8ed5134c66aae473924be2160acb9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.34', 'original', 'sa', 'Deva', 'इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ।
तयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.34', 'transliteration', 'sa', 'Latn', 'indriyasyendriyasyārthe rāgadveṣau vyavasthitau
tayorna vaśamāgacchettau hyasya paripanthinau', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.34', 'translation', 'en', 'Latn', 'Every sense has its affections and aversions towards its objects fixed. One should not become subject to them, for they are one''s opponents.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.34', 'vedic-scriptures', 'BG3.34', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.34', 'telang-1882', 'Chapter 3; aligned against BG3.34', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.34', 'इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ।
तयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ ॥', 'indriyasyendriyasyārthe rāgadveṣau vyavasthitau
tayorna vaśamāgacchettau hyasya paripanthinau', 'Every sense has its affections and aversions towards its objects fixed. One should not become subject to them, for they are one''s opponents.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.35', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.35', 3, 35, 'Krishna', '82ee58e47168b7d0b468459b756253a598817c76c1f0b5528dfa6591c7b441f6', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.35', 'original', 'sa', 'Deva', 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।
स्वधर्मे निधनं श्रेयः परधर्मो भयावहः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.35', 'transliteration', 'sa', 'Latn', 'śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt
svadharme nidhanaṃ śreyaḥ paradharmo bhayāvahaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.35', 'translation', 'en', 'Latn', 'One''s own duty, though defective, is better than another''s duty well performed. Death in (performing) one''s own duty is preferable the (performance of the) duty of others is dangerous.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.35', 'vedic-scriptures', 'BG3.35', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.35', 'telang-1882', 'Chapter 3; aligned against BG3.35', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.35', 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।
स्वधर्मे निधनं श्रेयः परधर्मो भयावहः ॥', 'śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt
svadharme nidhanaṃ śreyaḥ paradharmo bhayāvahaḥ', 'One''s own duty, though defective, is better than another''s duty well performed. Death in (performing) one''s own duty is preferable the (performance of the) duty of others is dangerous.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.36', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.36', 3, 36, 'Arjuna', '07414f2c377b28780a7ee1744a2b9ee90d4a5fb905ad2d522456e3ab563cb802', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.36', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
अथ केन प्रयुक्तोऽयं पापं चरति पूरुषः।
अनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.36', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
atha kena prayukto.ayaṃ pāpaṃ carati pūruṣaḥ
anicchannapi vārṣṇeya balādiva niyojitaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.36', 'translation', 'en', 'Latn', 'But by whom, O descendant of Vṛṣṇi! is man impelled, even though unwilling, and, as it were, constrained by force, to commit sin? The Deity said:', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.36', 'vedic-scriptures', 'BG3.36', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.36', 'telang-1882', 'Chapter 3; aligned against BG3.36', 'English translation witness');
