INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.39', 'original', 'sa', 'Deva', 'आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा।
कामरूपेण कौन्तेय दुष्पूरेणानलेन च ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.39', 'transliteration', 'sa', 'Latn', 'āvṛtaṃ jñānametena jñānino nityavairiṇā
