INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.39', 'translation', 'en', 'Latn', 'the fœtus by the womb so is this enveloped by desire. Knowledge, O son of Kuntī! is enveloped by this constant foe of the man of knowledge, in the shape of desire, which is like a fire and insatiable.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.39', 'vedic-scriptures', 'BG3.39', 'Devanagari and IAST digital witness');
