INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.40', 'original', 'sa', 'Deva', 'इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते।
एतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.40', 'transliteration', 'sa', 'Latn', 'indriyāṇi mano buddhirasyādhiṣṭhānamucyate
