INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.40', 'translation', 'en', 'Latn', 'The senses, the mind, and the understanding are said to be its seat with these it deludes the embodied (self) after enveloping knowledge.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.40', 'vedic-scriptures', 'BG3.40', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.40', 'telang-1882', 'Chapter 3; aligned against BG3.40', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.40', 'इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते।
