INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.41', 'original', 'sa', 'Deva', 'तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ।
पाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.41', 'transliteration', 'sa', 'Latn', 'tasmāttvamindriyāṇyādau niyamya bharatarṣabha
pāpmānaṃ prajahi hyenaṃ jñānavijñānanāśanam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.41', 'translation', 'en', 'Latn', 'Therefore, O chief of the descendants of Bharata! first restrain your senses, then cast off this sinful thing which destroys knowledge and experience.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.41', 'vedic-scriptures', 'BG3.41', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.41', 'telang-1882', 'Chapter 3; aligned against BG3.41', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.41', 'तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ।
पाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम् ॥', 'tasmāttvamindriyāṇyādau niyamya bharatarṣabha
pāpmānaṃ prajahi hyenaṃ jñānavijñānanāśanam', 'Therefore, O chief of the descendants of Bharata! first restrain your senses, then cast off this sinful thing which destroys knowledge and experience.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.42', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.42', 3, 42, 'Krishna', '65644d2161ce6be34aeb0de3fd366cb95f3a01f7490ca1e6ac8de690efedf8f9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.42', 'original', 'sa', 'Deva', 'इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः।
मनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.42', 'transliteration', 'sa', 'Latn', 'indriyāṇi parāṇyāhurindriyebhyaḥ paraṃ manaḥ
manasastu parā buddhiryo buddheḥ paratastu saḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.42', 'translation', 'en', 'Latn', 'It has been said, Great are the senses, greater than the senses is the mind, greater than the mind is the understanding. What is greater than the understanding is that.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.42', 'vedic-scriptures', 'BG3.42', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.42', 'telang-1882', 'Chapter 3; aligned against BG3.42', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.42', 'इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः।
मनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः ॥', 'indriyāṇi parāṇyāhurindriyebhyaḥ paraṃ manaḥ
manasastu parā buddhiryo buddheḥ paratastu saḥ', 'It has been said, Great are the senses, greater than the senses is the mind, greater than the mind is the understanding. What is greater than the understanding is that.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.3.43', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.3.43', 3, 43, 'Krishna', '95bca8f62653b298c5a65d742cfa10b0d86e94a4772a7fc2e920e419ed4b768b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.43', 'original', 'sa', 'Deva', 'एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना।
जहि शत्रुं महाबाहो कामरूपं दुरासदम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.43', 'transliteration', 'sa', 'Latn', 'evaṃ buddheḥ paraṃ buddhvā saṃstabhyātmānamātmanā
jahi śatruṃ mahābāho kāmarūpaṃ durāsadam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.3.43', 'translation', 'en', 'Latn', 'Thus knowing that which is higher than the understanding, and restraining (your)self by (your)self, O you of mighty arms! destroy this unmanageable enemy in the shape of desire.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.43', 'vedic-scriptures', 'BG3.43', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.3.43', 'telang-1882', 'Chapter 3; aligned against BG3.43', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.3.43', 'एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना।
जहि शत्रुं महाबाहो कामरूपं दुरासदम् ॥', 'evaṃ buddheḥ paraṃ buddhvā saṃstabhyātmānamātmanā
jahi śatruṃ mahābāho kāmarūpaṃ durāsadam', 'Thus knowing that which is higher than the understanding, and restraining (your)self by (your)self, O you of mighty arms! destroy this unmanageable enemy in the shape of desire.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.1', 4, 1, 'Krishna', '0398350c686307fe9b9b3249a0623ce9b072eb0e8814dd8b3a6a5513efb6c0c5', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.1', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
इमं विवस्वते योगं प्रोक्तवानहमव्ययम्।
विवस्वान्मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.1', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
imaṃ vivasvate yogaṃ proktavānahamavyayam
vivasvānmanave prāha manurikṣvākave.abravīt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.1', 'translation', 'en', 'Latn', 'This everlasting (system of) devotion I declared to the sun, the sun declared it to Manu , and Manu communicated it to Ikṣvāku. Coming thus by steps', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.1', 'vedic-scriptures', 'BG4.1', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.1', 'telang-1882', 'Chapter 4; aligned against BG4.1', 'English translation witness');
