INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.3', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.3', 4, 3, 'Krishna', 'baf705209f2efd869266628f900e9e42f2f4758922a34314e3a530fb6073483d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.3', 'original', 'sa', 'Deva', 'स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः।
भक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.3', 'transliteration', 'sa', 'Latn', 'sa evāyaṃ mayā te.adya yogaḥ proktaḥ purātanaḥ
bhakto.asi me sakhā ceti rahasyaṃ hyetaduttamam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.3', 'translation', 'en', 'Latn', 'seeing. that you are my devotee and friend for it is the highest mystery.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.3', 'vedic-scriptures', 'BG4.3', 'Devanagari and IAST digital witness');
