INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.3', 'स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः।
भक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम् ॥', 'sa evāyaṃ mayā te.adya yogaḥ proktaḥ purātanaḥ
