INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.4', 4, 4, 'Arjuna', 'a7227ef07c2413a6c5fed9599f0da90486a083e632acc5f6993f8cd6dcf9c18a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.4', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
अपरं भवतो जन्म परं जन्म विवस्वतः।
कथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.4', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
aparaṃ bhavato janma paraṃ janma vivasvataḥ
kathametadvijānīyāṃ tvamādau proktavāniti', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.4', 'translation', 'en', 'Latn', 'Later is your birth the birth of the sun is prior. How then shall I understand that you declared (this) first?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.4', 'vedic-scriptures', 'BG4.4', 'Devanagari and IAST digital witness');
