INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.5', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
बहूनि मे व्यतीतानि जन्मानि तव चार्जुन।
तान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.5', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
bahūni me vyatītāni janmāni tava cārjuna
tānyahaṃ veda sarvāṇi na tvaṃ vettha parantapa', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.5', 'translation', 'en', 'Latn', 'I have passed through many births, O Arjuna I and you also. I know them all, but you, O terror of (your) foes! do not know them.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.5', 'vedic-scriptures', 'BG4.5', 'Devanagari and IAST digital witness');
