INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.7', 'translation', 'en', 'Latn', 'Whensoever, O descendant of Bharata! piety languishes, and impiety is in the ascendant, I create myself.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.7', 'vedic-scriptures', 'BG4.7', 'Devanagari and IAST digital witness');
