INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.8', 'translation', 'en', 'Latn', 'I am born age after age, for the protection of the good, for the destruction of evil-doers, and the establishment of piety.', 'telang-1882');
