INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.9', 'original', 'sa', 'Deva', 'जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः।
त्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.9', 'transliteration', 'sa', 'Latn', 'janma karma ca me divyamevaṃ yo vetti tattvataḥ
tyaktvā dehaṃ punarjanma naiti māmeti so.arjuna', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.9', 'translation', 'en', 'Latn', 'Whoever truly knows thus my divine birth and work, casts off (this) body and is not born again. He comes to me O Arjuna! Many from whom affection', 'telang-1882');
