INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.11', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.11', 4, 11, 'Krishna', '169ea94de197557e9bdcc0279a3397e5736d4c7881688aa0d645afd31dd5fe42', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.11', 'original', 'sa', 'Deva', 'ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम्।
मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.11', 'transliteration', 'sa', 'Latn', 'ye yathā māṃ prapadyante tāṃstathaiva bhajāmyaham
mama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.11', 'translation', 'en', 'Latn', 'and wrath have departed who are full of me who depend on me and who are purified by the penance of knowledge have come into my essence. I serve men in the way in which they approach me. In every way, O son of Pṛthā! men follow in my path.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.11', 'vedic-scriptures', 'BG4.11', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.11', 'telang-1882', 'Chapter 4; aligned against BG4.11', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.11', 'ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम्।
मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥', 'ye yathā māṃ prapadyante tāṃstathaiva bhajāmyaham
mama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ', 'and wrath have departed who are full of me who depend on me and who are purified by the penance of knowledge have come into my essence. I serve men in the way in which they approach me. In every way, O son of Pṛthā! men follow in my path.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.12', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.12', 4, 12, 'Krishna', '067f36d2393d941b5ec27e3db291c4685d7a4a1b732efb7240432ed4af38c9bc', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.12', 'original', 'sa', 'Deva', 'काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः।
क्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.12', 'transliteration', 'sa', 'Latn', 'kāṅkṣantaḥ karmaṇāṃ siddhiṃ yajanta iha devatāḥ
kṣipraṃ hi mānuṣe loke siddhirbhavati karmajā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.12', 'translation', 'en', 'Latn', 'Desiring the success of actions, men in this world worship the divinities, for in this world of mortals, the success produced by action is soon obtained.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.12', 'vedic-scriptures', 'BG4.12', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.12', 'telang-1882', 'Chapter 4; aligned against BG4.12', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.12', 'काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः।
क्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा ॥', 'kāṅkṣantaḥ karmaṇāṃ siddhiṃ yajanta iha devatāḥ
kṣipraṃ hi mānuṣe loke siddhirbhavati karmajā', 'Desiring the success of actions, men in this world worship the divinities, for in this world of mortals, the success produced by action is soon obtained.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.13', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.13', 4, 13, 'Krishna', 'e69748a9a0d0f54be817664fe0f22493ee3c1116e53d744dca1a6184ca4a9449', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.13', 'original', 'sa', 'Deva', 'चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः।
तस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.13', 'transliteration', 'sa', 'Latn', 'cāturvarṇyaṃ mayā sṛṣṭaṃ guṇakarmavibhāgaśaḥ
tasya kartāramapi māṃ viddhyakartāramavyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.13', 'translation', 'en', 'Latn', 'The fourfold division of castes was created by me according to the apportionment of qualities and duties. But though I am its author know me to be inexhaustible and not the author.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.13', 'vedic-scriptures', 'BG4.13', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.13', 'telang-1882', 'Chapter 4; aligned against BG4.13', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.13', 'चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः।
तस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम् ॥', 'cāturvarṇyaṃ mayā sṛṣṭaṃ guṇakarmavibhāgaśaḥ
tasya kartāramapi māṃ viddhyakartāramavyayam', 'The fourfold division of castes was created by me according to the apportionment of qualities and duties. But though I am its author know me to be inexhaustible and not the author.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.14', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.14', 4, 14, 'Krishna', 'ae9394222332b097ef05dd82722475bfcf7877f04efa49d91b18ff8d54d91c40', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.14', 'original', 'sa', 'Deva', 'न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा।
इति मां योऽभिजानाति कर्मभिर्न स बध्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.14', 'transliteration', 'sa', 'Latn', 'na māṃ karmāṇi limpanti na me karmaphale spṛhā
iti māṃ yo.abhijānāti karmabhirna sa badhyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.14', 'translation', 'en', 'Latn', 'Actions defile me not. I have no attachment to the fruit of actions. He who knows me thus is not tied down by actions.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.14', 'vedic-scriptures', 'BG4.14', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.14', 'telang-1882', 'Chapter 4; aligned against BG4.14', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.14', 'न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा।
इति मां योऽभिजानाति कर्मभिर्न स बध्यते ॥', 'na māṃ karmāṇi limpanti na me karmaphale spṛhā
iti māṃ yo.abhijānāti karmabhirna sa badhyate', 'Actions defile me not. I have no attachment to the fruit of actions. He who knows me thus is not tied down by actions.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.15', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.15', 4, 15, 'Krishna', 'f77d6358c74086665a67a737ae9f5184d4062af651f1965e6588d74558df50cf', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.15', 'original', 'sa', 'Deva', 'एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः।
कुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.15', 'transliteration', 'sa', 'Latn', 'evaṃ jñātvā kṛtaṃ karma pūrvairapi mumukṣubhiḥ
kuru karmaiva tasmāttvaṃ pūrvaiḥ pūrvataraṃ kṛtam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.15', 'translation', 'en', 'Latn', 'Knowing this, the men of old who wished for final emancipation, performed action.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.15', 'vedic-scriptures', 'BG4.15', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.15', 'telang-1882', 'Chapter 4; aligned against BG4.15', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.15', 'एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः।
कुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम् ॥', 'evaṃ jñātvā kṛtaṃ karma pūrvairapi mumukṣubhiḥ
kuru karmaiva tasmāttvaṃ pūrvaiḥ pūrvataraṃ kṛtam', 'Knowing this, the men of old who wished for final emancipation, performed action.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.16', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.16', 4, 16, 'Krishna', 'addf24d32e40971cee12ea2b4078aea4c7315e24ee417a36bed0dac6f79af2eb', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.16', 'original', 'sa', 'Deva', 'किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः।
तत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.16', 'transliteration', 'sa', 'Latn', 'kiṃ karma kimakarmeti kavayo.apyatra mohitāḥ
tatte karma pravakṣyāmi yajjñātvā mokṣyase.aśubhāt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.16', 'translation', 'en', 'Latn', 'Therefore do you, too, perform action as was done by men of old in olden times. Even sages are confused as to what is action, what inaction. Therefore I will speak to you about action, and learning that, you will be freed from (this world of) evil. One must possess knowledge about action', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.16', 'vedic-scriptures', 'BG4.16', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.16', 'telang-1882', 'Chapter 4; aligned against BG4.16', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.16', 'किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः।
तत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥', 'kiṃ karma kimakarmeti kavayo.apyatra mohitāḥ
tatte karma pravakṣyāmi yajjñātvā mokṣyase.aśubhāt', 'Therefore do you, too, perform action as was done by men of old in olden times. Even sages are confused as to what is action, what inaction. Therefore I will speak to you about action, and learning that, you will be freed from (this world of) evil. One must possess knowledge about action');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.17', 4, 17, 'Krishna', 'b977794f293eb1cfc19994c7cb5aa58d073d3d7dc9f6f633dcba6bc535d21d19', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.17', 'original', 'sa', 'Deva', 'कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः।
अकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.17', 'transliteration', 'sa', 'Latn', 'karmaṇo hyapi boddhavyaṃ boddhavyaṃ ca vikarmaṇaḥ
akarmaṇaśca boddhavyaṃ gahanā karmaṇo gatiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.17', 'translation', 'en', 'Latn', 'one must also possess knowledge about prohibited action and again one must possess knowledge about inaction. The truth regarding action is abstruse.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.17', 'vedic-scriptures', 'BG4.17', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.17', 'telang-1882', 'Chapter 4; aligned against BG4.17', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.17', 'कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः।
अकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः ॥', 'karmaṇo hyapi boddhavyaṃ boddhavyaṃ ca vikarmaṇaḥ
akarmaṇaśca boddhavyaṃ gahanā karmaṇo gatiḥ', 'one must also possess knowledge about prohibited action and again one must possess knowledge about inaction. The truth regarding action is abstruse.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.18', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.18', 4, 18, 'Krishna', 'c61bb10289a34ba473081a6442c8ddb7dc95aeb4f8cd61025fd29679bb60a831', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.18', 'original', 'sa', 'Deva', 'कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः।
स बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.18', 'transliteration', 'sa', 'Latn', 'karmaṇyakarma yaḥ paśyedakarmaṇi ca karma yaḥ
sa buddhimānmanuṣyeṣu sa yuktaḥ kṛtsnakarmakṛt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.18', 'translation', 'en', 'Latn', 'He is wise among men, he is possessed of devotion, and performs all actions, who sees inaction in action, and action in inaction.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.18', 'vedic-scriptures', 'BG4.18', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.18', 'telang-1882', 'Chapter 4; aligned against BG4.18', 'English translation witness');
