INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.20', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.20', 4, 20, 'Krishna', '33c9a7f1f24d14e404558c20c482f2c6ba06eb62d97491b6fc6960acef0ad467', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.20', 'original', 'sa', 'Deva', 'त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः।
कर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.20', 'transliteration', 'sa', 'Latn', 'tyaktvā karmaphalāsaṅgaṃ nityatṛpto nirāśrayaḥ
karmaṇyabhipravṛtto.api naiva kiñcitkaroti saḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.20', 'translation', 'en', 'Latn', 'Forsaking all attachment to the fruit of action, always contented, dependent on none, he does nothing at all, though he engages in action.', 'telang-1882');
