INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.21', 'original', 'sa', 'Deva', 'निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः।
शारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.21', 'transliteration', 'sa', 'Latn', 'nirāśīryatacittātmā tyaktasarvaparigrahaḥ
