INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.21', 'translation', 'en', 'Latn', 'Devoid of expectations, restraining the mind and the self, and casting off all belongings, he incurs no sin, performing actions merely for the sake of the body.', 'telang-1882');
