INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.22', 'original', 'sa', 'Deva', 'यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः।
समः सिद्धावसिद्धौ च कृत्वापि न निबध्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.22', 'transliteration', 'sa', 'Latn', 'yadṛcchālābhasantuṣṭo dvandvātīto vimatsaraḥ
