INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.22', 'translation', 'en', 'Latn', 'Satisfied with earnings coming spontaneously rising above the pairs of opposites free from all animosity and equable on success or ill-success he is not fettered down even though he performs (actions).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.22', 'vedic-scriptures', 'BG4.22', 'Devanagari and IAST digital witness');
