INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.23', 'translation', 'en', 'Latn', 'The acts of one who is devoid of attachment who is free whose mind is fixed on knowledge and who performs action for (the purpose of) the sacrifice are all destroyed.', 'telang-1882');
