INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.25', 'original', 'sa', 'Deva', 'दैवमेवापरे यज्ञं योगिनः पर्युपासते।
ब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.25', 'transliteration', 'sa', 'Latn', 'daivamevāpare yajñaṃ yoginaḥ paryupāsate
