INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.25', 'translation', 'en', 'Latn', 'and Brahman, too, is the goal to which he proceeds who meditates on Brahman in the action. Some devotees perform the sacrifice to the gods, some offer up the sacrifice by the sacrifice itself in the fire of Brahman.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.25', 'vedic-scriptures', 'BG4.25', 'Devanagari and IAST digital witness');
