INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.27', 'original', 'sa', 'Deva', 'सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे।
आत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.27', 'transliteration', 'sa', 'Latn', 'sarvāṇīndriyakarmāṇi prāṇakarmāṇi cāpare
