INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.27', 'translation', 'en', 'Latn', 'Some again offer up all the operations of the senses and the operations of the life-breaths into the fire of devotion by self-restraint, kindled by knowledge. Others perform the sacrifice of wealth the sacrifice of penance the sacrifice of concentration of mind', 'telang-1882');
