INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.28', 'translation', 'en', 'Latn', 'the sacrifice of Vedic study and of knowledge and others are ascetics of rigid vows.', 'telang-1882');
