INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.29', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.29', 4, 29, 'Krishna', 'bfbb02004a22f58d018a2e5d945e3d415c2fcc676b932d7dd156d5e475831019', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.29', 'original', 'sa', 'Deva', 'अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे।
प्राणापानगती रुद्ध्वा प्राणायामपरायणाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.29', 'transliteration', 'sa', 'Latn', 'apāne juhvati prāṇaṃ prāṇe.apānaṃ tathāpare
prāṇāpānagatī ruddhvā prāṇāyāmaparāyaṇāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.29', 'translation', 'en', 'Latn', 'Some offer up the upward life-breath into the downward life-breath and the downward life-breath into the upper life-breath and stopping up the motions of the upward and downward life-breaths devote themselves to the restraint of the life-breaths.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.29', 'vedic-scriptures', 'BG4.29', 'Devanagari and IAST digital witness');
