INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.30', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.30', 4, 30, 'Krishna', 'ac90681fb12e8f936925f2781fad9b11555206fbcd539157b10c66bc6f80addb', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.30', 'original', 'sa', 'Deva', 'अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति।
सर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.30', 'transliteration', 'sa', 'Latn', 'apare niyatāhārāḥ prāṇānprāṇeṣu juhvati
sarve.apyete yajñavido yajñakṣapitakalmaṣāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.30', 'translation', 'en', 'Latn', 'Others, who (take) limited food, offer up the life-breaths into the life-breaths. All of these, conversant with the sacrifice, have their sins destroyed by the sacrifice.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.30', 'vedic-scriptures', 'BG4.30', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.30', 'telang-1882', 'Chapter 4; aligned against BG4.30', 'English translation witness');
