INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.33', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.33', 4, 33, 'Krishna', 'ce367d0aee9eb5ca30464343a5b72b2055fcad27b7fc8e0b4892deb8810c51e0', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.33', 'original', 'sa', 'Deva', 'श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप।
सर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.33', 'transliteration', 'sa', 'Latn', 'śreyāndravyamayādyajñājjñānayajñaḥ parantapa
sarvaṃ karmākhilaṃ pārtha jñāne parisamāpyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.33', 'translation', 'en', 'Latn', 'O son of Pṛthā! is wholly and entirely comprehended in knowledge. That you should learn by salutation question', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.33', 'vedic-scriptures', 'BG4.33', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.33', 'telang-1882', 'Chapter 4; aligned against BG4.33', 'English translation witness');
