INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.34', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.34', 4, 34, 'Krishna', '6a35edde0d9c76eb0e46525d16ece8c2de40ea7bcd7ff3626b6a7efc9cad3d79', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.34', 'original', 'sa', 'Deva', 'तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया।
उपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.34', 'transliteration', 'sa', 'Latn', 'tadviddhi praṇipātena paripraśnena sevayā
upadekṣyanti te jñānaṃ jñāninastattvadarśinaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.34', 'translation', 'en', 'Latn', 'and service. The men of knowledge who perceive the truth will teach knowledge to you.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.34', 'vedic-scriptures', 'BG4.34', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.34', 'telang-1882', 'Chapter 4; aligned against BG4.34', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.34', 'तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया।
उपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥', 'tadviddhi praṇipātena paripraśnena sevayā
upadekṣyanti te jñānaṃ jñāninastattvadarśinaḥ', 'and service. The men of knowledge who perceive the truth will teach knowledge to you.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.35', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.35', 4, 35, 'Krishna', 'f8c704dba82c81a943098082446a3c25eeb5adf99af40f411fef1a3680fde574', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.35', 'original', 'sa', 'Deva', 'यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव।
येन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि (var अशेषाणि) ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.35', 'transliteration', 'sa', 'Latn', 'yajjñātvā na punarmohamevaṃ yāsyasi pāṇḍava
yena bhūtānyaśeṣāṇi drakṣyasyātmanyatho mayi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.35', 'translation', 'en', 'Latn', 'Having learnt that, O son of Pāṇḍu! you will not again fall thus into delusion and by means of it, you will see all beings, without exception, first in yourself, and then in me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.35', 'vedic-scriptures', 'BG4.35', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.35', 'telang-1882', 'Chapter 4; aligned against BG4.35', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.35', 'यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव।
येन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि (var अशेषाणि) ॥', 'yajjñātvā na punarmohamevaṃ yāsyasi pāṇḍava
yena bhūtānyaśeṣāṇi drakṣyasyātmanyatho mayi', 'Having learnt that, O son of Pāṇḍu! you will not again fall thus into delusion and by means of it, you will see all beings, without exception, first in yourself, and then in me.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.36', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.36', 4, 36, 'Krishna', '29b7fa5b0f26d35d23fb9c6ad1c8889bed6ccb97b3e51b5e17e56e4be170e47d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.36', 'original', 'sa', 'Deva', 'अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः।
सर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.36', 'transliteration', 'sa', 'Latn', 'api cedasi pāpebhyaḥ sarvebhyaḥ pāpakṛttamaḥ
