INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.37', 'transliteration', 'sa', 'Latn', 'yathaidhāṃsi samiddho.agnirbhasmasātkurute.arjuna
