INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.37', 'translation', 'en', 'Latn', 'you will cross over all trespasses by means of the boat of knowledge alone. As a fire well kindled O Arjuna! reduces fuel to ashes', 'telang-1882');
