INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.38', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.38', 4, 38, 'Krishna', '66f69428e22676d3ec827e233159afc4a484a6e8c5bd8a0bb0fda72fb9b51627', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.38', 'original', 'sa', 'Deva', 'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते।
तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.38', 'transliteration', 'sa', 'Latn', 'na hi jñānena sadṛśaṃ pavitramiha vidyate
tatsvayaṃ yogasaṃsiddhaḥ kālenātmani vindati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.38', 'translation', 'en', 'Latn', 'so the fire of knowledge reduces all actions to ashes. For there is in this world no means of sanctification like knowledge and that one perfected by devotion finds within one''s self in time.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.38', 'vedic-scriptures', 'BG4.38', 'Devanagari and IAST digital witness');
