INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.39', 'original', 'sa', 'Deva', 'श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः।
ज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.39', 'transliteration', 'sa', 'Latn', 'śraddhāvā.Nllabhate jñānaṃ tatparaḥ saṃyatendriyaḥ
jñānaṃ labdhvā parāṃ śāntimacireṇādhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.39', 'translation', 'en', 'Latn', 'He who has faith, whose senses are restrained, and who is assiduous, obtains knowledge. Obtaining knowledge, he acquires, without delay, the highest tranquillity.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.39', 'vedic-scriptures', 'BG4.39', 'Devanagari and IAST digital witness');
