INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.40', 'original', 'sa', 'Deva', 'अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति।
नायं लोकोऽस्ति न परो न सुखं संशयात्मनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.40', 'transliteration', 'sa', 'Latn', 'ajñaścāśraddadhānaśca saṃśayātmā vinaśyati
nāyaṃ loko.asti na paro na sukhaṃ saṃśayātmanaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.40', 'translation', 'en', 'Latn', 'He who is ignorant and devoid of faith, and whose self is full of misgivings, is ruined. Not this world, not the next, nor happiness, is for him whose self is full of misgivings.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.40', 'vedic-scriptures', 'BG4.40', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.40', 'telang-1882', 'Chapter 4; aligned against BG4.40', 'English translation witness');
