INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.41', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.41', 4, 41, 'Krishna', '0dbd06eba26d4f62bcc536f3a2c58822a71d92432375551bd4aaa8ef50e94d98', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.41', 'original', 'sa', 'Deva', 'योगसंन्यस्तकर्माणं ज्ञानसञ्छिन्नसंशयम्।
आत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.41', 'transliteration', 'sa', 'Latn', 'yogasaṃnyastakarmāṇaṃ jñānasañchinnasaṃśayam
ātmavantaṃ na karmāṇi nibadhnanti dhanañjaya', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.41', 'translation', 'en', 'Latn', 'Actions, O Dhanañjaya ! do not fetter one who is self-possessed, who has renounced action by devotion, and who has destroyed misgivings by knowledge.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.41', 'vedic-scriptures', 'BG4.41', 'Devanagari and IAST digital witness');
