INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.4.42', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.4.42', 4, 42, 'Krishna', '35d00a7013a1c1518ec3a01c557e94f26c4cba1758a974990471c51126c2fe58', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.42', 'original', 'sa', 'Deva', 'तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः।
छित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.42', 'transliteration', 'sa', 'Latn', 'tasmādajñānasambhūtaṃ hṛtsthaṃ jñānāsinātmanaḥ
chittvainaṃ saṃśayaṃ yogamātiṣṭhottiṣṭha bhārata', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.4.42', 'translation', 'en', 'Latn', 'Therefore, O descendant of Bharata! destroy, with the sword of knowledge, these misgivings of yours which fill your mind, and which are produced from ignorance. Engage in devotion. Arise!', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.42', 'vedic-scriptures', 'BG4.42', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.4.42', 'telang-1882', 'Chapter 4; aligned against BG4.42', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.4.42', 'तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः।
