INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.1', 5, 1, 'Arjuna', '157a4e179f16de139e5bcbeb3b45caa9f4486b8a48ae2eab0c591d4948ac0a0c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.1', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
संन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि।
यच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.1', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
saṃnyāsaṃ karmaṇāṃ kṛṣṇa punaryogaṃ ca śaṃsasi
yacchreya etayorekaṃ tanme brūhi suniścitam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.1', 'translation', 'en', 'Latn', 'O Kṛṣṇa ! you praise renunciation of actions and also the pursuit (of them). Tell me determinately which one of these two is superior.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.1', 'vedic-scriptures', 'BG5.1', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.1', 'telang-1882', 'Chapter 5; aligned against BG5.1', 'English translation witness');
