INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.2', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
संन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ।
तयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.2', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
saṃnyāsaḥ karmayogaśca niḥśreyasakarāvubhau
tayostu karmasaṃnyāsātkarmayogo viśiṣyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.2', 'translation', 'en', 'Latn', 'Renunciation and pursuit of action are both instruments of happiness. But of the two, pursuit of action is superior to renunciation of action.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.2', 'vedic-scriptures', 'BG5.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.2', 'telang-1882', 'Chapter 5; aligned against BG5.2', 'English translation witness');
