INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.3', 'original', 'sa', 'Deva', 'ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति।
निर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.3', 'transliteration', 'sa', 'Latn', 'jñeyaḥ sa nityasaṃnyāsī yo na dveṣṭi na kāṅkṣati
nirdvandvo hi mahābāho sukhaṃ bandhātpramucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.3', 'translation', 'en', 'Latn', 'He should be understood to be always an ascetic who has no aversion and no desire. For O you of mighty arms! he who is free from the pairs of opposites is easily released from (all) bonds.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.3', 'vedic-scriptures', 'BG5.3', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.3', 'telang-1882', 'Chapter 5; aligned against BG5.3', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.5.3', 'ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति।
निर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते ॥', 'jñeyaḥ sa nityasaṃnyāsī yo na dveṣṭi na kāṅkṣati
nirdvandvo hi mahābāho sukhaṃ bandhātpramucyate', 'He should be understood to be always an ascetic who has no aversion and no desire. For O you of mighty arms! he who is free from the pairs of opposites is easily released from (all) bonds.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.4', 5, 4, 'Krishna', '5669b0313deb5266dde074704d3d48a4a2b76b08861b9624c1e4aa8431f34596', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.4', 'original', 'sa', 'Deva', 'साङ्ख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः।
एकमप्यास्थितः सम्यगुभयोर्विन्दते फलम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.4', 'transliteration', 'sa', 'Latn', 'sāṅkhyayogau pṛthagbālāḥ pravadanti na paṇḍitāḥ
ekamapyāsthitaḥ samyagubhayorvindate phalam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.4', 'translation', 'en', 'Latn', 'Children—not wise men—talk of saṅkhya and yoga as distinct. One who pursues either well obtains the fruit of both.', 'telang-1882');
