INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.5', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.5', 5, 5, 'Krishna', '5ae399173e7e50a48f7ac1ef56ccb186e9712c70fede13e992f8753dfb91ab15', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.5', 'original', 'sa', 'Deva', 'यत्साङ्ख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते।
एकं साङ्ख्यं च योगं च यः पश्यति स पश्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.5', 'transliteration', 'sa', 'Latn', 'yatsāṅkhyaiḥ prāpyate sthānaṃ tadyogairapi gamyate
ekaṃ sāṅkhyaṃ ca yogaṃ ca yaḥ paśyati sa paśyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.5', 'translation', 'en', 'Latn', 'The seat which the sāṅkhyas obtain is reached by the yogas also. He sees (truly), who sees the sāṅkhya and yoga as one.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.5', 'vedic-scriptures', 'BG5.5', 'Devanagari and IAST digital witness');
