INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.6', 'original', 'sa', 'Deva', 'संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः।
