INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.6', 'transliteration', 'sa', 'Latn', 'saṃnyāsastu mahābāho duḥkhamāptumayogataḥ
