INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.7', 'translation', 'en', 'Latn', 'He who is possessed of devotion whose self is pure who has restrained his self and who has controlled his senses and who identifies his self with every being is not tainted though he performs (actions). The man of devotion who knows the truth thinks he does nothing at all when he sees hears', 'telang-1882');
