INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.11', 'original', 'sa', 'Deva', 'कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि।
