INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.12', 'original', 'sa', 'Deva', 'युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम्।
अयुक्तः कामकारेण फले सक्तो निबध्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.12', 'transliteration', 'sa', 'Latn', 'yuktaḥ karmaphalaṃ tyaktvā śāntimāpnoti naiṣṭhikīm
ayuktaḥ kāmakāreṇa phale sakto nibadhyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.12', 'translation', 'en', 'Latn', 'He who is possessed of devotion, abandoning the fruit of actions, attains the highest tranquillity. He who is without devotion, and attached to the fruit (of action), is tied down by (reason of his) acting in consequence of (some) desire.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.12', 'vedic-scriptures', 'BG5.12', 'Devanagari and IAST digital witness');
