INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.13', 'original', 'sa', 'Deva', 'सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी।
नवद्वारे पुरे देही नैव कुर्वन्न कारयन् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.13', 'transliteration', 'sa', 'Latn', 'sarvakarmāṇi manasā saṃnyasyāste sukhaṃ vaśī
navadvāre pure dehī naiva kurvanna kārayan', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.13', 'translation', 'en', 'Latn', 'The self-restrained, embodied (self) lies at case within the city of nine portals, renouncing all actions by the mind, not doing nor causing (any thing) to be done.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.13', 'vedic-scriptures', 'BG5.13', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.13', 'telang-1882', 'Chapter 5; aligned against BG5.13', 'English translation witness');
