INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.15', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.15', 5, 15, 'Krishna', '453bd671f50c472e5627bb74a1544c6e7f02b10d4d6cc0d9c0b02e6af18d6ccc', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.15', 'original', 'sa', 'Deva', 'नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः।
अज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.15', 'transliteration', 'sa', 'Latn', 'nādatte kasyacitpāpaṃ na caiva sukṛtaṃ vibhuḥ
ajñānenāvṛtaṃ jñānaṃ tena muhyanti jantavaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.15', 'translation', 'en', 'Latn', 'The Lord receives no one''s sin, nor merit either. Knowledge is enveloped by ignorance', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.15', 'vedic-scriptures', 'BG5.15', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.15', 'telang-1882', 'Chapter 5; aligned against BG5.15', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.5.15', 'नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः।
