INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.17', 5, 17, 'Krishna', '30b0cff57eae2e19d40a57778c98d7215ccd2169ba244770ba37308699aae9db', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.17', 'original', 'sa', 'Deva', 'तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः।
गच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.17', 'transliteration', 'sa', 'Latn', 'tadbuddhayastadātmānastanniṣṭhāstatparāyaṇāḥ
gacchantyapunarāvṛttiṃ jñānanirdhūtakalmaṣāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.17', 'translation', 'en', 'Latn', 'shows forth that supreme (principle). And those whose mind is (centred) on it whose (very) self it is who are thoroughly devoted to it and whose final goal it is go never to return having their sins destroyed by knowledge.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.17', 'vedic-scriptures', 'BG5.17', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.17', 'telang-1882', 'Chapter 5; aligned against BG5.17', 'English translation witness');
