INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.24', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.24', 5, 24, 'Krishna', '8a82d1ea80e99a2207c5557ec98d06f3427edc8b70728e5287d6d2e143ef4111', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.24', 'original', 'sa', 'Deva', 'योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः।
स योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.24', 'transliteration', 'sa', 'Latn', 'yo.antaḥsukho.antarārāmastathāntarjyotireva yaḥ
sa yogī brahmanirvāṇaṃ brahmabhūto.adhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.24', 'translation', 'en', 'Latn', 'The devotee whose happiness is within (himself) whose recreation is within (himself) and whose light (of knowledge) also is within (himself) becoming (one with) the Brahman', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.24', 'vedic-scriptures', 'BG5.24', 'Devanagari and IAST digital witness');
