INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.25', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.25', 5, 25, 'Krishna', 'c634503068d52384cad7f7e08e52e9a64757b3cd4416f7e503f7151ea7e69a1e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.25', 'original', 'sa', 'Deva', 'लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः।
