INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.25', 'transliteration', 'sa', 'Latn', 'labhante brahmanirvāṇamṛṣayaḥ kṣīṇakalmaṣāḥ
