INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.25', 'translation', 'en', 'Latn', 'obtain the Brahmic bliss. The sages whose sins have perished whose misgivings are destroyed who are self-restrained and who are intent on the welfare of all beings', 'telang-1882');
