INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.26', 'translation', 'en', 'Latn', 'obtain the Brahmic bliss. To the ascetics who are free from desire and wrath and whose minds are restrained and who have knowledge of the self', 'telang-1882');
