INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.27', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.27', 5, 27, 'Krishna', '16e8e8a896c3a32068864d0003fe38513853a910ddc25f726b108082f3c933ac', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.27', 'original', 'sa', 'Deva', 'स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः।
प्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.27', 'transliteration', 'sa', 'Latn', 'sparśānkṛtvā bahirbāhyāṃścakṣuścaivāntare bhruvoḥ
prāṇāpānau samau kṛtvā nāsābhyantaracāriṇau', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.27', 'translation', 'en', 'Latn', 'the Brahmic bliss is on both sides (of death). The sage who excludes (from his mind) external objects, (concentrates) the visual power between the brows and making the upward and downward life-breaths even confines their movements within the nose', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.27', 'vedic-scriptures', 'BG5.27', 'Devanagari and IAST digital witness');
