INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.28', 'original', 'sa', 'Deva', 'यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः।
