INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.28', 'translation', 'en', 'Latn', 'who restrains senses mind and understanding whose highest goal is final emancipation from whom desire fear', 'telang-1882');
