INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.5.29', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.5.29', 5, 29, 'Krishna', '1306d6aac24f1522567e2fb72940ae1e99c5c8bc7d002f1b76c414360a369b03', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.29', 'original', 'sa', 'Deva', 'भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्।
सुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.29', 'transliteration', 'sa', 'Latn', 'bhoktāraṃ yajñatapasāṃ sarvalokamaheśvaram
suhṛdaṃ sarvabhūtānāṃ jñātvā māṃ śāntimṛcchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.5.29', 'translation', 'en', 'Latn', 'and wrath have departed is indeed for ever released (from birth and death). He knowing me to be the enjoyer of all sacrifices and penances, the great Lord of all worlds, and the friend of all beings, attains tranquillity.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.29', 'vedic-scriptures', 'BG5.29', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.5.29', 'telang-1882', 'Chapter 5; aligned against BG5.29', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.5.29', 'भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्।
