INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.2', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.2', 6, 2, 'Krishna', '80e59f4b88b5d4856faadf5fc2435be2da87bc21963385988eba5373d4a37c24', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.2', 'original', 'sa', 'Deva', 'यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव।
न ह्यसंन्यस्तसङ्कल्पो योगी भवति कश्चन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.2', 'transliteration', 'sa', 'Latn', 'yaṃ saṃnyāsamiti prāhuryogaṃ taṃ viddhi pāṇḍava
na hyasaṃnyastasaṅkalpo yogī bhavati kaścana', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.2', 'translation', 'en', 'Latn', 'Know, O son of Pāṇḍu! that what is called renunciation is devotion for nobody becomes a devotee who has not renounced (all) fancies. To the sage who wishes to rise to devotion', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.2', 'vedic-scriptures', 'BG6.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.2', 'telang-1882', 'Chapter 6; aligned against BG6.2', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.6.2', 'यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव।
न ह्यसंन्यस्तसङ्कल्पो योगी भवति कश्चन ॥', 'yaṃ saṃnyāsamiti prāhuryogaṃ taṃ viddhi pāṇḍava
na hyasaṃnyastasaṅkalpo yogī bhavati kaścana', 'Know, O son of Pāṇḍu! that what is called renunciation is devotion for nobody becomes a devotee who has not renounced (all) fancies. To the sage who wishes to rise to devotion');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.3', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.3', 6, 3, 'Krishna', '5c161121467461c96ab47bb54639e43f548db783b8e2b629d4a455885b4ca203', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.3', 'original', 'sa', 'Deva', 'आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते।
योगारूढस्य तस्यैव शमः कारणमुच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.3', 'transliteration', 'sa', 'Latn', 'ārurukṣormuneryogaṃ karma kāraṇamucyate
