INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.3', 'translation', 'en', 'Latn', 'action is said to be a means and to him when he has risen to devotion tranquillity is said to be a means. When one does not attach oneself to objects of sense', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.3', 'vedic-scriptures', 'BG6.3', 'Devanagari and IAST digital witness');
