INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.4', 'original', 'sa', 'Deva', 'यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते।
