INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.5', 'translation', 'en', 'Latn', '(A man) should elevate his self by his self he should not debase his self for even (a man''s) own self is his friend, (a man''s) own self is also his enemy. To him who has subjugated his self by his self', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.5', 'vedic-scriptures', 'BG6.5', 'Devanagari and IAST digital witness');
