INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.6', 'original', 'sa', 'Deva', 'बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः।
