INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.8', 'original', 'sa', 'Deva', 'ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः।
