INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.8', 'translation', 'en', 'Latn', 'The devotee whose self is contented with knowledge and experience who is unmoved who has restrained his senses and to whom a sod a stone and gold are alike is said to be devoted. And he is esteemed highest who thinks alike about well-wishers', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.8', 'vedic-scriptures', 'BG6.8', 'Devanagari and IAST digital witness');
