INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.10', 'original', 'sa', 'Deva', 'योगी युञ्जीत सततमात्मानं रहसि स्थितः।
एकाकी यतचित्तात्मा निराशीरपरिग्रहः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.10', 'transliteration', 'sa', 'Latn', 'yogī yuñjīta satatamātmānaṃ rahasi sthitaḥ
ekākī yatacittātmā nirāśīraparigrahaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.10', 'translation', 'en', 'Latn', 'and those who take part with both sides and those who are objects of hatred and relatives as well as about the good and the sinful. A devotee should constantly devote his self to abstraction, remaining in a secret place, alone, with his mind and self restrained, without expectations, and without belongings.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.10', 'vedic-scriptures', 'BG6.10', 'Devanagari and IAST digital witness');
