INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.11', 'original', 'sa', 'Deva', 'शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः।
नात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.11', 'transliteration', 'sa', 'Latn', 'śucau deśe pratiṣṭhāpya sthiramāsanamātmanaḥ
