INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.11', 'translation', 'en', 'Latn', 'Fixing his seat firmly in a clean place not too high nor too low and covered over with a sheet of cloth a deerskin and (blades of) Kuśa (grass),—and there seated on (that) seat', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.11', 'vedic-scriptures', 'BG6.11', 'Devanagari and IAST digital witness');
