INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.12', 'translation', 'en', 'Latn', 'fixing his mind exclusively on one point with the workings of the mind and senses restrained he should practice devotion for purity of self.', 'telang-1882');
