INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.14', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.14', 6, 14, 'Krishna', '1b9832177b4ef138234a6a98280d9e492eaf22af854dc1c2285decbc98f98a28', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.14', 'original', 'sa', 'Deva', 'प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः।
मनः संयम्य मच्चित्तो युक्त आसीत मत्परः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.14', 'transliteration', 'sa', 'Latn', 'praśāntātmā vigatabhīrbrahmacārivrate sthitaḥ
manaḥ saṃyamya maccitto yukta āsīta matparaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.14', 'translation', 'en', 'Latn', 'and neck even and unmoved, (remaining) steady looking at the tip of his own nose and not looking about in (all) directions with a tranquil self devoid of fear and adhering to the rules of Brahmacārins he should restrain his mind and (concentrate it) on me and sit down engaged in devotion regarding me as his final goal.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.14', 'vedic-scriptures', 'BG6.14', 'Devanagari and IAST digital witness');
