INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.15', 'original', 'sa', 'Deva', 'युञ्जन्नेवं सदात्मानं योगी नियतमानसः।
शान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.15', 'transliteration', 'sa', 'Latn', 'yuñjannevaṃ sadātmānaṃ yogī niyatamānasaḥ
śāntiṃ nirvāṇaparamāṃ matsaṃsthāmadhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.15', 'translation', 'en', 'Latn', 'Thus constantly devoting his self to abstraction, a devotee whose mind is restrained, attains that tranquillity which culminates in final emancipation, and assimilation with me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.15', 'vedic-scriptures', 'BG6.15', 'Devanagari and IAST digital witness');
