INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.16', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.16', 6, 16, 'Krishna', 'b1d0d2ff8e8e720e2bc146231f13ae52e5c99f8c1439bd3a4dc1fbb0fdc99149', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.16', 'original', 'sa', 'Deva', 'नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः।
न चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.16', 'transliteration', 'sa', 'Latn', 'nātyaśnatastu yogo.asti na caikāntamanaśnataḥ
na cātisvapnaśīlasya jāgrato naiva cārjuna', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.16', 'translation', 'en', 'Latn', 'Devotion is not his, O Arjuna ! who eats too much, nor his who cats not at all not his who is addicted to too much sleep nor his who is (ever) awake. That devotion which destroys (all) misery is his', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.16', 'vedic-scriptures', 'BG6.16', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.16', 'telang-1882', 'Chapter 6; aligned against BG6.16', 'English translation witness');
