INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.17', 'translation', 'en', 'Latn', 'who takes due food and exercise who toils duly in all works and who sleeps and awakes (in) due (time). When (a man''s) mind well restrained becomes steady upon the self alone', 'telang-1882');
