INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.19', 'original', 'sa', 'Deva', 'यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता।
योगिनो यतचित्तस्य युञ्जतो योगमात्मनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.19', 'transliteration', 'sa', 'Latn', 'yathā dīpo nivātastho neṅgate sopamā smṛtā
