INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.19', 'translation', 'en', 'Latn', 'is said to be devoted. As a light standing in a windless (place) flickers not that is declared to be the parallel for a devotee whose mind is restrained and who devotes his self to abstraction. That (mental condition)', 'telang-1882');
