INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.20', 'translation', 'en', 'Latn', 'in which the mind restrained by practice of abstraction ceases to work in which too, one seeing the self by the self, is pleased in the self', 'telang-1882');
