INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.22', 'transliteration', 'sa', 'Latn', 'yaṃ labdhvā cāparaṃ lābhaṃ manyate nādhikaṃ tataḥ
