INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.22', 'translation', 'en', 'Latn', 'acquiring which, one thinks no other acquisition higher than it and adhering to which, one is not shaken off even by great misery', 'telang-1882');
