INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.23', 'original', 'sa', 'Deva', 'तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम्।
