INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.23', 'transliteration', 'sa', 'Latn', 'taṃ vidyād duḥkhasaṃyogaviyogaṃ yogasaṃjñitam
