INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.23', 'translation', 'en', 'Latn', 'that should be understood to be called devotion in which there is a severance of all connexion with pain. That devotion should be practised with steadiness and with an undesponding heart. Abandoning without exception all desires which are produced from fancies', 'telang-1882');
