INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.25', 'original', 'sa', 'Deva', 'शनैः शनैरुपरमेद् बुद्ध्या धृतिगृहीतया।
आत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.25', 'transliteration', 'sa', 'Latn', 'śanaiḥ śanairuparamed buddhyā dhṛtigṛhītayā
