INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.26', 'original', 'sa', 'Deva', 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।
ततस्ततो नियम्यैतदात्मन्येव वशं नयेत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.26', 'transliteration', 'sa', 'Latn', 'yato yato niścarati manaścañcalamasthiram
tatastato niyamyaitadātmanyeva vaśaṃ nayet', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.26', 'translation', 'en', 'Latn', 'Wherever the active and unsteady mind breaks forth, there one should ever restrain it, and fix it steadily on the self alone. The highest happiness comes to such a devotee whose mind is fully tranquil in whom the quality of passion has been suppressed', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.26', 'vedic-scriptures', 'BG6.26', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.26', 'telang-1882', 'Chapter 6; aligned against BG6.26', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.6.26', 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।
ततस्ततो नियम्यैतदात्मन्येव वशं नयेत् ॥', 'yato yato niścarati manaścañcalamasthiram
tatastato niyamyaitadātmanyeva vaśaṃ nayet', 'Wherever the active and unsteady mind breaks forth, there one should ever restrain it, and fix it steadily on the self alone. The highest happiness comes to such a devotee whose mind is fully tranquil in whom the quality of passion has been suppressed');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.27', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.27', 6, 27, 'Krishna', '04f1c651ab9f944cc502d7adffcdedc8562ed6fdebb8a9775fa513ca22231b49', 'first review verified; second review pending', 0);
