INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.30', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.30', 6, 30, 'Krishna', '954d164230ca294fcebb11febc68a8ab96b0d5d18360226b4f5d5195c8468b5e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.30', 'original', 'sa', 'Deva', 'यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति।
तस्याहं न प्रणश्यामि स च मे न प्रणश्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.30', 'transliteration', 'sa', 'Latn', 'yo māṃ paśyati sarvatra sarvaṃ ca mayi paśyati
