INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.31', 'transliteration', 'sa', 'Latn', 'sarvabhūtasthitaṃ yo māṃ bhajatyekatvamāsthitaḥ
