INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.6.31', 'सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः।
सर्वथा वर्तमानोऽपि स योगी मयि वर्तते ॥', 'sarvabhūtasthitaṃ yo māṃ bhajatyekatvamāsthitaḥ
sarvathā vartamāno.api sa yogī mayi vartate', 'The devotee who worships me abiding in all beings holding that all is one lives in me however he may be living. That devotee');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.32', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.32', 6, 32, 'Krishna', 'eefdd76c834ab4b20d49972bb75676274785e62020baba671d171b6d5b964283', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.32', 'original', 'sa', 'Deva', 'आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन।
सुखं वा यदि वा दुःखं स योगी परमो मतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.32', 'transliteration', 'sa', 'Latn', 'ātmaupamyena sarvatra samaṃ paśyati yo.arjuna
sukhaṃ vā yadi vā duḥkhaṃ sa yogī paramo mataḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.32', 'translation', 'en', 'Latn', 'O Arjuna! is deemed to be the best who looks alike on pleasure or pain', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.32', 'vedic-scriptures', 'BG6.32', 'Devanagari and IAST digital witness');
