INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.33', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.33', 6, 33, 'Arjuna', 'f9fd856d46d49fa3750aa70dce11267874df48fc4a46d79c6203ee5bf581421f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.33', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
योऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन।
एतस्याहं न पश्यामि चञ्चलत्वात्स्थितिं स्थिराम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.33', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
yo.ayaṃ yogastvayā proktaḥ sāmyena madhusūdana
etasyāhaṃ na paśyāmi cañcalatvātsthitiṃ sthirām', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.33', 'translation', 'en', 'Latn', 'whatever it may be in all (creatures) comparing. all with his own (pleasure or pain). I cannot see, O destroyer of Madhu! (how) the sustained existence (is to be secured) of this devotion by means of equanimity which you have declared-in consequence of fickleness. For O Kṛṣṇa ! the mind is fickle', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.33', 'vedic-scriptures', 'BG6.33', 'Devanagari and IAST digital witness');
