INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.36', 'original', 'sa', 'Deva', 'असंयतात्मना योगो दुष्प्राप इति मे मतिः।
वश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.36', 'transliteration', 'sa', 'Latn', 'asaṃyatātmanā yogo duṣprāpa iti me matiḥ
vaśyātmanā tu yatatā śakyo.avāptumupāyataḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.36', 'translation', 'en', 'Latn', 'that devotion is hard to obtain for one who does not restrain his self. But by one who is self-restrained and assiduous it can be obtained through (proper) expedients.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.36', 'vedic-scriptures', 'BG6.36', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.36', 'telang-1882', 'Chapter 6; aligned against BG6.36', 'English translation witness');
