INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.37', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
अयतिः श्रद्धयोपेतो योगाच्चलितमानसः।
अप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.37', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
ayatiḥ śraddhayopeto yogāccalitamānasaḥ
aprāpya yogasaṃsiddhiṃ kāṃ gatiṃ kṛṣṇa gacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.37', 'translation', 'en', 'Latn', 'What is the end of him O Kṛṣṇa! who does not attain the consummation of his devotion being not assiduous and having a mind shaken off from devotion, (though) full of faith? Does he fallen from both (paths)', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.37', 'vedic-scriptures', 'BG6.37', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.37', 'telang-1882', 'Chapter 6; aligned against BG6.37', 'English translation witness');
