INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.39', 'original', 'sa', 'Deva', 'एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः।
