INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.39', 'transliteration', 'sa', 'Latn', 'etanme saṃśayaṃ kṛṣṇa chettumarhasyaśeṣataḥ
