INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.39', 'translation', 'en', 'Latn', 'O you of mighty arms! without support and deluded on the path (leading) to the Brahman? Be pleased, O Kṛṣṇa! to entirely destroy this doubt of mine, for none else than you can destroy this doubt.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.39', 'vedic-scriptures', 'BG6.39', 'Devanagari and IAST digital witness');
