INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.41', 'original', 'sa', 'Deva', 'प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः।
शुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.41', 'transliteration', 'sa', 'Latn', 'prāpya puṇyakṛtāṃ lokānuṣitvā śāśvatīḥ samāḥ
śucīnāṃ śrīmatāṃ gehe yogabhraṣṭo.abhijāyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.41', 'translation', 'en', 'Latn', 'He who is fallen from devotion attains the worlds of those who perform meritorious acts dwells (there) for many a year', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.41', 'vedic-scriptures', 'BG6.41', 'Devanagari and IAST digital witness');
