INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.42', 'original', 'sa', 'Deva', 'अथवा योगिनामेव कुले भवति धीमताम्।
एतद्धि दुर्लभतरं लोके जन्म यदीदृशम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.42', 'transliteration', 'sa', 'Latn', 'athavā yogināmeva kule bhavati dhīmatām
etaddhi durlabhataraṃ loke janma yadīdṛśam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.42', 'translation', 'en', 'Latn', 'and is afterwards born into a family of holy and illustrious men. Or he is even born into a family of talented devotees for such a birth as that in this world is more difficult to obtain.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.42', 'vedic-scriptures', 'BG6.42', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.42', 'telang-1882', 'Chapter 6; aligned against BG6.42', 'English translation witness');
