INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.43', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.43', 6, 43, 'Krishna', '93706c448364fffa5721bca679b1a6748739e3aef8bfb93a49f45b04b7c72c7b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.43', 'original', 'sa', 'Deva', 'तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम्।
यतते च ततो भूयः संसिद्धौ कुरुनन्दन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.43', 'transliteration', 'sa', 'Latn', 'tatra taṃ buddhisaṃyogaṃ labhate paurvadehikam
yatate ca tato bhūyaḥ saṃsiddhau kurunandana', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.43', 'translation', 'en', 'Latn', 'There he comes into contact with the knowledge which belonged to him in his former body', 'telang-1882');
