INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.44', 'original', 'sa', 'Deva', 'पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः।
जिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.44', 'transliteration', 'sa', 'Latn', 'pūrvābhyāsena tenaiva hriyate hyavaśo.api saḥ
jijñāsurapi yogasya śabdabrahmātivartate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.44', 'translation', 'en', 'Latn', 'and then again O descendant of Kuru ! he works for perfection. For even though reluctant he is led away by the self-same former practice and although he only wishes to learn devotion he rises above the (fruits of action laid down in the) divine word. But the devotee working with great efforts', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.44', 'vedic-scriptures', 'BG6.44', 'Devanagari and IAST digital witness');
