INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.45', 'original', 'sa', 'Deva', 'प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः।
अनेकजन्मसंसिद्धस्ततो याति परां गतिम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.45', 'transliteration', 'sa', 'Latn', 'prayatnādyatamānastu yogī saṃśuddhakilbiṣaḥ
anekajanmasaṃsiddhastato yāti parāṃ gatim', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.45', 'translation', 'en', 'Latn', 'and cleared of his sins attains perfection after many births and then reaches the supreme goal.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.45', 'vedic-scriptures', 'BG6.45', 'Devanagari and IAST digital witness');
