INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.6.46', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.6.46', 6, 46, 'Krishna', '280d8159ad4040d7957098e4314135151fa793079615121668b766efe4ecf1a6', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.46', 'original', 'sa', 'Deva', 'तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः।
कर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.46', 'transliteration', 'sa', 'Latn', 'tapasvibhyo.adhiko yogī jñānibhyo.api mato.adhikaḥ
karmibhyaścādhiko yogī tasmādyogī bhavārjuna', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.6.46', 'translation', 'en', 'Latn', 'The devotee is esteemed higher than the performers of penances, higher even than the men of knowledge, and the devotee is higher than the men of action therefore', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.6.46', 'vedic-scriptures', 'BG6.46', 'Devanagari and IAST digital witness');
