INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.2', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.2', 7, 2, 'Krishna', '206ecc1805087bf116e3047859da199f2ed3e4b7a423a2e963598603b80463f9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.2', 'original', 'sa', 'Deva', 'ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः।
यज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.2', 'transliteration', 'sa', 'Latn', 'jñānaṃ te.ahaṃ savijñānamidaṃ vakṣyāmyaśeṣataḥ
yajjñātvā neha bhūyo.anyajjñātavyamavaśiṣyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.2', 'translation', 'en', 'Latn', 'that being known, there is nothing further left in this world to know.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.2', 'vedic-scriptures', 'BG7.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.2', 'telang-1882', 'Chapter 7; aligned against BG7.2', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.7.2', 'ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः।
