INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.3', 'original', 'sa', 'Deva', 'मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये।
यततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.3', 'transliteration', 'sa', 'Latn', 'manuṣyāṇāṃ sahasreṣu kaścidyatati siddhaye
yatatāmapi siddhānāṃ kaścinmāṃ vetti tattvataḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.3', 'translation', 'en', 'Latn', 'Among thousands of men, only some work for perfection and even of those who have reached perfection, and who are assiduous, only some know me truly.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.3', 'vedic-scriptures', 'BG7.3', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.3', 'telang-1882', 'Chapter 7; aligned against BG7.3', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.7.3', 'मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये।
यततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः ॥', 'manuṣyāṇāṃ sahasreṣu kaścidyatati siddhaye
yatatāmapi siddhānāṃ kaścinmāṃ vetti tattvataḥ', 'Among thousands of men, only some work for perfection and even of those who have reached perfection, and who are assiduous, only some know me truly.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.4', 7, 4, 'Krishna', '3d2e8a40c470c40a386e636f0d07de2c8cceead1f71dc9afe532d52c32df2fde', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.4', 'original', 'sa', 'Deva', 'भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च।
अहंकार इतीयं मे भिन्ना प्रकृतिरष्टधा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.4', 'transliteration', 'sa', 'Latn', 'bhūmirāpo.analo vāyuḥ khaṃ mano buddhireva ca
ahaṃkāra itīyaṃ me bhinnā prakṛtiraṣṭadhā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.4', 'translation', 'en', 'Latn', 'Earth, water, fire, air, space, mind, understanding, and egoism, thus is my nature divided eightfold. But this is a lower (form of my) nature.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.4', 'vedic-scriptures', 'BG7.4', 'Devanagari and IAST digital witness');
