INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.6', 'translation', 'en', 'Latn', 'Know that all things have these (for their) source. I am the producer and the destroyer of the whole universe.', 'telang-1882');
