INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.7', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.7', 7, 7, 'Krishna', 'fda72cf5cad2298475762905f57ec9a61a7cea6a14f096d07adcf8360c295fcd', 'first review verified; second review pending', 0);
