INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.7', 'transliteration', 'sa', 'Latn', 'mattaḥ parataraṃ nānyatkiñcidasti dhanañjaya
