INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.8', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.8', 7, 8, 'Krishna', '4023c499f67f354bdb13e8eb4f5a236ca1f2108acd7a10eca95acbd1a67a7f17', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.8', 'original', 'sa', 'Deva', 'रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः।
प्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.8', 'transliteration', 'sa', 'Latn', 'raso.ahamapsu kaunteya prabhāsmi śaśisūryayoḥ
