INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.8', 'translation', 'en', 'Latn', 'I am the taste in water, O son of Kuntī ! I am the light of the sun and moon. I am ''Om'' in all the Vedas , sound in space, and manliness in human beings', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.8', 'vedic-scriptures', 'BG7.8', 'Devanagari and IAST digital witness');
