INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.9', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.9', 7, 9, 'Krishna', '7dd54bc7e9918d1fafbd1341e0b647ed183f2a058a3ba523fe880babba1d405c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.9', 'original', 'sa', 'Deva', 'पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ।
जीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.9', 'transliteration', 'sa', 'Latn', 'puṇyo gandhaḥ pṛthivyāṃ ca tejaścāsmi vibhāvasau
jīvanaṃ sarvabhūteṣu tapaścāsmi tapasviṣu', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.9', 'translation', 'en', 'Latn', 'I am the fragrant smell in the earth, refulgence in the fire I am life in all beings, and penance in those who perform penance.', 'telang-1882');
