INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.10', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.10', 7, 10, 'Krishna', 'fe0b1dad844b6c2cbba9388c44a6b7315c1f47c088c51d673fcb07de888fab9c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.10', 'original', 'sa', 'Deva', 'बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम्।
बुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.10', 'transliteration', 'sa', 'Latn', 'bījaṃ māṃ sarvabhūtānāṃ viddhi pārtha sanātanam
