INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.10', 'translation', 'en', 'Latn', 'Know me, O son of Pṛthā! to be the eternal seed of all beings I am the discernment of the discerning ones, and I the glory of the glorious.', 'telang-1882');
