INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.11', 'original', 'sa', 'Deva', 'बलं बलवतां चाहं कामरागविवर्जितम्।
धर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.11', 'transliteration', 'sa', 'Latn', 'balaṃ balavatāṃ cāhaṃ kāmarāgavivarjitam
