INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.11', 'translation', 'en', 'Latn', 'I am also the strength, unaccompanied by fondness or desire, of the strong. And, O chief of the descendants of Bharata! I am love unopposed to piety among all beings. And all entities which are of the quality of goodness and those which are of the quality of passion and of darkness', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.11', 'vedic-scriptures', 'BG7.11', 'Devanagari and IAST digital witness');
