INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.13', 'original', 'sa', 'Deva', 'त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत्।
मोहितं नाभिजानाति मामेभ्यः परमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.13', 'transliteration', 'sa', 'Latn', 'tribhirguṇamayairbhāvairebhiḥ sarvamidaṃ jagat
mohitaṃ nābhijānāti māmebhyaḥ paramavyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.13', 'translation', 'en', 'Latn', 'all from me I am not in them, but they are in me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.13', 'vedic-scriptures', 'BG7.13', 'Devanagari and IAST digital witness');
