INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.24', 'original', 'sa', 'Deva', 'अव्यक्तं व्यक्तिमापन्नं मन्यन्ते मामबुद्धयः।
परं भावमजानन्तो ममाव्ययमनुत्तमम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.24', 'transliteration', 'sa', 'Latn', 'avyaktaṃ vyaktimāpannaṃ manyante māmabuddhayaḥ
paraṃ bhāvamajānanto mamāvyayamanuttamam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.24', 'translation', 'en', 'Latn', 'The undiscerning ones, not knowing my transcendent and inexhaustible essence, than which there is nothing higher, think me, who am unperceived, to have become perceptible.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.24', 'vedic-scriptures', 'BG7.24', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.24', 'telang-1882', 'Chapter 7; aligned against BG7.24', 'English translation witness');
