INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.25', 'original', 'sa', 'Deva', 'नाहं प्रकाशः सर्वस्य योगमायासमावृतः।
मूढोऽयं नाभिजानाति लोको मामजमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.25', 'transliteration', 'sa', 'Latn', 'nāhaṃ prakāśaḥ sarvasya yogamāyāsamāvṛtaḥ
mūḍho.ayaṃ nābhijānāti loko māmajamavyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.25', 'translation', 'en', 'Latn', 'Surrounded by the delusion of my mystic power, I am not manifest to all. This deluded world knows not me unborn and inexhaustible.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.25', 'vedic-scriptures', 'BG7.25', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.25', 'telang-1882', 'Chapter 7; aligned against BG7.25', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.7.25', 'नाहं प्रकाशः सर्वस्य योगमायासमावृतः।
