INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.26', 'original', 'sa', 'Deva', 'वेदाहं समतीतानि वर्तमानानि चार्जुन।
भविष्याणि च भूतानि मां तु वेद न कश्चन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.26', 'transliteration', 'sa', 'Latn', 'vedāhaṃ samatītāni vartamānāni cārjuna
bhaviṣyāṇi ca bhūtāni māṃ tu veda na kaścana', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.26', 'translation', 'en', 'Latn', 'I know, O Arjuna! the things which have been, those which are, and those which are to be. But me nobody knows.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.26', 'vedic-scriptures', 'BG7.26', 'Devanagari and IAST digital witness');
