INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.28', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.28', 7, 28, 'Krishna', 'b5324241c883e3fb2dde0851952270574555b784c2a68a941d34492d90f1e87a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.28', 'original', 'sa', 'Deva', 'येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम्।
ते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.28', 'transliteration', 'sa', 'Latn', 'yeṣāṃ tvantagataṃ pāpaṃ janānāṃ puṇyakarmaṇām
te dvandvamohanirmuktā bhajante māṃ dṛḍhavratāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.28', 'translation', 'en', 'Latn', 'O terror of (your) foes! are deluded at the time of birth by the delusion O descendant of Bharata! caused by the pairs of opposites arising from desire and aversion. But the men of meritorious actions whose sins have terminated worship me being released from the delusion (caused) by the pairs of opposites and being firm in their beliefs. Those who resting on me', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.28', 'vedic-scriptures', 'BG7.28', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.28', 'telang-1882', 'Chapter 7; aligned against BG7.28', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.7.28', 'येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम्।
ते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः ॥', 'yeṣāṃ tvantagataṃ pāpaṃ janānāṃ puṇyakarmaṇām
te dvandvamohanirmuktā bhajante māṃ dṛḍhavratāḥ', 'O terror of (your) foes! are deluded at the time of birth by the delusion O descendant of Bharata! caused by the pairs of opposites arising from desire and aversion. But the men of meritorious actions whose sins have terminated worship me being released from the delusion (caused) by the pairs of opposites and being firm in their beliefs. Those who resting on me');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.7.29', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.7.29', 7, 29, 'Krishna', '7cf0ef6e754401fec7a82495b37a1923ad86b736f0b0c716204cde8e28ed7921', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.29', 'original', 'sa', 'Deva', 'जरामरणमोक्षाय मामाश्रित्य यतन्ति ये।
ते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.29', 'transliteration', 'sa', 'Latn', 'jarāmaraṇamokṣāya māmāśritya yatanti ye
te brahma tadviduḥ kṛtsnamadhyātmaṃ karma cākhilam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.29', 'translation', 'en', 'Latn', 'work for release from old age and death know the Brahman the whole Adhyātma', 'telang-1882');
