INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.30', 'original', 'sa', 'Deva', 'साधिभूताधिदैवं मां साधियज्ञं च ये विदुः।
प्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.30', 'transliteration', 'sa', 'Latn', 'sādhibhūtādhidaivaṃ māṃ sādhiyajñaṃ ca ye viduḥ
prayāṇakāle.api ca māṃ te viduryuktacetasaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.7.30', 'translation', 'en', 'Latn', 'and all action. And those who know me with the Adhibhūta the Adhidaiva and the Adhiyajña having minds devoted to abstraction know me at the time of departure (from this world).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.7.30', 'vedic-scriptures', 'BG7.30', 'Devanagari and IAST digital witness');
