INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.1', 8, 1, 'Arjuna', '26f0cb1a4bdcad97cd0a0cea5e1f7177316d738b3a8d01cae73573b24877594f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.1', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
किं तद् ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम।
अधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.1', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
kiṃ tad brahma kimadhyātmaṃ kiṃ karma puruṣottama
adhibhūtaṃ ca kiṃ proktamadhidaivaṃ kimucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.1', 'translation', 'en', 'Latn', 'What is that Brahman what the Adhyātma and what O best of beings! is action? And what is called the Adhibhūta? And who is the Adhiyajña', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.1', 'vedic-scriptures', 'BG8.1', 'Devanagari and IAST digital witness');
