INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.2', 'original', 'sa', 'Deva', 'अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन।
प्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.2', 'transliteration', 'sa', 'Latn', 'adhiyajñaḥ kathaṃ ko.atra dehe.asminmadhusūdana
prayāṇakāle ca kathaṃ jñeyo.asi niyatātmabhiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.2', 'translation', 'en', 'Latn', 'and how in this body O destroyer of Madhu? And how too are you to be known at the time of departure (from this world) by those who restrain their selfs?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.2', 'vedic-scriptures', 'BG8.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.2', 'telang-1882', 'Chapter 8; aligned against BG8.2', 'English translation witness');
