INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.9', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.9', 8, 9, 'Krishna', '3adc9b604b1931f2fbb7032e7127234d48aa2fe720f37792ef14af957766360d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.9', 'original', 'sa', 'Deva', 'कविं पुराणमनुशासितार-
मणोरणीयंसमनुस्मरेद्यः।
सर्वस्य धातारमचिन्त्यरूप-
मादित्यवर्णं तमसः परस्तात् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.9', 'transliteration', 'sa', 'Latn', 'kaviṃ purāṇamanuśāsitāraṃ aṇoraṇīyaṃsamanusmaredyaḥ
sarvasya dhātāramacintyarūpaṃ ādityavarṇaṃ tamasaḥ parastāt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.9', 'translation', 'en', 'Latn', 'properly concentrates the life-breath between the brows and meditates on the ancient Seer the ruler more minute than the minutest atom the supporter of all who is of an unthinkable form whose brilliance is like that of the sun and who is beyond all darkness', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.9', 'vedic-scriptures', 'BG8.9', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.9', 'telang-1882', 'Chapter 8; aligned against BG8.9', 'English translation witness');
