INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.10', 'original', 'sa', 'Deva', 'प्रयाणकाले मनसाऽचलेन
भक्त्या युक्तो योगबलेन चैव।
भ्रुवोर्मध्ये प्राणमावेश्य सम्यक्
स तं परं पुरुषमुपैति दिव्यम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.10', 'transliteration', 'sa', 'Latn', 'prayāṇakāle manasā.acalena bhaktyā yukto yogabalena caiva
bhruvormadhye prāṇamāveśya samyak sa taṃ paraṃ puruṣamupaiti divyam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.10', 'translation', 'en', 'Latn', 'he attains to that transcendent and divine Being.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.10', 'vedic-scriptures', 'BG8.10', 'Devanagari and IAST digital witness');
