INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.11', 'original', 'sa', 'Deva', 'यदक्षरं वेदविदो वदन्ति
विशन्ति यद्यतयो वीतरागाः।
यदिच्छन्तो ब्रह्मचर्यं चरन्ति
तत्ते पदं संग्रहेण प्रवक्ष्ये ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.11', 'transliteration', 'sa', 'Latn', 'yadakṣaraṃ vedavido vadanti viśanti yadyatayo vītarāgāḥ
yadicchanto brahmacaryaṃ caranti tatte padaṃ saṃgraheṇa pravakṣye', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.11', 'translation', 'en', 'Latn', 'I will tell you briefly about the seat, which those who know the Vedas declare to be indestructible which entered by ascetics from whom all desires have departed and wishing for which, people pursue the mode of life of Brahmacārins . He who leaves the body and departs (from this world) stopping up all passages', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.11', 'vedic-scriptures', 'BG8.11', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.11', 'telang-1882', 'Chapter 8; aligned against BG8.11', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.8.11', 'यदक्षरं वेदविदो वदन्ति
विशन्ति यद्यतयो वीतरागाः।
यदिच्छन्तो ब्रह्मचर्यं चरन्ति
तत्ते पदं संग्रहेण प्रवक्ष्ये ॥', 'yadakṣaraṃ vedavido vadanti viśanti yadyatayo vītarāgāḥ
yadicchanto brahmacaryaṃ caranti tatte padaṃ saṃgraheṇa pravakṣye', 'I will tell you briefly about the seat, which those who know the Vedas declare to be indestructible which entered by ascetics from whom all desires have departed and wishing for which, people pursue the mode of life of Brahmacārins . He who leaves the body and departs (from this world) stopping up all passages');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.12', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.12', 8, 12, 'Krishna', '3feef2d5d03fcac085e5f33cc0b1a579eb2231eff871680c122613192678a182', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.12', 'original', 'sa', 'Deva', 'सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च।
मूध्न्यार्धायात्मनः प्राणमास्थितो योगधारणाम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.12', 'transliteration', 'sa', 'Latn', 'sarvadvārāṇi saṃyamya mano hṛdi nirudhya ca
mūdhnyā^^rdhāyātmanaḥ prāṇamāsthito yogadhāraṇām', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.12', 'translation', 'en', 'Latn', 'and confining the mind within the heart placing the life-breath in the head', 'telang-1882');
