INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.14', 'original', 'sa', 'Deva', 'अनन्यचेताः सततं यो मां स्मरति नित्यशः।
तस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.14', 'transliteration', 'sa', 'Latn', 'ananyacetāḥ satataṃ yo māṃ smarati nityaśaḥ
tasyāhaṃ sulabhaḥ pārtha nityayuktasya yoginaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.14', 'translation', 'en', 'Latn', 'and meditating on me he reaches the highest goal. To the devotee who constantly practises abstraction O son of Pṛthā! and who with a mind not (turned) to anything else is ever and constantly meditating on me I am easy of access.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.14', 'vedic-scriptures', 'BG8.14', 'Devanagari and IAST digital witness');
