INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.15', 'original', 'sa', 'Deva', 'मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम्।
