INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.15', 'translation', 'en', 'Latn', 'The high-souled ones, who achieve the highest perfection, attaining to me, do not again come to life, which is transient, a home of woes.', 'telang-1882');
