INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.16', 'original', 'sa', 'Deva', 'आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन।
