INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.16', 'translation', 'en', 'Latn', 'All worlds O Arjuna ! up to the world of Brahman are (destined) to return. But O son of Kuntī! after attaining to me there is no birth again.', 'telang-1882');
