INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.17', 'translation', 'en', 'Latn', 'Those who know a day of Brahman to end after one thousand ages and the night to terminate after one thousand ages are the persons who know day and night. On the advent of day', 'telang-1882');
