INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.18', 'original', 'sa', 'Deva', 'अव्यक्ताद् व्यक्तयः सर्वाः प्रभवन्त्यहरागमे।
रात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.18', 'transliteration', 'sa', 'Latn', 'avyaktād vyaktayaḥ sarvāḥ prabhavantyaharāgame
