INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.18', 'translation', 'en', 'Latn', 'all perceptible things are produced from the unperceived and on the advent of night they dissolve in that same (principle) called the unperceived.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.18', 'vedic-scriptures', 'BG8.18', 'Devanagari and IAST digital witness');
