INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.8.18', 'अव्यक्ताद् व्यक्तयः सर्वाः प्रभवन्त्यहरागमे।
रात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके ॥', 'avyaktād vyaktayaḥ sarvāḥ prabhavantyaharāgame
rātryāgame pralīyante tatraivāvyaktasaṃjñake', 'all perceptible things are produced from the unperceived and on the advent of night they dissolve in that same (principle) called the unperceived.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.19', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.19', 8, 19, 'Krishna', 'adaa5147b51b9c173a3062eb69a429a4a685d5b9580dd653822ae9387b4ab550', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.19', 'original', 'sa', 'Deva', 'भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते।
रात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.19', 'transliteration', 'sa', 'Latn', 'bhūtagrāmaḥ sa evāyaṃ bhūtvā bhūtvā pralīyate
rātryāgame.avaśaḥ pārtha prabhavatyaharāgame', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.19', 'translation', 'en', 'Latn', 'This same assemblage of entities being produced again and again dissolves on the advent of night and O son of Pṛthā! issues forth on the advent of day', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.19', 'vedic-scriptures', 'BG8.19', 'Devanagari and IAST digital witness');
