INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.20', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.20', 8, 20, 'Krishna', 'dc5bbb3b6602a68332cd393445f7abcfe08f8ab18138321f07148695b17bcf43', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.20', 'original', 'sa', 'Deva', 'परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः।
यः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.20', 'transliteration', 'sa', 'Latn', 'parastasmāttu bhāvo.anyo.avyakto.avyaktātsanātanaḥ
yaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.20', 'translation', 'en', 'Latn', 'without a will of its own. But there is another entity unperceived and eternal and distinct from this unperceived (principle) which is not destroyed when all entities are destroyed. It is called the unperceived, the indestructible', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.20', 'vedic-scriptures', 'BG8.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.20', 'telang-1882', 'Chapter 8; aligned against BG8.20', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.8.20', 'परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः।
यः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति ॥', 'parastasmāttu bhāvo.anyo.avyakto.avyaktātsanātanaḥ
yaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati', 'without a will of its own. But there is another entity unperceived and eternal and distinct from this unperceived (principle) which is not destroyed when all entities are destroyed. It is called the unperceived, the indestructible');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.21', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.21', 8, 21, 'Krishna', '4dbc2b54be2a5343ce3470da598969fc903c3fce5433478d79abee27f89059ef', 'first review verified; second review pending', 0);
