INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.21', 'transliteration', 'sa', 'Latn', 'avyakto.akṣara ityuktastamāhuḥ paramāṃ gatim
