INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.23', 'original', 'sa', 'Deva', 'यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः।
प्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.23', 'transliteration', 'sa', 'Latn', 'yatra kāle tvanāvṛttimāvṛttiṃ caiva yoginaḥ
