INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.23', 'translation', 'en', 'Latn', 'is to be attained to by reverence not (directed) to another. I will state the times, O descendant of Bharata! at which devotees departing (from this world) go, never to return, or to return.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.23', 'vedic-scriptures', 'BG8.23', 'Devanagari and IAST digital witness');
