INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.25', 'original', 'sa', 'Deva', 'धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम्।
तत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.25', 'transliteration', 'sa', 'Latn', 'dhūmo rātristathā kṛṣṇaḥ ṣaṇmāsā dakṣiṇāyanam
tatra cāndramasaṃ jyotiryogī prāpya nivartate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.25', 'translation', 'en', 'Latn', 'departing (from the world) in these those who know the Brahman go to the Brahman. Smoke, night, the dark fortnight, the six months of the southern solstice, (dying) in these, the devotee goes to the lunar light and returns.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.25', 'vedic-scriptures', 'BG8.25', 'Devanagari and IAST digital witness');
