INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.26', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.26', 8, 26, 'Krishna', '7b2110ec73fd897e0bfb08044036540b8c5eec5eebd88d93010fb4d4b31ef64e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.26', 'original', 'sa', 'Deva', 'शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते।
एकया यात्यनावृत्तिमन्ययावर्तते पुनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.26', 'transliteration', 'sa', 'Latn', 'śuklakṛṣṇe gatī hyete jagataḥ śāśvate mate
ekayā yātyanāvṛttimanyayāvartate punaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.26', 'translation', 'en', 'Latn', 'These two paths, bright and dark, are deemed to be eternal in this world. By the one, (a man) goes never to return, by the other he comes back.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.26', 'vedic-scriptures', 'BG8.26', 'Devanagari and IAST digital witness');
