INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.8.27', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.8.27', 8, 27, 'Krishna', '7c26df37de1d6896031f2bb74b2896cf768f90fb9973d694d41d8b79a00967e5', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.27', 'original', 'sa', 'Deva', 'नैते सृती पार्थ जानन्योगी मुह्यति कश्चन।
तस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.27', 'transliteration', 'sa', 'Latn', 'naite sṛtī pārtha jānanyogī muhyati kaścana
tasmātsarveṣu kāleṣu yogayukto bhavārjuna', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.27', 'translation', 'en', 'Latn', 'Knowing these two paths, O son of Pṛthā! no devotee is deluded. Therefore at all times be possessed of devotion O Arjuna! A devotee knowing all this obtains all the holy fruit which is prescribed for (study of) the Vedas', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.8.27', 'vedic-scriptures', 'BG8.27', 'Devanagari and IAST digital witness');
