INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.8.28', 'translation', 'en', 'Latn', 'for sacrifices and also for penances and gifts and he attains to the highest and primeval seat.', 'telang-1882');
