INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.1', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
इदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे।
ज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.1', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
idaṃ tu te guhyatamaṃ pravakṣyāmyanasūyave
jñānaṃ vijñānasahitaṃ yajjñātvā mokṣyase.aśubhāt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.1', 'translation', 'en', 'Latn', 'Now I will speak to you who are not given to carping of that most mysterious knowledge accompanied by experience by knowing which you will be released from evil.', 'telang-1882');
