INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.2', 'translation', 'en', 'Latn', 'It is the chief among the sciences, the chief among the mysteries. It is the best means of sanctification. It is imperishable, not opposed to the sacred law. It is to be apprehended directly, and is easy to practise.', 'telang-1882');
