INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.4', 'transliteration', 'sa', 'Latn', 'mayā tatamidaṃ sarvaṃ jagadavyaktamūrtinā
