INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.4', 'translation', 'en', 'Latn', 'This whole universe is pervaded by me in an unperceived form. All entities live in me, but I do not live in them. Nor yet do all entities live in me.', 'telang-1882');
