INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.5', 'original', 'sa', 'Deva', 'न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम्।
