INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.7', 'original', 'sa', 'Deva', 'सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम्।
