INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.7', 'transliteration', 'sa', 'Latn', 'sarvabhūtāni kaunteya prakṛtiṃ yānti māmikām
