INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.7', 'translation', 'en', 'Latn', 'At the expiration of a Kalpa , O son of Kuntī ! all entities enter my nature and at the beginning of a Kalpa, I again bring them forth.', 'telang-1882');
