INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.8', 'original', 'sa', 'Deva', 'प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः।
