INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.8', 'transliteration', 'sa', 'Latn', 'prakṛtiṃ svāmavaṣṭabhya visṛjāmi punaḥ punaḥ
