INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.8', 'translation', 'en', 'Latn', 'Taking the control of my own nature I bring forth again and again this whole collection of entities without a will of its own by the power of nature. But', 'telang-1882');
