INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.9', 'transliteration', 'sa', 'Latn', 'na ca māṃ tāni karmāṇi nibadhnanti dhanañjaya
