INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.9', 'translation', 'en', 'Latn', 'O Arjuna ! these actions do not fetter me who remain like one unconcerned and who am unattached to those actions.', 'telang-1882');
