INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.13', 'original', 'sa', 'Deva', 'महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः।
भजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.13', 'transliteration', 'sa', 'Latn', 'mahātmānastu māṃ pārtha daivīṃ prakṛtimāśritāḥ
bhajantyananyamanaso jñātvā bhūtādimavyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.13', 'translation', 'en', 'Latn', 'whose minds are disordered and who are inclined to the delusive nature of Asuras and Rākṣasas not knowing my highest nature as great lord of all entities disregard me as I have assumed a human body. But the high-souled ones O son of Pṛthā! who are inclined to the godlike nature knowing me as the inexhaustible source of (all) entities', 'telang-1882');
