INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.14', 'original', 'sa', 'Deva', 'सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः।
नमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.14', 'transliteration', 'sa', 'Latn', 'satataṃ kīrtayanto māṃ yatantaśca dṛḍhavratāḥ
namasyantaśca māṃ bhaktyā nityayuktā upāsate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.14', 'translation', 'en', 'Latn', 'worship me with minds not (turned) elsewhere. Constantly glorifying me, and exerting themselves, firm in their vows, and saluting me with reverence,', 'telang-1882');
