INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.15', 'original', 'sa', 'Deva', 'ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते।
