INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.15', 'translation', 'en', 'Latn', 'they worship me, being always devoted. And others again, offering up the sacrifice of knowledge, worship me as one, as distinct, and as all-pervading in numerous forms.', 'telang-1882');
