INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.16', 'original', 'sa', 'Deva', 'अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम्।
मन्त्रोऽहमहमेवाज्यमहमग्निरहं हुतम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.16', 'transliteration', 'sa', 'Latn', 'ahaṃ kraturahaṃ yajñaḥ svadhāhamahamauṣadham
mantro.ahamahamevājyamahamagnirahaṃ hutam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.16', 'translation', 'en', 'Latn', 'I am the Kratu, I am the Yajña, I am the Svadhā, I the product of the herbs. I am the sacred verse. I too am the sacrificial butter, and I the fire, I the offering. I am the father of this universe', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.16', 'vedic-scriptures', 'BG9.16', 'Devanagari and IAST digital witness');
