INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.18', 'original', 'sa', 'Deva', 'गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत्।
प्रभवः प्रलयः स्थानं निधानं बीजमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.18', 'transliteration', 'sa', 'Latn', 'gatirbhartā prabhuḥ sākṣī nivāsaḥ śaraṇaṃ suhṛt
