INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.19', 'original', 'sa', 'Deva', 'तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च।
अमृतं चैव मृत्युश्च सदसच्चाहमर्जुन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.19', 'transliteration', 'sa', 'Latn', 'tapāmyahamahaṃ varṣaṃ nigṛhṇāmyutsṛjāmi ca
amṛtaṃ caiva mṛtyuśca sadasaccāhamarjuna', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.19', 'translation', 'en', 'Latn', 'I cause heat and I send forth and stop showers. I am immortality and also death and I, O Arjuna! am that which is and that which is not.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.19', 'vedic-scriptures', 'BG9.19', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.19', 'telang-1882', 'Chapter 9; aligned against BG9.19', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.9.19', 'तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च।
अमृतं चैव मृत्युश्च सदसच्चाहमर्जुन ॥', 'tapāmyahamahaṃ varṣaṃ nigṛhṇāmyutsṛjāmi ca
amṛtaṃ caiva mṛtyuśca sadasaccāhamarjuna', 'I cause heat and I send forth and stop showers. I am immortality and also death and I, O Arjuna! am that which is and that which is not.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.9.20', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.9.20', 9, 20, 'Krishna', '870ba431828a2a352e1428bef5483e2d271c0f9d76f3705a4bea0bc3b955b0f0', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.20', 'original', 'sa', 'Deva', 'त्रैविद्या मां सोमपाः पूतपापा
यज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते।
ते पुण्यमासाद्य सुरेन्द्रलोक-
मश्नन्ति दिव्यान्दिवि देवभोगान् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.20', 'transliteration', 'sa', 'Latn', 'traividyā māṃ somapāḥ pūtapāpā yajñairiṣṭvā svargatiṃ prārthayante
te puṇyamāsādya surendralokaṃ aśnanti divyāndivi devabhogān', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.20', 'translation', 'en', 'Latn', 'Those who know the three (branches of) knowledge who drink the Soma juice whose sins are washed away offer sacrifices and pray to me for a passage into heaven and reaching the holy world of the lord of gods they enjoy in the celestial regions the celestial pleasures of the gods. And having enjoyed that great heavenly world', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.20', 'vedic-scriptures', 'BG9.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.20', 'telang-1882', 'Chapter 9; aligned against BG9.20', 'English translation witness');
