INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.9.30', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.9.30', 9, 30, 'Krishna', '04f2afa54b8fe881e83b08e05fabc6e7d0f6c3932511b573fdac076e3f487325', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.30', 'original', 'sa', 'Deva', 'अपि चेत्सुदुराचारो भजते मामनन्यभाक्।
साधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.30', 'transliteration', 'sa', 'Latn', 'api cetsudurācāro bhajate māmananyabhāk
sādhureva sa mantavyaḥ samyagvyavasito hi saḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.30', 'translation', 'en', 'Latn', 'Even if a very ill-conducted man worships me, not worshipping any one else, he must certainly be deemed to be good, for he has well resolved.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.30', 'vedic-scriptures', 'BG9.30', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.30', 'telang-1882', 'Chapter 9; aligned against BG9.30', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.9.30', 'अपि चेत्सुदुराचारो भजते मामनन्यभाक्।
साधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः ॥', 'api cetsudurācāro bhajate māmananyabhāk
sādhureva sa mantavyaḥ samyagvyavasito hi saḥ', 'Even if a very ill-conducted man worships me, not worshipping any one else, he must certainly be deemed to be good, for he has well resolved.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.9.31', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.9.31', 9, 31, 'Krishna', '24e793fcb6462697a5d1da981d7c5fd999b8b4ab08ad5e3352a1eb2022a9e033', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.31', 'original', 'sa', 'Deva', 'क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति।
कौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.31', 'transliteration', 'sa', 'Latn', 'kṣipraṃ bhavati dharmātmā śaśvacchāntiṃ nigacchati
kaunteya pratijānīhi na me bhaktaḥ praṇaśyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.31', 'translation', 'en', 'Latn', 'He soon becomes devout of heart, and obtains lasting tranquillity. (You may) affirm, O son of Kuntī! that my devotee is never ruined. For, O son of Pṛthā! even those who are of sinful birth, women, Vaiśyas', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.31', 'vedic-scriptures', 'BG9.31', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.31', 'telang-1882', 'Chapter 9; aligned against BG9.31', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.9.31', 'क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति।
कौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति ॥', 'kṣipraṃ bhavati dharmātmā śaśvacchāntiṃ nigacchati
kaunteya pratijānīhi na me bhaktaḥ praṇaśyati', 'He soon becomes devout of heart, and obtains lasting tranquillity. (You may) affirm, O son of Kuntī! that my devotee is never ruined. For, O son of Pṛthā! even those who are of sinful birth, women, Vaiśyas');
