INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.32', 'original', 'sa', 'Deva', 'मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः।
स्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.32', 'transliteration', 'sa', 'Latn', 'māṃ hi pārtha vyapāśritya ye.api syuḥ pāpayonayaḥ
striyo vaiśyāstathā śūdrāste.api yānti parāṃ gatim', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.32', 'translation', 'en', 'Latn', 'and Śūdras likewise, resorting to me, attain the supreme goal.', 'telang-1882');
