INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.9.33', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.9.33', 9, 33, 'Krishna', '11c9576c245e1ec6dfa99ea113321f7071c746a09bbe7c92b7a73cc9381d4fca', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.33', 'original', 'sa', 'Deva', 'किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा।
अनित्यमसुखं लोकमिमं प्राप्य भजस्व माम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.33', 'transliteration', 'sa', 'Latn', 'kiṃ punarbrāhmaṇāḥ puṇyā bhaktā rājarṣayastathā
anityamasukhaṃ lokamimaṃ prāpya bhajasva mām', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.33', 'translation', 'en', 'Latn', 'What then (need be said of) holy Brāhmaṇas and royal saints who are (my) devotees? Coming to this transient unhappy world, worship me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.33', 'vedic-scriptures', 'BG9.33', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.33', 'telang-1882', 'Chapter 9; aligned against BG9.33', 'English translation witness');
