INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.34', 'original', 'sa', 'Deva', 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।
मामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.34', 'transliteration', 'sa', 'Latn', 'manmanā bhava madbhakto madyājī māṃ namaskuru
māmevaiṣyasi yuktvaivamātmānaṃ matparāyaṇaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.9.34', 'translation', 'en', 'Latn', '(Place your) mind on me, become my devotee, my worshipper reverence me, and thus making me your highest goal, and devoting your self to abstraction, you will certainly come to me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.34', 'vedic-scriptures', 'BG9.34', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.9.34', 'telang-1882', 'Chapter 9; aligned against BG9.34', 'English translation witness');
