INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.1', 10, 1, 'Krishna', '785daead151ddb612b7cd3ae0079c3990cf723d1b921e16fdc6a9c10bbfa544f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.1', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
भूय एव महाबाहो शृणु मे परमं वचः।
यत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.1', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
bhūya eva mahābāho śṛṇu me paramaṃ vacaḥ
yatte.ahaṃ prīyamāṇāya vakṣyāmi hitakāmyayā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.1', 'translation', 'en', 'Latn', 'Yet again O you of mighty arms! listen to my excellent words which out of a wish for your welfare I speak to you who are delighted (with them).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.1', 'vedic-scriptures', 'BG10.1', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.1', 'telang-1882', 'Chapter 10; aligned against BG10.1', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.10.1', 'श्रीभगवानुवाच।
भूय एव महाबाहो शृणु मे परमं वचः।
यत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया ॥', 'śrībhagavānuvāca
bhūya eva mahābāho śṛṇu me paramaṃ vacaḥ
yatte.ahaṃ prīyamāṇāya vakṣyāmi hitakāmyayā', 'Yet again O you of mighty arms! listen to my excellent words which out of a wish for your welfare I speak to you who are delighted (with them).');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.2', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.2', 10, 2, 'Krishna', '9b7e23d576f4acb798ae3acc2f58415f52a0348d80021cd8362be0e04a241016', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.2', 'original', 'sa', 'Deva', 'न मे विदुः सुरगणाः प्रभवं न महर्षयः।
अहमादिर्हि देवानां महर्षीणां च सर्वशः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.2', 'transliteration', 'sa', 'Latn', 'na me viduḥ suragaṇāḥ prabhavaṃ na maharṣayaḥ
ahamādirhi devānāṃ maharṣīṇāṃ ca sarvaśaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.2', 'translation', 'en', 'Latn', 'Not the multitudes of gods, nor the great sages know my source for I am in every way the origin of the gods and great sages. Of (all) mortals he who knows me to be unborn without beginning', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.2', 'vedic-scriptures', 'BG10.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.2', 'telang-1882', 'Chapter 10; aligned against BG10.2', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.10.2', 'न मे विदुः सुरगणाः प्रभवं न महर्षयः।
