INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.3', 'original', 'sa', 'Deva', 'यो मामजमनादिं च वेत्ति लोकमहेश्वरम्।
असम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.3', 'transliteration', 'sa', 'Latn', 'yo māmajamanādiṃ ca vetti lokamaheśvaram
