INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.3', 'translation', 'en', 'Latn', 'the great lord of the world being free from delusion is released from all sins. Intelligence knowledge freedom from delusion', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.3', 'vedic-scriptures', 'BG10.3', 'Devanagari and IAST digital witness');
