INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.6', 'transliteration', 'sa', 'Latn', 'maharṣayaḥ sapta pūrve catvāro manavastathā
madbhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.6', 'translation', 'en', 'Latn', 'contentment penance, (making) gifts glory disgrace all these different tempers of living beings are from me alone. The seven great sages and likewise the four ancient Manus whose descendants are (all) these people in the world were all born from my mind, (partaking) of my powers.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.6', 'vedic-scriptures', 'BG10.6', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.6', 'telang-1882', 'Chapter 10; aligned against BG10.6', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.10.6', 'महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा।
मद्भावा मानसा जाता येषां लोक इमाः प्रजाः ॥', 'maharṣayaḥ sapta pūrve catvāro manavastathā
madbhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ', 'contentment penance, (making) gifts glory disgrace all these different tempers of living beings are from me alone. The seven great sages and likewise the four ancient Manus whose descendants are (all) these people in the world were all born from my mind, (partaking) of my powers.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.7', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.7', 10, 7, 'Krishna', '818d33ba5fdf69ab0e36f89b4f1fc0a7227f88e9531dd5168c7c5099f36c0495', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.7', 'original', 'sa', 'Deva', 'एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः।
सोऽविकम्पेन योगेन युज्यते नात्र संशयः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.7', 'transliteration', 'sa', 'Latn', 'etāṃ vibhūtiṃ yogaṃ ca mama yo vetti tattvataḥ
so.avikampena yogena yujyate nātra saṃśayaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.7', 'translation', 'en', 'Latn', 'Whoever correctly knows these powers and emanations of mine, becomes possessed of devotion free from indecision of this (there is) no doubt.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.7', 'vedic-scriptures', 'BG10.7', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.7', 'telang-1882', 'Chapter 10; aligned against BG10.7', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.10.7', 'एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः।
