INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.8', 'original', 'sa', 'Deva', 'अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते।
इति मत्वा भजन्ते मां बुधा भावसमन्विताः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.8', 'transliteration', 'sa', 'Latn', 'ahaṃ sarvasya prabhavo mattaḥ sarvaṃ pravartate
iti matvā bhajante māṃ budhā bhāvasamanvitāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.8', 'translation', 'en', 'Latn', 'The wise, full of love, worship me, believing that I am the origin of all, and that all moves on through me. (Placing their) minds on me offering (their) lives to me', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.8', 'vedic-scriptures', 'BG10.8', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.8', 'telang-1882', 'Chapter 10; aligned against BG10.8', 'English translation witness');
