INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.10', 'original', 'sa', 'Deva', 'तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम्।
ददामि बुद्धियोगं तं येन मामुपयान्ति ते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.10', 'transliteration', 'sa', 'Latn', 'teṣāṃ satatayuktānāṃ bhajatāṃ prītipūrvakam
dadāmi buddhiyogaṃ taṃ yena māmupayānti te', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.10', 'translation', 'en', 'Latn', 'they are always contented and happy. To these who are constantly devoted and who worship with love, I give that knowledge by which they attain to me. And remaining in their hearts', 'telang-1882');
