INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.14', 'translation', 'en', 'Latn', 'you tell me yourself O Kesava! I believe all this that you tell me (to be) true for, O lord! neither the gods nor demons understand your manifestation.', 'telang-1882');
