INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.15', 'translation', 'en', 'Latn', 'You only know your self by your self. O best of beings! creator of all things! lord of all things! god of gods! lord of the universe! be pleased to declare without', 'telang-1882');
