INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.16', 'original', 'sa', 'Deva', 'वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः।
