INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.16', 'transliteration', 'sa', 'Latn', 'vaktumarhasyaśeṣeṇa divyā hyātmavibhūtayaḥ
yābhirvibhūtibhirlokānimāṃstvaṃ vyāpya tiṣṭhasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.16', 'translation', 'en', 'Latn', 'exception your divine emanations by which emanations you stand pervading all these worlds.', 'telang-1882');
