INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.17', 10, 17, 'Arjuna', '2e9d7ccefbdf687667e5dac88c1847148134b67468e886c6189adee5dc0f77fa', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.17', 'original', 'sa', 'Deva', 'कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन्।
केषु केषु च भावेषु चिन्त्योऽसि भगवन्मया ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.17', 'transliteration', 'sa', 'Latn', 'kathaṃ vidyāmahaṃ yogiṃstvāṃ sadā paricintayan
keṣu keṣu ca bhāveṣu cintyo.asi bhagavanmayā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.17', 'translation', 'en', 'Latn', 'How shall I know you, O you of mystic power! always meditating on you? And in what various entities, O lord! should I meditate on you?', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.17', 'vedic-scriptures', 'BG10.17', 'Devanagari and IAST digital witness');
