INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.19', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.19', 10, 19, 'Krishna', '4d8eb6a2c4044a9ed176cfdfe6bf39218b853f2a7885bbdf7dcf512e6b409b3d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.19', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
हन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः।
प्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.19', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
hanta te kathayiṣyāmi divyā hyātmavibhūtayaḥ
prādhānyataḥ kuruśreṣṭha nāstyanto vistarasya me', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.19', 'translation', 'en', 'Latn', 'Well then, O best of Kauravas! I will state to you my own divine emanations but (only) the chief (ones), for there is no end to the extent of my (emanations).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.19', 'vedic-scriptures', 'BG10.19', 'Devanagari and IAST digital witness');
