INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.20', 'transliteration', 'sa', 'Latn', 'ahamātmā guḍākeśa sarvabhūtāśayasthitaḥ
ahamādiśca madhyaṃ ca bhūtānāmanta eva ca', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.20', 'translation', 'en', 'Latn', 'I am the self, O Guḍākesa! seated in the hearts of all beings. I am the beginning and the middle and the end also of all beings.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.20', 'vedic-scriptures', 'BG10.20', 'Devanagari and IAST digital witness');
