INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.21', 'original', 'sa', 'Deva', 'आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान्।
