INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.21', 'transliteration', 'sa', 'Latn', 'ādityānāmahaṃ viṣṇurjyotiṣāṃ raviraṃśumān
