INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.21', 'translation', 'en', 'Latn', 'I am Viṣṇu among the Ādityas , the beaming sun among the shining (bodies) I am Marīci among the Maruts , and the moon among the lunar mansions.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.21', 'vedic-scriptures', 'BG10.21', 'Devanagari and IAST digital witness');
