INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.22', 'transliteration', 'sa', 'Latn', 'vedānāṃ sāmavedo.asmi devānāmasmi vāsavaḥ
