INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.22', 'translation', 'en', 'Latn', 'Among the Vedas , I am the Sāma - veda . I am Indra among the gods. And I am mind among the senses.', 'telang-1882');
