INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.23', 'original', 'sa', 'Deva', 'रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम्।
वसूनां पावकश्चास्मि मेरुः शिखरिणामहम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.23', 'transliteration', 'sa', 'Latn', 'rudrāṇāṃ śaṅkaraścāsmi vitteśo yakṣarakṣasām
vasūnāṃ pāvakaścāsmi meruḥ śikhariṇāmaham', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.23', 'translation', 'en', 'Latn', 'I am consciousness in (living) beings. And I am Śaṅkara among the Rudras the lord of wealth among Yakṣas and Rakṣases. And I am fire among the Vasus and Meru among the high-topped (mountains). And know me', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.23', 'vedic-scriptures', 'BG10.23', 'Devanagari and IAST digital witness');
