INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.24', 'original', 'sa', 'Deva', 'पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम्।
सेनानीनामहं स्कन्दः सरसामस्मि सागरः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.24', 'transliteration', 'sa', 'Latn', 'purodhasāṃ ca mukhyaṃ māṃ viddhi pārtha bṛhaspatim
senānīnāmahaṃ skandaḥ sarasāmasmi sāgaraḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.24', 'translation', 'en', 'Latn', 'O Arjuna ! to be Bṛhaspati the chief among domestic priests. I am Skanda among generals. I am the ocean among reservoirs of water.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.24', 'vedic-scriptures', 'BG10.24', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.10.24', 'telang-1882', 'Chapter 10; aligned against BG10.24', 'English translation witness');
