INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.25', 'original', 'sa', 'Deva', 'महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम्।
यज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.25', 'transliteration', 'sa', 'Latn', 'maharṣīṇāṃ bhṛgurahaṃ girāmasmyekamakṣaram
yajñānāṃ japayajño.asmi sthāvarāṇāṃ himālayaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.25', 'translation', 'en', 'Latn', 'I am Bhṛgu among the great sages. I am the single syllable (Om) among words. Among sacrifices I am the Japa sacrifice the Himālaya among the firmly-fixed (mountains)', 'telang-1882');
