INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.10.25', 'महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम्।
यज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः ॥', 'maharṣīṇāṃ bhṛgurahaṃ girāmasmyekamakṣaram
yajñānāṃ japayajño.asmi sthāvarāṇāṃ himālayaḥ', 'I am Bhṛgu among the great sages. I am the single syllable (Om) among words. Among sacrifices I am the Japa sacrifice the Himālaya among the firmly-fixed (mountains)');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.26', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.26', 10, 26, 'Krishna', 'd41e0497f015425f3180ecdc5d7ccbf034e1b568d07eae4db391d4cb8cca4b3b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.26', 'original', 'sa', 'Deva', 'अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः।
गन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.26', 'transliteration', 'sa', 'Latn', 'aśvatthaḥ sarvavṛkṣāṇāṃ devarṣīṇāṃ ca nāradaḥ
gandharvāṇāṃ citrarathaḥ siddhānāṃ kapilo muniḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.26', 'translation', 'en', 'Latn', 'the Aśvattha among all trees, and Nārada among divine sages Citraratha among the heavenly choristers, the sage Kapila among the Siddhas .', 'telang-1882');
