INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.27', 'translation', 'en', 'Latn', 'Among horses know me to be Uccaiśśravas, brought forth by (the labours for) the nectar and Airāvata among the great elephants, and the ruler. of men among men.', 'telang-1882');
