INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.10.35', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.10.35', 10, 35, 'Krishna', '96537b90ed93c56aea66d1520b6eff73c595bd1c6dd736de12f85515c8747d21', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.35', 'original', 'sa', 'Deva', 'बृहत्साम तथा साम्नां गायत्री छन्दसामहम्।
