INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.35', 'transliteration', 'sa', 'Latn', 'bṛhatsāma tathā sāmnāṃ gāyatrī chandasāmaham
