INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.35', 'translation', 'en', 'Latn', 'Likewise among Sāman hymns, I am the Bṛhat-sāman, and I the Gāyatrī among metres. I am Mārgaśīrṣa among the months, the spring among the seasons', 'telang-1882');
