INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.37', 'original', 'sa', 'Deva', 'वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनञ्जयः।
