INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.38', 'translation', 'en', 'Latn', 'I am the rod of those that restrain, and the policy of those that desire victory. I am silence respecting secrets.', 'telang-1882');
