INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.39', 'transliteration', 'sa', 'Latn', 'yaccāpi sarvabhūtānāṃ bījaṃ tadahamarjuna
