INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.39', 'translation', 'en', 'Latn', 'I am the knowledge of those that have knowledge And, O Arjuna! I am also that which is the seed of all things. There is nothing movable or immovable which can exist without me.', 'telang-1882');
