INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.40', 'transliteration', 'sa', 'Latn', 'nānto.asti mama divyānāṃ vibhūtīnāṃ parantapa
