INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.41', 'translation', 'en', 'Latn', 'Here I have declared the extent of (those) emanations only in part. Whatever thing (there is) of power or glorious or splendid know all that to be produced from portions of my energy. Or rather', 'telang-1882');
