INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.10.42', 'translation', 'en', 'Latn', 'O Arjuna! what have you to do knowing all this at large? I stand supporting all this by (but) a single portion (of myself).', 'telang-1882');
