INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.1', 11, 1, 'Arjuna', 'bace603779302d63848ba7e410874d7bca9b216841ac1f2fa68de112fefbc33f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.1', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
मदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम्।
यत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.1', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
madanugrahāya paramaṃ guhyamadhyātmasaṃjñitam
yattvayoktaṃ vacastena moho.ayaṃ vigato mama', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.1', 'translation', 'en', 'Latn', 'In consequence of the excellent and mysterious words concerning the relation of the supreme and individual soul, which you have spoken for my welfare this delusion of mine is gone away.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.1', 'vedic-scriptures', 'BG11.1', 'Devanagari and IAST digital witness');
