INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.2', 'original', 'sa', 'Deva', 'भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया।
