INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.2', 'transliteration', 'sa', 'Latn', 'bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā
tvattaḥ kamalapatrākṣa māhātmyamapi cāvyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.2', 'translation', 'en', 'Latn', 'O you whose eyes are like lotus leaves! I have heard from you at large about the production and dissolution of things, and also about your inexhaustible greatness. O highest lord! what you have said about yourself is so.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.2', 'vedic-scriptures', 'BG11.2', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.2', 'telang-1882', 'Chapter 11; aligned against BG11.2', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.11.2', 'भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया।
त्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम् ॥', 'bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā
tvattaḥ kamalapatrākṣa māhātmyamapi cāvyayam', 'O you whose eyes are like lotus leaves! I have heard from you at large about the production and dissolution of things, and also about your inexhaustible greatness. O highest lord! what you have said about yourself is so.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.3', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.3', 11, 3, 'Arjuna', '6340f387e968e9512d7c1a31b3d16796d70b379acddd862f1166d988ed1ff5fb', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.3', 'original', 'sa', 'Deva', 'एवमेतद्यथात्थ त्वमात्मानं परमेश्वर।
द्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.3', 'transliteration', 'sa', 'Latn', 'evametadyathāttha tvamātmānaṃ parameśvara
draṣṭumicchāmi te rūpamaiśvaraṃ puruṣottama', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.3', 'translation', 'en', 'Latn', 'I wish, O best of beings! to see your divine form. If', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.3', 'vedic-scriptures', 'BG11.3', 'Devanagari and IAST digital witness');
