INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.4', 11, 4, 'Arjuna', '8086a301652779ff65ae1ab3e197a665ac4e17005043f700184063d63ed90d42', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.4', 'original', 'sa', 'Deva', 'मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो।
योगेश्वर ततो मे त्वं दर्शयात्मानमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.4', 'transliteration', 'sa', 'Latn', 'manyase yadi tacchakyaṃ mayā draṣṭumiti prabho
yogeśvara tato me tvaṃ darśayātmānamavyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.4', 'translation', 'en', 'Latn', 'O lord! you think that it is possible for me to look upon it then O lord of the possessors of mystic power! show your inexhaustible form to me.', 'telang-1882');
