INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.5', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.5', 11, 5, 'Krishna', 'fa5f9e783486deec2997656dd7d40f933cb256faf58abdc104dc5924fccb914e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.5', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
पश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः।
नानाविधानि दिव्यानि नानावर्णाकृतीनि च ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.5', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
paśya me pārtha rūpāṇi śataśo.atha sahasraśaḥ
nānāvidhāni divyāni nānāvarṇākṛtīni ca', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.5', 'translation', 'en', 'Latn', 'In hundreds and in thousands see my forms, O son of Pṛthā! various, divine, and of various colours and shapes.', 'telang-1882');
