INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.6', 'original', 'sa', 'Deva', 'पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा।
