INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.6', 'translation', 'en', 'Latn', 'See the Ādityas , Vasus , Rudras , the two Aśvins , and Maruts likewise. And O descendant of Bharata! see wonders, in numbers, unseen before. Within my body', 'telang-1882');
