INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.7', 'original', 'sa', 'Deva', 'इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम्।
मम देहे गुडाकेश यच्चान्यद् द्रष्टुमिच्छसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.7', 'transliteration', 'sa', 'Latn', 'ihaikasthaṃ jagatkṛtsnaṃ paśyādya sacarācaram
