INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.8', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.8', 11, 8, 'Krishna', 'ae8b2e3d51e2160c412badae23078aefebde0a51f352197a05415402e66c2604', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.8', 'original', 'sa', 'Deva', 'न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा।
दिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.8', 'transliteration', 'sa', 'Latn', 'na tu māṃ śakyase draṣṭumanenaiva svacakṣuṣā
divyaṃ dadāmi te cakṣuḥ paśya me yogamaiśvaram', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.8', 'translation', 'en', 'Latn', 'including (everything) movable and immovable, (all) in one and whatever else you wish to see. But you will not be able to see me with merely this eye of yours. I give you an eye divine. (Now) see my divine power.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.8', 'vedic-scriptures', 'BG11.8', 'Devanagari and IAST digital witness');
