INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.9', 'original', 'sa', 'Deva', 'सञ्जय उवाच।
एवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः।
दर्शयामास पार्थाय परमं रूपमैश्वरम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.9', 'transliteration', 'sa', 'Latn', 'sañjaya uvāca
evamuktvā tato rājanmahāyogeśvaro hariḥ
darśayāmāsa pārthāya paramaṃ rūpamaiśvaram', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.9', 'translation', 'en', 'Latn', 'Having spoken thus O king! Hari', 'telang-1882');
