INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.12', 'original', 'sa', 'Deva', 'दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता।
यदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.12', 'transliteration', 'sa', 'Latn', 'divi sūryasahasrasya bhavedyugapadutthitā
yadi bhāḥ sadṛśī sā syādbhāsastasya mahātmanaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.12', 'translation', 'en', 'Latn', 'If in the heavens, the lustre of a thousand suns burst forth all at once, that would be like the lustre of that mighty one.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.12', 'vedic-scriptures', 'BG11.12', 'Devanagari and IAST digital witness');
