INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.13', 'transliteration', 'sa', 'Latn', 'tatraikasthaṃ jagatkṛtsnaṃ pravibhaktamanekadhā
