INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.13', 'translation', 'en', 'Latn', 'There the son of Pāṇḍu then observed in the body of the god of gods the whole universe (all) in one, and divided into numerous (divisions).', 'telang-1882');
