INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.14', 'original', 'sa', 'Deva', 'ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः।
प्रणम्य शिरसा देवं कृताञ्जलिरभाषत ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.14', 'transliteration', 'sa', 'Latn', 'tataḥ sa vismayāviṣṭo hṛṣṭaromā dhanañjayaḥ
praṇamya śirasā devaṃ kṛtāñjalirabhāṣata', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.14', 'translation', 'en', 'Latn', 'Then Dhanañjaya filled with amazement, and with hair standing on end, bowed his head before the god, and spoke with joined hands.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.14', 'vedic-scriptures', 'BG11.14', 'Devanagari and IAST digital witness');
