INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.15', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
पश्यामि देवांस्तव देव देहे
सर्वांस्तथा भूतविशेषसङ्घान्।
ब्रह्माणमीशं कमलासनस्थ-
मृषींश्च सर्वानुरगांश्च दिव्यान् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.15', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
paśyāmi devāṃstava deva dehe sarvāṃstathā bhūtaviśeṣasaṅghān
brahmāṇamīśaṃ kamalāsanasthaṃ ṛṣīṃśca sarvānuragāṃśca divyān', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.15', 'translation', 'en', 'Latn', 'O god! I see within your body the gods, as also all the groups of various beings and the lord Brahman seated on (his) lotus seat, and all the sages and celestial snakes.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.15', 'vedic-scriptures', 'BG11.15', 'Devanagari and IAST digital witness');
