INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.16', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.16', 11, 16, 'Arjuna', 'b368eb8325aad355144fd496fb288e860d2218187c1f95b8fcff62d628d854be', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.16', 'original', 'sa', 'Deva', 'अनेकबाहूदरवक्त्रनेत्रं
पश्यामि त्वां सर्वतोऽनन्तरूपम्।
नान्तं न मध्यं न पुनस्तवादिं
पश्यामि विश्वेश्वर विश्वरूप ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.16', 'transliteration', 'sa', 'Latn', 'anekabāhūdaravaktranetraṃ paśyāmi tvāṃ sarvato.anantarūpam
nāntaṃ na madhyaṃ na punastavādiṃ paśyāmi viśveśvara viśvarūpa', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.16', 'translation', 'en', 'Latn', 'I see you, who are of countless forms, possessed of many arms, stomachs, mouths, and eyes on all sides. And, O lord of the universe! O you of all forms!', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.16', 'vedic-scriptures', 'BG11.16', 'Devanagari and IAST digital witness');
