INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.17', 11, 17, 'Arjuna', 'a262c8083e65d696c58d3ceac83e9c55015ed99958a8b597552b06a01a406d4a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.17', 'original', 'sa', 'Deva', 'किरीटिनं गदिनं चक्रिणं च
तेजोराशिं सर्वतो दीप्तिमन्तम्।
पश्यामि त्वां दुर्निरीक्ष्यं समन्ताद्
दीप्तानलार्कद्युतिमप्रमेयम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.17', 'transliteration', 'sa', 'Latn', 'kirīṭinaṃ gadinaṃ cakriṇaṃ ca tejorāśiṃ sarvato dīptimantam
paśyāmi tvāṃ durnirīkṣyaṃ samantād dīptānalārkadyutimaprameyam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.17', 'translation', 'en', 'Latn', 'I do not see your end or middle or beginning. I see you bearing a coronet and a mace and a discus—a mass of glory brilliant on all sides difficult to look at having on all sides the effulgence of a blazing fire or sun and indefinable.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.17', 'vedic-scriptures', 'BG11.17', 'Devanagari and IAST digital witness');
