INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.18', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.18', 11, 18, 'Arjuna', 'a009638428f109d20502883434db3dfba8b6d8f1324b5b4c0f34286f495270e5', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.18', 'original', 'sa', 'Deva', 'त्वमक्षरं परमं वेदितव्यं
त्वमस्य विश्वस्य परं निधानम्।
त्वमव्ययः शाश्वतधर्मगोप्ता
सनातनस्त्वं पुरुषो मतो मे ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.18', 'transliteration', 'sa', 'Latn', 'tvamakṣaraṃ paramaṃ veditavyaṃ tvamasya viśvasya paraṃ nidhānam
tvamavyayaḥ śāśvatadharmagoptā sanātanastvaṃ puruṣo mato me', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.18', 'translation', 'en', 'Latn', 'You are indestructible, the supreme one to be known. You are the highest support of this universe. You are the inexhaustible protector of everlasting piety. I believe you to be the eternal being.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.18', 'vedic-scriptures', 'BG11.18', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.18', 'telang-1882', 'Chapter 11; aligned against BG11.18', 'English translation witness');
