INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.20', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.20', 11, 20, 'Arjuna', 'a3dd284d40cf9f29fc57ce460f27e874505552f7c3a5719570edc7f3c307b1db', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.20', 'original', 'sa', 'Deva', 'द्यावापृथिव्योरिदमन्तरं हि
व्याप्तं त्वयैकेन दिशश्च सर्वाः।
दृष्ट्वाद्भुतं रूपमुग्रं तवेदं
लोकत्रयं प्रव्यथितं महात्मन् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.20', 'transliteration', 'sa', 'Latn', 'dyāvāpṛthivyoridamantaraṃ hi vyāptaṃ tvayaikena diśaśca sarvāḥ
dṛṣṭvādbhutaṃ rūpamugraṃ tavedaṃ lokatrayaṃ pravyathitaṃ mahātman', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.20', 'translation', 'en', 'Latn', 'and heating the universe with your radiance. For this space between heaven and earth and all the quarters are pervaded by you alone. Looking at this wonderful and terrible form of yours, O high-souled one! the three worlds are affrighted. For here these groups of gods are entering into you.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.20', 'vedic-scriptures', 'BG11.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.20', 'telang-1882', 'Chapter 11; aligned against BG11.20', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.11.20', 'द्यावापृथिव्योरिदमन्तरं हि
व्याप्तं त्वयैकेन दिशश्च सर्वाः।
दृष्ट्वाद्भुतं रूपमुग्रं तवेदं
लोकत्रयं प्रव्यथितं महात्मन् ॥', 'dyāvāpṛthivyoridamantaraṃ hi vyāptaṃ tvayaikena diśaśca sarvāḥ
dṛṣṭvādbhutaṃ rūpamugraṃ tavedaṃ lokatrayaṃ pravyathitaṃ mahātman', 'and heating the universe with your radiance. For this space between heaven and earth and all the quarters are pervaded by you alone. Looking at this wonderful and terrible form of yours, O high-souled one! the three worlds are affrighted. For here these groups of gods are entering into you.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.21', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.21', 11, 21, 'Arjuna', 'd7a8919385275b8de9bbcb349e97b0cf0c4b1530acc93fa7cb804057bd229325', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.21', 'original', 'sa', 'Deva', 'अमी हि त्वां सुरसङ्घा विशन्ति
केचिद्भीताः प्राञ्जलयो गृणन्ति।
स्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः
स्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.21', 'transliteration', 'sa', 'Latn', 'amī hi tvāṃ surasaṅghā viśanti kecidbhītāḥ prāñjalayo gṛṇanti
svastītyuktvā maharṣisiddhasaṅghāḥ stuvanti tvāṃ stutibhiḥ puṣkalābhiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.21', 'translation', 'en', 'Latn', 'Some being afraid are praying with joined hands, and the groups of great sages and Siddhas are saying ''Welfare!'' and praising you with abundant (hymns) of praise.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.21', 'vedic-scriptures', 'BG11.21', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.21', 'telang-1882', 'Chapter 11; aligned against BG11.21', 'English translation witness');
