INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.24', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.24', 11, 24, 'Arjuna', '5c98462da52e70c2efb6299c6827fe65360800326acda54c11a6f3faa8e0779f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.24', 'original', 'sa', 'Deva', 'नभःस्पृशं दीप्तमनेकवर्णं
व्यात्ताननं दीप्तविशालनेत्रम्।
दृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा
धृतिं न विन्दामि शमं च विष्णो ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.24', 'transliteration', 'sa', 'Latn', 'nabhaḥspṛśaṃ dīptamanekavarṇaṃ vyāttānanaṃ dīptaviśālanetram
dṛṣṭvā hi tvāṃ pravyathitāntarātmā dhṛtiṃ na vindāmi śamaṃ ca viṣṇo', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.24', 'translation', 'en', 'Latn', 'Seeing you O Viṣṇu ! touching the skies radiant possessed of many hues with a gaping mouth and with large blazing eyes I am much alarmed in my inmost self and feel no courage', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.24', 'vedic-scriptures', 'BG11.24', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.24', 'telang-1882', 'Chapter 11; aligned against BG11.24', 'English translation witness');
