INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.25', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.25', 11, 25, 'Arjuna', 'd8626f589a940ccfcf2d610b4f5c6160810e1e227a659cf1f29acc031ad0d87a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.25', 'original', 'sa', 'Deva', 'दंष्ट्राकरालानि च ते मुखानि
दृष्ट्वैव कालानलसन्निभानि।
दिशो न जाने न लभे च शर्म
प्रसीद देवेश जगन्निवास ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.25', 'transliteration', 'sa', 'Latn', 'daṃṣṭrākarālāni ca te mukhāni dṛṣṭvaiva kālānalasannibhāni
diśo na jāne na labhe ca śarma prasīda deveśa jagannivāsa', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.25', 'translation', 'en', 'Latn', 'no tranquillity. And seeing your mouths terrible by the jaws and resembling the fire of destruction I cannot recognise the (various) directions I feel no comfort. Be gracious O lord of gods! who pervadest the universe. And all these sons of Dhṛtarāṣṭra together with all the bands of kings', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.25', 'vedic-scriptures', 'BG11.25', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.25', 'telang-1882', 'Chapter 11; aligned against BG11.25', 'English translation witness');
