INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.26', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.26', 11, 26, 'Arjuna', 'f6ca06b10241badbbb5dce7569db9ea4e9a10c891f50b3855baae870485a5776', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.26', 'original', 'sa', 'Deva', 'अमी च त्वां धृतराष्ट्रस्य पुत्राः
सर्वे सहैवावनिपालसङ्घैः।
भीष्मो द्रोणः सूतपुत्रस्तथासौ
सहास्मदीयैरपि योधमुख्यैः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.26', 'transliteration', 'sa', 'Latn', 'amī ca tvāṃ dhṛtarāṣṭrasya putrāḥ sarve sahaivāvanipālasaṅghaiḥ
bhīṣmo droṇaḥ sūtaputrastathāsau sahāsmadīyairapi yodhamukhyaiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.26', 'translation', 'en', 'Latn', 'and Bhīṣma and Droṇa and this charioteer''s son likewise together with our principal warriors also', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.26', 'vedic-scriptures', 'BG11.26', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.26', 'telang-1882', 'Chapter 11; aligned against BG11.26', 'English translation witness');
