INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.30', 'original', 'sa', 'Deva', 'लेलिह्यसे ग्रसमानः समन्ताल्-
लोकान्समग्रान्वदनैर्ज्वलद्भिः।
तेजोभिरापूर्य जगत्समग्रं
भासस्तवोग्राः प्रतपन्ति विष्णो ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.30', 'transliteration', 'sa', 'Latn', 'lelihyase grasamānaḥ samantāl- lokānsamagrānvadanairjvaladbhiḥ
tejobhirāpūrya jagatsamagraṃ bhāsastavogrāḥ pratapanti viṣṇo', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.30', 'translation', 'en', 'Latn', 'so too do these people enter your mouths with increased velocity (only) to their destruction. Swallowing all these people, you are licking them over and over again from all sides, with your blazing mouths. Your fierce splendours, O Viṣṇu! filling the whole universe with (their) effulgence, are heating it.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.30', 'vedic-scriptures', 'BG11.30', 'Devanagari and IAST digital witness');
