INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.31', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.31', 11, 31, 'Arjuna', '99e8707408f09181362e5968bb3c1d936335065d372e3e3a7295468246c92c0e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.31', 'original', 'sa', 'Deva', 'आख्याहि मे को भवानुग्ररूपो
नमोऽस्तु ते देववर प्रसीद।
विज्ञातुमिच्छामि भवन्तमाद्यं
न हि प्रजानामि तव प्रवृत्तिम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.31', 'transliteration', 'sa', 'Latn', 'ākhyāhi me ko bhavānugrarūpo namo.astu te devavara prasīda
vijñātumicchāmi bhavantamādyaṃ na hi prajānāmi tava pravṛttim', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.31', 'translation', 'en', 'Latn', 'Tell me who you are in this fierce form. Salutations be to thee, O chief of the gods! Be gracious. I wish to know you, the primeval, one, for I do not understand your actions.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.31', 'vedic-scriptures', 'BG11.31', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.31', 'telang-1882', 'Chapter 11; aligned against BG11.31', 'English translation witness');
