INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.33', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.33', 11, 33, 'Krishna', '1267f4ac3affbc9c9988c3ea5e828375fc274816122137567636943ac6d11b78', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.33', 'original', 'sa', 'Deva', 'तस्मात्त्वमुत्तिष्ठ यशो लभस्व
जित्वा शत्रून् भुङ्क्ष्व राज्यं समृद्धम्।
मयैवैते निहताः पूर्वमेव
निमित्तमात्रं भव सव्यसाचिन् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.33', 'transliteration', 'sa', 'Latn', 'tasmāttvamuttiṣṭha yaśo labhasva jitvā śatrūn bhuṅkṣva rājyaṃ samṛddham
mayaivaite nihatāḥ pūrvameva nimittamātraṃ bhava savyasācin', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.33', 'translation', 'en', 'Latn', 'Therefore, be up, obtain glory, and vanquishing (your) foes, enjoy a prosperous kingdom. All these have been already killed by me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.33', 'vedic-scriptures', 'BG11.33', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.33', 'telang-1882', 'Chapter 11; aligned against BG11.33', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.11.33', 'तस्मात्त्वमुत्तिष्ठ यशो लभस्व
जित्वा शत्रून् भुङ्क्ष्व राज्यं समृद्धम्।
