INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.47', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.47', 11, 47, 'Krishna', '830178544440b96148d2c473ee154e19cb596f54b7b2733df765f6ecfff3dfc6', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.47', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
मया प्रसन्नेन तवार्जुनेदं
रूपं परं दर्शितमात्मयोगात्।
तेजोमयं विश्वमनन्तमाद्यं
यन्मे त्वदन्येन न दृष्टपूर्वम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.47', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
mayā prasannena tavārjunedaṃ rūpaṃ paraṃ darśitamātmayogāt
tejomayaṃ viśvamanantamādyaṃ yanme tvadanyena na dṛṣṭapūrvam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.47', 'translation', 'en', 'Latn', 'O Arjuna ! being pleased (with you) I have by my own mystic power shown you this supreme form full of glory universal infinite primeval', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.47', 'vedic-scriptures', 'BG11.47', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.47', 'telang-1882', 'Chapter 11; aligned against BG11.47', 'English translation witness');
