INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.48', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.48', 11, 48, 'Krishna', '9c8889186ae094f18cadd382fab706450cea9f77a62adb1318828e8b60e13314', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.48', 'original', 'sa', 'Deva', 'न वेदयज्ञाध्ययनैर्न दानैर्-
न च क्रियाभिर्न तपोभिरुग्रैः।
एवंरूपः शक्य अहं नृलोके
द्रष्टुं त्वदन्येन कुरुप्रवीर ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.48', 'transliteration', 'sa', 'Latn', 'na vedayajñādhyayanairna dānaira- na ca kriyābhirna tapobhirugraiḥ
evaṃrūpaḥ śakya ahaṃ nṛloke draṣṭuṃ tvadanyena kurupravīra', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.48', 'translation', 'en', 'Latn', 'and which has not been seen before by any one else but you O you hero among the Kauravas! I cannot be seen in this form by any one but you, (even) by (the help of) the study of the Vedas or of sacrifices nor by gifts nor by actions nor by fierce penances.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.48', 'vedic-scriptures', 'BG11.48', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.48', 'telang-1882', 'Chapter 11; aligned against BG11.48', 'English translation witness');
