INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.49', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.49', 11, 49, 'Krishna', '431f6778f83f0243f10f812e22a28b7033d686aa9a4a9e49a867ca62097a52b9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.49', 'original', 'sa', 'Deva', 'मा ते व्यथा मा च विमूढभावो
दृष्ट्वा रूपं घोरमीदृङ्ममेदम्।
व्यपेतभीः प्रीतमनाः पुनस्त्वं
तदेव मे रूपमिदं प्रपश्य ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.49', 'transliteration', 'sa', 'Latn', 'mā te vyathā mā ca vimūḍhabhāvo dṛṣṭvā rūpaṃ ghoramīdṛṅmamedam
vyapetabhīḥ prītamanāḥ punastvaṃ tadeva me rūpamidaṃ prapaśya', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.49', 'translation', 'en', 'Latn', 'Be not alarmed, be not perplexed, at seeing this form of mine, fearful like this. Free from fear and with delighted heart, see now again that same form of mine.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.49', 'vedic-scriptures', 'BG11.49', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.49', 'telang-1882', 'Chapter 11; aligned against BG11.49', 'English translation witness');
