INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.50', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.50', 11, 50, 'Sanjaya', 'bd0466acbeb5eef66e023be97ac916d5463a4b894e154180639e2bcd1bf658da', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.50', 'original', 'sa', 'Deva', 'सञ्जय उवाच।
इत्यर्जुनं वासुदेवस्तथोक्त्वा
स्वकं रूपं दर्शयामास भूयः।
आश्वासयामास च भीतमेनं
भूत्वा पुनः सौम्यवपुर्महात्मा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.50', 'transliteration', 'sa', 'Latn', 'sañjaya uvāca
ityarjunaṃ vāsudevastathoktvā svakaṃ rūpaṃ darśayāmāsa bhūyaḥ
āśvāsayāmāsa ca bhītamenaṃ bhūtvā punaḥ saumyavapurmahātmā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.50', 'translation', 'en', 'Latn', 'Having thus spoken to Arjuna, Vāsudeva again showed his own form, and the high-souled one becoming again of a mild form, comforted him who had been affrighted.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.50', 'vedic-scriptures', 'BG11.50', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.50', 'telang-1882', 'Chapter 11; aligned against BG11.50', 'English translation witness');
