INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.51', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.51', 11, 51, 'Arjuna', '4dc32b0f153e6b4874a16183977b161564aa4de386170c6f533bfbcbd8c03536', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.51', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
दृष्ट्वेदं मानुषं रूपं तव सौम्यं जनार्दन।
इदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.51', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
dṛṣṭvedaṃ mānuṣaṃ rūpaṃ tava saumyaṃ janārdana
idānīmasmi saṃvṛttaḥ sacetāḥ prakṛtiṃ gataḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.51', 'translation', 'en', 'Latn', 'O Janardana ! seeing this mild, human form of yours, I am new in my right mind, and have come to my normal state. Even the gods are always desiring to see this form of mine, which it is difficult to get a sight of, and which you have seen. I cannot be seen', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.51', 'vedic-scriptures', 'BG11.51', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.11.51', 'telang-1882', 'Chapter 11; aligned against BG11.51', 'English translation witness');
