INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.52', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.52', 11, 52, 'Krishna', '7babbe081299ff85687bad7e83cd8cad719f134cac596fb686a2cf69e7d019ae', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.52', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम।
देवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.52', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
sudurdarśamidaṃ rūpaṃ dṛṣṭavānasi yanmama
devā apyasya rūpasya nityaṃ darśanakāṅkṣiṇaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.52', 'translation', 'en', 'Latn', 'as you have seen me by (means of) the Vedas not by penance', 'telang-1882');
