INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.11.53', 'नाहं वेदैर्न तपसा न दानेन न चेज्यया।
शक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा ॥', 'nāhaṃ vedairna tapasā na dānena na cejyayā
śakya evaṃvidho draṣṭuṃ dṛṣṭavānasi māṃ yathā', 'not by gift');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.11.54', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.11.54', 11, 54, 'Krishna', 'ceb8ff2039db6f8792c0783e52defea89312f75a3af6dccc42f76a41fdc9ae55', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.54', 'original', 'sa', 'Deva', 'भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन।
ज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.54', 'transliteration', 'sa', 'Latn', 'bhaktyā tvananyayā śakya ahamevaṃvidho.arjuna
jñātuṃ draṣṭuṃ ca tattvena praveṣṭuṃ ca parantapa', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.54', 'translation', 'en', 'Latn', 'nor yet by sacrifice. But O Arjuna! by devotion to me exclusively I can in this form be truly known seen', 'telang-1882');
