INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.55', 'original', 'sa', 'Deva', 'मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः।
निर्वैरः सर्वभूतेषु यः स मामेति पाण्डव ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.55', 'transliteration', 'sa', 'Latn', 'matkarmakṛnmatparamo madbhaktaḥ saṅgavarjitaḥ
