INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.11.55', 'translation', 'en', 'Latn', 'and assimilated with O terror of your foes! He who performs acts for (propitiating) me to whom I am the highest (object) who is my devotee who is free from attachment and who has no enmity towards any being he O son of Pāṇḍu! comes to me.', 'telang-1882');
