INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.12.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.12.1', 12, 1, 'Arjuna', '3af4b55fada9cd5ede0eed4c69f2eda4219e7b005c47d4cffbe1c10802e02acd', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.1', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते।
ये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.1', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
evaṃ satatayuktā ye bhaktāstvāṃ paryupāsate
ye cāpyakṣaramavyaktaṃ teṣāṃ ke yogavittamāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.1', 'translation', 'en', 'Latn', 'Of the worshippers, who thus, constantly devoted, meditate on you, and those who (meditate) on the unperceived and indestructible, which best know devotion? Those who being constantly devoted and possessed of the highest faith', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.12.1', 'vedic-scriptures', 'BG12.1', 'Devanagari and IAST digital witness');
