INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.5', 'original', 'sa', 'Deva', 'क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।
अव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.5', 'transliteration', 'sa', 'Latn', 'kleśo.adhikatarasteṣāmavyaktāsaktacetasām
