INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.12.8', 'मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।
निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः ॥', 'mayyeva mana ādhatsva mayi buddhiṃ niveśaya
nivasiṣyasi mayyeva ata ūrdhvaṃ na saṃśayaḥ', 'Place your mind on me only');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.12.9', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.12.9', 12, 9, 'Krishna', '061b761d7686297de7f9b57ee032fb6e0344923a501985ada7725a64d05302ca', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.9', 'original', 'sa', 'Deva', 'अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।
