INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.9', 'transliteration', 'sa', 'Latn', 'atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram
abhyāsayogena tato māmicchāptuṃ dhanañjaya', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.9', 'translation', 'en', 'Latn', 'fix your understanding on me. In me you will dwell hereafter, (there is) no doubt. But if you are unable to fix your mind steadily on me then', 'telang-1882');
