INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.10', 'original', 'sa', 'Deva', 'अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।
मदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.10', 'transliteration', 'sa', 'Latn', 'abhyāse.apyasamartho.asi matkarmaparamo bhava
madarthamapi karmāṇi kurvansiddhimavāpsyasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.10', 'translation', 'en', 'Latn', 'O Dhanañjaya ! endeavour to obtain me by the abstraction of mind (resulting) from continuous meditation. If you are unequal even to continuous meditation, then let acts for (propitiating) me be your highest (aim). Even performing actions for (propitiating) me, you will attain perfection.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.12.10', 'vedic-scriptures', 'BG12.10', 'Devanagari and IAST digital witness');
