INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.12', 'original', 'sa', 'Deva', 'श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।
ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.12', 'transliteration', 'sa', 'Latn', 'śreyo hi jñānamabhyāsājjñānāddhyānaṃ viśiṣyate
