INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.12', 'translation', 'en', 'Latn', 'then resort to devotion to me and with self-restraint abandon all fruit of action. For knowledge is better than continuous meditation concentration is esteemed higher than knowledge and the abandonment of fruit of action than concentration from (that) abandonment tranquillity soon (results). That devotee of mine', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.12.12', 'vedic-scriptures', 'BG12.12', 'Devanagari and IAST digital witness');
