INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.18', 'transliteration', 'sa', 'Latn', 'samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ
