INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.20', 'original', 'sa', 'Deva', 'ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते।
श्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.20', 'transliteration', 'sa', 'Latn', 'ye tu dharmyāmṛtamidaṃ yathoktaṃ paryupāsate
śraddadhānā matparamā bhaktāste.atīva me priyāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.12.20', 'translation', 'en', 'Latn', 'imbued with faith and (regarding) me as their highest (goal) resort to this holy (means for attaining) immortality as stated they are extremely dear to me.', 'telang-1882');
