INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.1', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
इदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते।
एतद्यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.1', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
idaṃ śarīraṃ kaunteya kṣetramityabhidhīyate
etadyo vetti taṃ prāhuḥ kṣetrajña iti tadvidaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.1', 'translation', 'en', 'Latn', 'O son of Kuntī ! is called Kṣetra', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.1', 'vedic-scriptures', 'BG13.2', 'Devanagari and IAST digital witness');
