INSERT OR REPLACE INTO variants (id, passage_id, type, note, devanagari, iast) VALUES ('gita.13.1.variant.1', 'gita.13.1', 'recensional-prelude', 'Some editions count an opening question by Arjuna as 13.1, producing 701 verses. This 700-verse edition records it as an unnumbered prelude.', 'अर्जुन उवाच |
प्रकृतिं पुरुषं चैव क्षेत्रं क्षेत्रज्ञमेव च |
एतद्वेदितुमिच्छामि ज्ञानं ज्ञेयं च केशव', 'arjuna uvāca .
prakṛtiṃ puruṣaṃ caiva kṣetraṃ kṣetrajñameva ca .
etadveditumicchāmi jñānaṃ jñeyaṃ ca keśava');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.13.1', 'श्रीभगवानुवाच।
