INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.2', 'translation', 'en', 'Latn', 'and the learned call him who knows it the Kṣetrajña.. And know me also O descendant of Bharata! to be the Kṣetrajña in all Kṣetras . The knowledge of Kṣetra and Kṣetrajña is deemed by me (to be real) knowledge. Now hear from me in brief what that Kṣetra (is)', 'telang-1882');
