INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.11', 'original', 'sa', 'Deva', 'अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम्।
