INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.11', 'translation', 'en', 'Latn', 'constancy in knowledge of the relation of the individual self to the supreme perception of the object of knowledge of the truth this is called knowledge that is ignorance which is opposed to this.', 'telang-1882');
