INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.12', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.12', 13, 12, 'Krishna', 'c06c6fe3a96df450f40cb9eae0402bad76a87ae4a7b3916d6c28390ac3eed010', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.12', 'original', 'sa', 'Deva', 'ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वामृतमश्नुते।
अनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.12', 'transliteration', 'sa', 'Latn', 'jñeyaṃ yattatpravakṣyāmi yajjñātvāmṛtamaśnute
anādi matparaṃ brahma na sattannāsaducyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.12', 'translation', 'en', 'Latn', 'I will declare that which is the object of knowledge, knowing which, one reaches immortality the highest Brahman, having no beginning nor end, which cannot be said to be existent or non-existent.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.12', 'vedic-scriptures', 'BG13.13', 'Devanagari and IAST digital witness');
