INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.13', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.13', 13, 13, 'Krishna', 'b35192042bf7cece8663c467a9082859657b8ac54a480d8235b0f34925b513e1', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.13', 'original', 'sa', 'Deva', 'सर्वतः पाणिपादं तत्सर्वतोऽक्षिशिरोमुखम्।
सर्वतः श्रुतिमल्लोके सर्वमावृत्य तिष्ठति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.13', 'transliteration', 'sa', 'Latn', 'sarvataḥ pāṇipādaṃ tatsarvato.akṣiśiromukham
sarvataḥ śrutimalloke sarvamāvṛtya tiṣṭhati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.13', 'translation', 'en', 'Latn', 'It has hands and feet on all sides it has eyes heads', 'telang-1882');
