INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.14', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.14', 13, 14, 'Krishna', '9830c8093c2cdcccb9bb55c536d86030c9f51e71406e31a23fa01b23fde847d1', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.14', 'original', 'sa', 'Deva', 'सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम्।
असक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.14', 'transliteration', 'sa', 'Latn', 'sarvendriyaguṇābhāsaṃ sarvendriyavivarjitam
asaktaṃ sarvabhṛccaiva nirguṇaṃ guṇabhoktṛ ca', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.14', 'translation', 'en', 'Latn', 'and faces on all sides it has ears on all sides it stands pervading everything in the world. Possessed of the qualities of all the senses, (but) devoid of all senses, unattached, it supports all, is devoid of qualities, and the enjoyer of qualities.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.14', 'vedic-scriptures', 'BG13.15', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.14', 'telang-1882', 'Chapter 13; aligned against BG13.15', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.13.14', 'सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम्।
असक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च ॥', 'sarvendriyaguṇābhāsaṃ sarvendriyavivarjitam
asaktaṃ sarvabhṛccaiva nirguṇaṃ guṇabhoktṛ ca', 'and faces on all sides it has ears on all sides it stands pervading everything in the world. Possessed of the qualities of all the senses, (but) devoid of all senses, unattached, it supports all, is devoid of qualities, and the enjoyer of qualities.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.15', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.15', 13, 15, 'Krishna', 'a4758d3bde53d441a1d2edc26ed4caa428b3804ab5cdd1287a5d9c397bfde1e7', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.15', 'original', 'sa', 'Deva', 'बहिरन्तश्च भूतानामचरं चरमेव च।
सूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.15', 'transliteration', 'sa', 'Latn', 'bahirantaśca bhūtānāmacaraṃ carameva ca
sūkṣmatvāttadavijñeyaṃ dūrasthaṃ cāntike ca tat', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.15', 'translation', 'en', 'Latn', 'It is within all things and without them it is movable and also immovable it is unknowable through (its) subtlety it stands afar and near.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.15', 'vedic-scriptures', 'BG13.16', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.15', 'telang-1882', 'Chapter 13; aligned against BG13.16', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.13.15', 'बहिरन्तश्च भूतानामचरं चरमेव च।
सूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत् ॥', 'bahirantaśca bhūtānāmacaraṃ carameva ca
sūkṣmatvāttadavijñeyaṃ dūrasthaṃ cāntike ca tat', 'It is within all things and without them it is movable and also immovable it is unknowable through (its) subtlety it stands afar and near.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.16', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.16', 13, 16, 'Krishna', 'f66e9d225945facd4132eb5a7370b30d1111f3872f75e9e595a85eebdc0bafee', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.16', 'original', 'sa', 'Deva', 'अविभक्तं च भूतेषु विभक्तमिव च स्थितम्।
भूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.16', 'transliteration', 'sa', 'Latn', 'avibhaktaṃ ca bhūteṣu vibhaktamiva ca sthitam
bhūtabhartṛ ca tajjñeyaṃ grasiṣṇu prabhaviṣṇu ca', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.16', 'translation', 'en', 'Latn', 'Not different in (different) things, but standing as though different, it should be known to be the supporter of (all) things, and that which absorbs and creates (them). It is the radiance even of the radiant (bodies)', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.16', 'vedic-scriptures', 'BG13.17', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.16', 'telang-1882', 'Chapter 13; aligned against BG13.17', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.13.16', 'अविभक्तं च भूतेषु विभक्तमिव च स्थितम्।
भूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च ॥', 'avibhaktaṃ ca bhūteṣu vibhaktamiva ca sthitam
bhūtabhartṛ ca tajjñeyaṃ grasiṣṇu prabhaviṣṇu ca', 'Not different in (different) things, but standing as though different, it should be known to be the supporter of (all) things, and that which absorbs and creates (them). It is the radiance even of the radiant (bodies)');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.17', 13, 17, 'Krishna', 'c834bc9a4c7932c3a3fda4e829674f8c48a2480254aa4c5949eb2bc04b657c0b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.17', 'original', 'sa', 'Deva', 'ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते।
ज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.17', 'transliteration', 'sa', 'Latn', 'jyotiṣāmapi tajjyotistamasaḥ paramucyate
jñānaṃ jñeyaṃ jñānagamyaṃ hṛdi sarvasya viṣṭhitam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.17', 'translation', 'en', 'Latn', 'it is said (to be) beyond darkness. It is knowledge, the object of knowledge, that which is to be attained to by knowledge, and placed in the heart of all.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.17', 'vedic-scriptures', 'BG13.18', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.17', 'telang-1882', 'Chapter 13; aligned against BG13.18', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.13.17', 'ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते।
ज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम् ॥', 'jyotiṣāmapi tajjyotistamasaḥ paramucyate
jñānaṃ jñeyaṃ jñānagamyaṃ hṛdi sarvasya viṣṭhitam', 'it is said (to be) beyond darkness. It is knowledge, the object of knowledge, that which is to be attained to by knowledge, and placed in the heart of all.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.18', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.18', 13, 18, 'Krishna', 'c640758fdacacd0f699dac93883167f587beac4c5bc88c10f5e8b29a63885d56', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.18', 'original', 'sa', 'Deva', 'इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः।
मद्भक्त एतद्विज्ञाय मद्भावायोपपद्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.18', 'transliteration', 'sa', 'Latn', 'iti kṣetraṃ tathā jñānaṃ jñeyaṃ coktaṃ samāsataḥ
madbhakta etadvijñāya madbhāvāyopapadyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.18', 'translation', 'en', 'Latn', 'Thus in brief have Kṣetra, knowledge, and the object of knowledge been declared. My devotee, knowing this, becomes fit for assimilation with me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.18', 'vedic-scriptures', 'BG13.19', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.18', 'telang-1882', 'Chapter 13; aligned against BG13.19', 'English translation witness');
