INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.27', 'translation', 'en', 'Latn', 'He sees (truly) who sees the supreme lord abiding alike in all entities', 'telang-1882');
