INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.13.28', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.13.28', 13, 28, 'Krishna', '7b8b64b9a7255485d1339e76cba5df2e04fb7b2900d593a90804905b1468ad61', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.28', 'original', 'sa', 'Deva', 'समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम्।
