INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.28', 'translation', 'en', 'Latn', 'and not destroyed though they are destroyed. For he who sees the lord abiding everywhere alike does not destroy himselfby himself and then reaches the highest goal.', 'telang-1882');
