INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.29', 'original', 'sa', 'Deva', 'प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः।
यः पश्यति तथात्मानमकर्तारं स पश्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.29', 'transliteration', 'sa', 'Latn', 'prakṛtyaiva ca karmāṇi kriyamāṇāni sarvaśaḥ
yaḥ paśyati tathātmānamakartāraṃ sa paśyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.29', 'translation', 'en', 'Latn', 'He sees (truly) who sees (all) actions (to be) in every way done by nature alone and likewise the self (to be) not the doer. When a man sees all the variety of entities as existing in one and (all as) emanating from that', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.29', 'vedic-scriptures', 'BG13.30', 'Devanagari and IAST digital witness');
