INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.33', 'original', 'sa', 'Deva', 'यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः।
क्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति भारत ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.33', 'transliteration', 'sa', 'Latn', 'yathā prakāśayatyekaḥ kṛtsnaṃ lokamimaṃ raviḥ
kṣetraṃ kṣetrī tathā kṛtsnaṃ prakāśayati bhārata', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.13.33', 'translation', 'en', 'Latn', 'O son of Kuntī! though stationed in the body. As by (reason of its) subtlety the all-pervading space is not tainted so the self stationed in every body is not tainted. As the sun singly lights up all this world', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.33', 'vedic-scriptures', 'BG13.34', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.13.33', 'telang-1882', 'Chapter 13; aligned against BG13.34', 'English translation witness');
