INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.14.3', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.14.3', 14, 3, 'Krishna', '21c89a8f754587a61e47919bacefb6f888ea2505fde739029a40c1e090f6ea03', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.3', 'original', 'sa', 'Deva', 'मम योनिर्महद् ब्रह्म तस्मिन्गर्भं दधाम्यहम्।
सम्भवः सर्वभूतानां ततो भवति भारत ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.3', 'transliteration', 'sa', 'Latn', 'mama yonirmahad brahma tasmingarbhaṃ dadhāmyaham
sambhavaḥ sarvabhūtānāṃ tato bhavati bhārata', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.3', 'translation', 'en', 'Latn', 'The great Brahman is a womb for me in which I cast the seed. From that O descendant of Bharata! is the birth of all things. Of the bodies O son of Kuntī ! which are born from all wombs the (main) womb is the great Brahman', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.3', 'vedic-scriptures', 'BG14.3', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.3', 'telang-1882', 'Chapter 14; aligned against BG14.3', 'English translation witness');
