INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.4', 'original', 'sa', 'Deva', 'सर्वयोनिषु कौन्तेय मूर्तयः सम्भवन्ति याः।
तासां ब्रह्म महद्योनिरहं बीजप्रदः पिता ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.4', 'transliteration', 'sa', 'Latn', 'sarvayoniṣu kaunteya mūrtayaḥ sambhavanti yāḥ
