INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.5', 'original', 'sa', 'Deva', 'सत्त्वं रजस्तम इति गुणाः प्रकृतिसम्भवाः।
निबध्नन्ति महाबाहो देहे देहिनमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.5', 'transliteration', 'sa', 'Latn', 'sattvaṃ rajastama iti guṇāḥ prakṛtisambhavāḥ
