INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.5', 'translation', 'en', 'Latn', 'the giver of the seed. Goodness passion darkness these qualities born from nature O you of mighty arms! bind down the inexhaustible soul in the body. Of these', 'telang-1882');
