INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.14.6', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.14.6', 14, 6, 'Krishna', 'edf9ea387c3597650282a58391b71407a836d657f441ff7f387f491101c55940', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.6', 'original', 'sa', 'Deva', 'तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम्।
सुखसङ्गेन बध्नाति ज्ञानसङ्गेन चानघ ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.6', 'transliteration', 'sa', 'Latn', 'tatra sattvaṃ nirmalatvātprakāśakamanāmayam
