INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.6', 'translation', 'en', 'Latn', 'goodness which in consequence of being untainted is enlightening and free from (all) misery binds the soul O sinless one! with the bond of pleasure and the bond of knowledge.', 'telang-1882');
