INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.14', 'original', 'sa', 'Deva', 'यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत्।
तदोत्तमविदां लोकानमलान्प्रतिपद्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.14', 'transliteration', 'sa', 'Latn', 'yadā sattve pravṛddhe tu pralayaṃ yāti dehabhṛt
tadottamavidāṃ lokānamalānpratipadyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.14', 'translation', 'en', 'Latn', 'these are produced O descendant of Kuru ! when darkness is developed. When an embodied (self) encounters death while goodness is developed then he reaches the untainted worlds of those who know the highest.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.14', 'vedic-scriptures', 'BG14.14', 'Devanagari and IAST digital witness');
