INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.15', 'original', 'sa', 'Deva', 'रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते।
तथा प्रलीनस्तमसि मूढयोनिषु जायते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.15', 'transliteration', 'sa', 'Latn', 'rajasi pralayaṃ gatvā karmasaṅgiṣu jāyate
tathā pralīnastamasi mūḍhayoniṣu jāyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.15', 'translation', 'en', 'Latn', 'Encountering death during (the prevalence of) passion, he is born among those attached to action. Likewise, dying during (the prevalence of) darkness, he is born in the wombs of the ignorant.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.15', 'vedic-scriptures', 'BG14.15', 'Devanagari and IAST digital witness');
