INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.17', 'original', 'sa', 'Deva', 'सत्त्वात्सञ्जायते ज्ञानं रजसो लोभ एव च।
प्रमादमोहौ तमसो भवतोऽज्ञानमेव च ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.17', 'transliteration', 'sa', 'Latn', 'sattvātsañjāyate jñānaṃ rajaso lobha eva ca
pramādamohau tamaso bhavato.ajñānameva ca', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.17', 'translation', 'en', 'Latn', 'while the fruit of passion is misery and the fruit of darkness ignorance. From goodness is produced knowledge, from passion avarice, and from darkness heedlessness and delusion and ignorance also.', 'telang-1882');
