INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.18', 'original', 'sa', 'Deva', 'ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः।
जघन्यगुणवृत्तिस्था अधो गच्छन्ति तामसाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.18', 'transliteration', 'sa', 'Latn', 'ūrdhvaṃ gacchanti sattvasthā madhye tiṣṭhanti rājasāḥ
