INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.18', 'translation', 'en', 'Latn', 'Those who adhere to (the ways of) goodness go up the passionate remain in the middle while those of the qualities of darkness adhering to the ways of the lowest quality', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.18', 'vedic-scriptures', 'BG14.18', 'Devanagari and IAST digital witness');
