INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.19', 'original', 'sa', 'Deva', 'नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति।
गुणेभ्यश्च परं वेत्ति मद्भावं सोऽधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.19', 'transliteration', 'sa', 'Latn', 'nānyaṃ guṇebhyaḥ kartāraṃ yadā draṣṭānupaśyati
guṇebhyaśca paraṃ vetti madbhāvaṃ so.adhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.19', 'translation', 'en', 'Latn', 'go down. When a right-seeing person sees none but the qualities (to be) the doers (of all action) and knows what is above the qualities', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.19', 'vedic-scriptures', 'BG14.19', 'Devanagari and IAST digital witness');
