INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.20', 'original', 'sa', 'Deva', 'गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान्।
जन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.20', 'transliteration', 'sa', 'Latn', 'guṇānetānatītya trīndehī dehasamudbhavān
janmamṛtyujarāduḥkhairvimukto.amṛtamaśnute', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.20', 'translation', 'en', 'Latn', 'he enters into my essence. The embodied (self), who transcends these three qualities, from which bodies are produced, attains immortality, being freed from birth and death and old age and misery.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.20', 'vedic-scriptures', 'BG14.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.14.20', 'telang-1882', 'Chapter 14; aligned against BG14.20', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.14.20', 'गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान्।
जन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते ॥', 'guṇānetānatītya trīndehī dehasamudbhavān
janmamṛtyujarāduḥkhairvimukto.amṛtamaśnute', 'he enters into my essence. The embodied (self), who transcends these three qualities, from which bodies are produced, attains immortality, being freed from birth and death and old age and misery.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.14.21', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.14.21', 14, 21, 'Arjuna', '50d03f3a002bc19577bb3ee5c52096e592756bcb11c32a77a4d57ff4c79bd4d9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.21', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
कैर्लिङ्गैस्त्रीन्गुणानेतानतीतो भवति प्रभो।
किमाचारः कथं चैतांस्त्रीन्गुणानतिवर्तते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.21', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
kairliṅgaistrīnguṇānetānatīto bhavati prabho
kimācāraḥ kathaṃ caitāṃstrīnguṇānativartate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.21', 'translation', 'en', 'Latn', 'What are the characteristics, O lord! of one who has transcended these three qualities? What is his conduct, and how does he transcend these three qualities? He is said to have transcended the qualities', 'telang-1882');
