INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.14.22', 'translation', 'en', 'Latn', 'O son of Pāndu! who is not averse to light and activity and delusion (when they) prevail and who does not desire (them when they) cease', 'telang-1882');
