INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.3', 'original', 'sa', 'Deva', 'न रूपमस्येह तथोपलभ्यते
नान्तो न चादिर्न च सम्प्रतिष्ठा।
अश्वत्थमेनं सुविरूढमूलं
असङ्गशस्त्रेण दृढेन छित्त्वा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.3', 'transliteration', 'sa', 'Latn', 'na rūpamasyeha tathopalabhyate nānto na cādirna ca sampratiṣṭhā
aśvatthamenaṃ suvirūḍhamūlaṃ asaṅgaśastreṇa dṛḍhena chittvā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.3', 'translation', 'en', 'Latn', 'Its form is not thus known here nor (its) end nor beginning nor support. But having with the firm weapon of unconcern cut this Aśvattha whose roots are firmly fixed', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.3', 'vedic-scriptures', 'BG15.3', 'Devanagari and IAST digital witness');
