INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.15.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.15.4', 15, 4, 'Krishna', '8adafd5302c4691b66cc1c8c1e05e9738a74e1c3eb40e39cc0f13e3f85f16222', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.4', 'original', 'sa', 'Deva', 'ततः पदं तत्परिमार्गितव्यं
यस्मिन्गता न निवर्तन्ति भूयः।
तमेव चाद्यं पुरुषं प्रपद्ये।
यतः प्रवृत्तिः प्रसृता पुराणी ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.4', 'transliteration', 'sa', 'Latn', 'tataḥ padaṃ tatparimārgitavyaṃ yasmingatā na nivartanti bhūyaḥ
tameva cādyaṃ puruṣaṃ prapadye
yataḥ pravṛttiḥ prasṛtā purāṇī', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.4', 'translation', 'en', 'Latn', 'then should one seek for that seat from which those that go there never return, (thinking) that one rests on that same primal being from whom the ancient course (of worldly life) emanated.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.4', 'vedic-scriptures', 'BG15.4', 'Devanagari and IAST digital witness');
