INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.15.5', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.15.5', 15, 5, 'Krishna', 'bd531050bacebf7e5904db1f60686603d1d47b0baaa7d7b63df3a6b4c4eb87b2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.5', 'original', 'sa', 'Deva', 'निर्मानमोहा जितसङ्गदोषा
अध्यात्मनित्या विनिवृत्तकामाः।
द्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञैर्-
गच्छन्त्यमूढाः पदमव्ययं तत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.5', 'transliteration', 'sa', 'Latn', 'nirmānamohā jitasaṅgadoṣā adhyātmanityā vinivṛttakāmāḥ
dvandvairvimuktāḥ sukhaduḥkhasaṃjñaira- gacchantyamūḍhāḥ padamavyayaṃ tat', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.5', 'translation', 'en', 'Latn', 'Those who are free from pride and delusion who have overcome the evils of attachment who are constant in (contemplating) the relation of the supreme and individual self from whom desire has departed who are free from the pairs (of opposites) called pleasure and pain go undeluded to that imperishable seat.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.5', 'vedic-scriptures', 'BG15.5', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.5', 'telang-1882', 'Chapter 15; aligned against BG15.5', 'English translation witness');
