INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.6', 'original', 'sa', 'Deva', 'न तद्भासयते सूर्यो न शशाङ्को न पावकः।
यद्गत्वा न निवर्तन्ते तद्धाम परमं मम ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.6', 'transliteration', 'sa', 'Latn', 'na tadbhāsayate sūryo na śaśāṅko na pāvakaḥ
yadgatvā na nivartante taddhāma paramaṃ mama', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.6', 'translation', 'en', 'Latn', 'The sun does not light it, nor the moon, nor fire. That is my highest abode, going to which none returns.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.6', 'vedic-scriptures', 'BG15.6', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.6', 'telang-1882', 'Chapter 15; aligned against BG15.6', 'English translation witness');
