INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.15.8', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.15.8', 15, 8, 'Krishna', '4247a4f2c30b3ab69e146df4b2bd8fac6393b7f071f190c4322b417dddd30bb5', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.8', 'original', 'sa', 'Deva', 'शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः।
गृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.8', 'transliteration', 'sa', 'Latn', 'śarīraṃ yadavāpnoti yaccāpyutkrāmatīśvaraḥ
gṛhitvaitāni saṃyāti vāyurgandhānivāśayāt', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.8', 'translation', 'en', 'Latn', 'Whenever the ruler (of the bodily frame) obtains or quits a body he goes taking these (with him) as the wind (takes) perfumes from (their) seats. And presiding over the senses of hearing and seeing and touch', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.8', 'vedic-scriptures', 'BG15.8', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.8', 'telang-1882', 'Chapter 15; aligned against BG15.8', 'English translation witness');
