INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.15.10', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.15.10', 15, 10, 'Krishna', 'fcc6d728b0f63b7d9a6e6483e33b5f255a06b9552ac2b4e4ae203c929660ee20', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.10', 'original', 'sa', 'Deva', 'उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।
विमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.10', 'transliteration', 'sa', 'Latn', 'utkrāmantaṃ sthitaṃ vāpi bhuñjānaṃ vā guṇānvitam
vimūḍhā nānupaśyanti paśyanti jñānacakṣuṣaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.10', 'translation', 'en', 'Latn', 'Those who are deluded do not see (him) remaining in or quitting (a body), enjoying or joined to the qualities they see, who have eyes of knowledge.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.10', 'vedic-scriptures', 'BG15.10', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.10', 'telang-1882', 'Chapter 15; aligned against BG15.10', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.15.10', 'उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।
विमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः ॥', 'utkrāmantaṃ sthitaṃ vāpi bhuñjānaṃ vā guṇānvitam
