INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.15.11', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.15.11', 15, 11, 'Krishna', '179dc1e72a428c464733b5cb241aff14f093745bf16fbbc22056cdb5a35a8037', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.11', 'original', 'sa', 'Deva', 'यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।
यतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.11', 'transliteration', 'sa', 'Latn', 'yatanto yoginaścainaṃ paśyantyātmanyavasthitam
yatanto.apyakṛtātmāno nainaṃ paśyantyacetasaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.11', 'translation', 'en', 'Latn', 'Devotees making efforts perceive him abiding within their selfs. But those whose selfs have not been refined and who have no discernment do not perceive him even (after) making efforts.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.11', 'vedic-scriptures', 'BG15.11', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.15.11', 'telang-1882', 'Chapter 15; aligned against BG15.11', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.15.11', 'यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।
यतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः ॥', 'yatanto yoginaścainaṃ paśyantyātmanyavasthitam
