INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.15.12', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.15.12', 15, 12, 'Krishna', 'a99b9e85cf1d0e7897c6d3faf01cabd28a33123ea8b90c366a1a797ffb68fc3f', 'first review verified; second review pending', 0);
