INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.15', 'translation', 'en', 'Latn', 'and dwelling in the bodies of (all) creatures and united with the upward and downward life-breaths cause digestion of the fourfold food. And I am placed in the heart of all from me (come) memory, knowledge, and their removal I alone am to be learnt from all the Vedas I am the author of the Vedāntas', 'telang-1882');
