INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.16', 'original', 'sa', 'Deva', 'द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।
क्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.16', 'transliteration', 'sa', 'Latn', 'dvāvimau puruṣau loke kṣaraścākṣara eva ca
kṣaraḥ sarvāṇi bhūtāni kūṭastho.akṣara ucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.15.16', 'translation', 'en', 'Latn', 'and I alone know the Vedas. There are these two beings in the world, the destructible and the indestructible. The destructible (includes) all things. The unconcerned one is (what is) called the indestructible. But the being supreme is yet another', 'telang-1882');
