INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.1', 'translation', 'en', 'Latn', 'Freedom from fear purity of heart perseverance in (pursuit of) knowledge and abstraction of mind gifts self-restraint and sacrifice', 'telang-1882');
