INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.5', 'original', 'sa', 'Deva', 'दैवी सम्पद्विमोक्षाय निबन्धायासुरी मता।
मा शुचः सम्पदं दैवीमभिजातोऽसि पाण्डव ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.5', 'transliteration', 'sa', 'Latn', 'daivī sampadvimokṣāya nibandhāyāsurī matā
mā śucaḥ sampadaṃ daivīmabhijāto.asi pāṇḍava', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.5', 'translation', 'en', 'Latn', 'freedom from a desire to injure others absence of vanity, (these) O descendant of Bharata! are his who is born to godlike endowments. Ostentatiousness, pride, vanity, anger, and also harshness and ignorance (are) his, O son of Pṛthā! who is born to demoniac endowments. Godlike endowments are deemed to be (means) for final emancipation, demoniac for bondage. Grieve not, O descendant of Bharata! you are born to godlike endowments.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.5', 'vedic-scriptures', 'BG16.5', 'Devanagari and IAST digital witness');
