INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.6', 'original', 'sa', 'Deva', 'द्वौ भूतसर्गौ लोकेऽस्मिन्दैव आसुर एव च।
दैवो विस्तरशः प्रोक्त आसुरं पार्थ मे शृणु ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.6', 'transliteration', 'sa', 'Latn', 'dvau bhūtasargau loke.asmindaiva āsura eva ca
daivo vistaraśaḥ prokta āsuraṃ pārtha me śṛṇu', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.6', 'translation', 'en', 'Latn', '(There are) two classes of created beings in this world, the godlike and the demoniac the godlike (class) has been described at length now hear from me, O son of Pṛthā! about the demoniac.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.6', 'vedic-scriptures', 'BG16.6', 'Devanagari and IAST digital witness');
