INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.7', 'original', 'sa', 'Deva', 'प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः।
न शौचं नापि चाचारो न सत्यं तेषु विद्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.7', 'transliteration', 'sa', 'Latn', 'pravṛttiṃ ca nivṛttiṃ ca janā na vidurāsurāḥ
na śaucaṃ nāpi cācāro na satyaṃ teṣu vidyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.7', 'translation', 'en', 'Latn', 'Demoniac persons know not action or inaction, neither purity nor yet (correct) conduct nor veracity are in them.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.7', 'vedic-scriptures', 'BG16.7', 'Devanagari and IAST digital witness');
