INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.8', 'transliteration', 'sa', 'Latn', 'asatyamapratiṣṭhaṃ te jagadāhuranīśvaram
