INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.8', 'translation', 'en', 'Latn', 'They say the universe is devoid of truth devoid of fixed principle and devoid of a ruler produced by union (of male and female) caused by lust and nothing else.', 'telang-1882');
