INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.9', 'original', 'sa', 'Deva', 'एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः।
