INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.9', 'translation', 'en', 'Latn', 'Holding this view, (these) enemies of the world, of ruined selfs, of little knowledge, and of ferocious actions, are born for the destruction (of the world).', 'telang-1882');
