INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.10', 'translation', 'en', 'Latn', 'Entertaining insatiable desire, full of vanity, ostentatiousness, and frenzy, they adopt false notions through delusion, and engage in unholy observances.', 'telang-1882');
