INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.21', 'original', 'sa', 'Deva', 'त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः।
कामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.21', 'transliteration', 'sa', 'Latn', 'trividhaṃ narakasyedaṃ dvāraṃ nāśanamātmanaḥ
kāmaḥ krodhastathā lobhastasmādetattrayaṃ tyajet', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.21', 'translation', 'en', 'Latn', 'Threefold is this way, to hell,-ruinous to the self,—lust, anger, and likewise avarice therefore one should abandon this triad.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.21', 'vedic-scriptures', 'BG16.21', 'Devanagari and IAST digital witness');
