INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.22', 'original', 'sa', 'Deva', 'एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः।
आचरत्यात्मनः श्रेयस्ततो याति परां गतिम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.22', 'transliteration', 'sa', 'Latn', 'etairvimuktaḥ kaunteya tamodvāraistribhirnaraḥ
ācaratyātmanaḥ śreyastato yāti parāṃ gatim', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.22', 'translation', 'en', 'Latn', 'Released from these three ways to darkness, O son of Kuntī! a man works out his own welfare, and then proceeds to the highest goal.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.22', 'vedic-scriptures', 'BG16.22', 'Devanagari and IAST digital witness');
