INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.16.23', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.16.23', 16, 23, 'Krishna', '54242c5eace854c6fcf39c6572579254eea225902bfdcb8dd3df0440a746d1b1', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.23', 'original', 'sa', 'Deva', 'यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः।
न स सिद्धिमवाप्नोति न सुखं न परां गतिम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.23', 'transliteration', 'sa', 'Latn', 'yaḥ śāstravidhimutsṛjya vartate kāmakārataḥ
na sa siddhimavāpnoti na sukhaṃ na parāṃ gatim', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.16.23', 'translation', 'en', 'Latn', 'He who abandoning scripture ordinances, acts under the impulse of desire, does not attain perfection, nor happiness, nor the highest goal.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.23', 'vedic-scriptures', 'BG16.23', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.16.23', 'telang-1882', 'Chapter 16; aligned against BG16.23', 'English translation witness');
