INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.4', 17, 4, 'Krishna', '5947b96aaeb85efa88ab2f6c3d531c6503e5861f2b252f41b5bf70f00333245c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.4', 'original', 'sa', 'Deva', 'यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः।
प्रेतान्भूतगणांश्चान्ये यजन्ते तामसा जनाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.4', 'transliteration', 'sa', 'Latn', 'yajante sāttvikā devānyakṣarakṣāṃsi rājasāḥ
pretānbhūtagaṇāṃścānye yajante tāmasā janāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.4', 'translation', 'en', 'Latn', 'Those of the quality of goodness worship the gods those of the quality of passion the Yakṣas and Rakṣases and the others, the people of the quality of darkness, worship departed (spirits) and the multitudes of Bhūtas .', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.4', 'vedic-scriptures', 'BG17.4', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.4', 'telang-1882', 'Chapter 17; aligned against BG17.4', 'English translation witness');
