INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.5', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.5', 17, 5, 'Krishna', 'c320cb3a4310461932a01d8bd5164046edf700cb92f4dd7fce45e8718b27e112', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.5', 'original', 'sa', 'Deva', 'अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः।
दम्भाहंकारसंयुक्ताः कामरागबलान्विताः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.5', 'transliteration', 'sa', 'Latn', 'aśāstravihitaṃ ghoraṃ tapyante ye tapo janāḥ
dambhāhaṃkārasaṃyuktāḥ kāmarāgabalānvitāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.5', 'translation', 'en', 'Latn', 'Know those to be of demoniac convictions, who practise fierce penance not ordained by scripture who are full of ostentatiousness and egoism, and of desire, attachment, and stubbornness', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.5', 'vedic-scriptures', 'BG17.5', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.5', 'telang-1882', 'Chapter 17; aligned against BG17.5', 'English translation witness');
