INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.7', 'original', 'sa', 'Deva', 'आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः।
