INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.7', 'translation', 'en', 'Latn', 'The food also, which is liked by all, and likewise the sacrifice, the penance, and gifts, are of three kinds. Listen to the distinctions regarding them as follows.', 'telang-1882');
