INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.8', 'original', 'sa', 'Deva', 'आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः।
