INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.8', 'translation', 'en', 'Latn', 'The kinds of food which increase life, energy, strength, health, comfort, and relish, which are savoury, oleaginous, full of nutrition, and agreeable, are liked by the good. The kinds of food which are bitter acid saltish too hot sharp', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.8', 'vedic-scriptures', 'BG17.8', 'Devanagari and IAST digital witness');
