INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.11', 'original', 'sa', 'Deva', 'अफलाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते।
यष्टव्यमेवेति मनः समाधाय स सात्त्विकः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.11', 'transliteration', 'sa', 'Latn', 'aphalāṅkṣibhiryajño vidhidṛṣṭo ya ijyate
yaṣṭavyameveti manaḥ samādhāya sa sāttvikaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.11', 'translation', 'en', 'Latn', 'stinking stale impure and even leavings are liked by the dark. That sacrifice is good which being prescribed in (scripture) ordinances is performed by persons not wishing for the fruit (of it) and after determining (in their) mind that the sacrifice must needs be performed. But when a sacrifice is performed O highest of the descendants of Bharata! with an expectation of fruit (from it)', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.11', 'vedic-scriptures', 'BG17.11', 'Devanagari and IAST digital witness');
