INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.12', 'original', 'sa', 'Deva', 'अभिसन्धाय तु फलं दम्भार्थमपि चैव यत्।
इज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.12', 'transliteration', 'sa', 'Latn', 'abhisandhāya tu phalaṃ dambhārthamapi caiva yat
