INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.12', 'translation', 'en', 'Latn', 'and for the purpose of ostentation know that sacrifice (to be) passionate.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.12', 'vedic-scriptures', 'BG17.12', 'Devanagari and IAST digital witness');
