INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.13', 'original', 'sa', 'Deva', 'विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम्।
श्रद्धाविरहितं यज्ञं तामसं परिचक्षते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.13', 'transliteration', 'sa', 'Latn', 'vidhihīnamasṛṣṭānnaṃ mantrahīnamadakṣiṇam
śraddhāvirahitaṃ yajñaṃ tāmasaṃ paricakṣate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.13', 'translation', 'en', 'Latn', 'They call that sacrifice dark which is against the ordinances (of scripture) in which no food is dealt out (to Brāhmaṇas, &c.) which is devoid of Mantras devoid of Dakṣiṇā presents and which is without faith.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.13', 'vedic-scriptures', 'BG17.13', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.13', 'telang-1882', 'Chapter 17; aligned against BG17.13', 'English translation witness');
