INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.14', 'original', 'sa', 'Deva', 'देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम्।
ब्रह्मचर्यमहिंसा च शारीरं तप उच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.14', 'transliteration', 'sa', 'Latn', 'devadvijaguruprājñapūjanaṃ śaucamārjavam
brahmacaryamahiṃsā ca śārīraṃ tapa ucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.14', 'translation', 'en', 'Latn', 'Paying reverence to gods, Brāhmaṇas, preceptors, and men of knowledge purity, straightforwardness, life as Brahmacārin , and harmlessness, (this) is called the penance bodily.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.14', 'vedic-scriptures', 'BG17.14', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.14', 'telang-1882', 'Chapter 17; aligned against BG17.14', 'English translation witness');
