INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.15', 'original', 'sa', 'Deva', 'अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत्।
स्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.15', 'transliteration', 'sa', 'Latn', 'anudvegakaraṃ vākyaṃ satyaṃ priyahitaṃ ca yat
svādhyāyābhyasanaṃ caiva vāṅmayaṃ tapa ucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.15', 'translation', 'en', 'Latn', 'The speech which causes no sorrow, which is true, agreeable, and beneficial, and the study of the Vedas , (this) is called the penance vocal.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.15', 'vedic-scriptures', 'BG17.15', 'Devanagari and IAST digital witness');
