INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.17.15', 'अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत्।
स्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते ॥', 'anudvegakaraṃ vākyaṃ satyaṃ priyahitaṃ ca yat
svādhyāyābhyasanaṃ caiva vāṅmayaṃ tapa ucyate', 'The speech which causes no sorrow, which is true, agreeable, and beneficial, and the study of the Vedas , (this) is called the penance vocal.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.16', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.16', 17, 16, 'Krishna', '2af96a7bfecefdba5e658867aa634a446653f040f8454d13958fe1dd14075fe6', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.16', 'original', 'sa', 'Deva', 'मनः प्रसादः सौम्यत्वं मौनमात्मविनिग्रहः।
भावसंशुद्धिरित्येतत्तपो मानसमुच्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.16', 'transliteration', 'sa', 'Latn', 'manaḥ prasādaḥ saumyatvaṃ maunamātmavinigrahaḥ
bhāvasaṃśuddhirityetattapo mānasamucyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.16', 'translation', 'en', 'Latn', 'Calmness of mind, mildness, taciturnity, self-restraint, and purity of heart, this is called the penance mental.', 'telang-1882');
