INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.17', 'original', 'sa', 'Deva', 'श्रद्धया परया तप्तं तपस्तत्त्रिविधं नरैः।
