INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.17', 'translation', 'en', 'Latn', 'This threefold penance, practised with perfect faith, by men who do not wish for the fruit, and who are possessed of devotion is called good. The penance which is done for respect', 'telang-1882');
