INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.19', 'original', 'sa', 'Deva', 'मूढग्राहेणात्मनो यत्पीडया क्रियते तपः।
परस्योत्सादनार्थं वा तत्तामसमुदाहृतम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.19', 'transliteration', 'sa', 'Latn', 'mūḍhagrāheṇātmano yatpīḍayā kriyate tapaḥ
