INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.19', 'translation', 'en', 'Latn', 'and reverence and with ostentatiousness and which is uncertain and transient is here called passionate. And that penance is described as dark which is performed under a misguided conviction with pain to oneself', 'telang-1882');
