INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.20', 'original', 'sa', 'Deva', 'दातव्यमिति यद्दानं दीयतेऽनुपकारिणे।
देशे काले च पात्रे च तद्दानं सात्त्विकं स्मृतम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.20', 'transliteration', 'sa', 'Latn', 'dātavyamiti yaddānaṃ dīyate.anupakāriṇe
deśe kāle ca pātre ca taddānaṃ sāttvikaṃ smṛtam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.20', 'translation', 'en', 'Latn', 'or for the destruction of another. That gift is said (to be) good which is given because it ought to be given to one who (can) do no service (in return) at a (proper) place and time an d to a (proper) person. But that gift which is given with much difficulty', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.20', 'vedic-scriptures', 'BG17.20', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.20', 'telang-1882', 'Chapter 17; aligned against BG17.20', 'English translation witness');
