INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.21', 'transliteration', 'sa', 'Latn', 'yattu pratyupakārārthaṃ phalamuddiśya vā punaḥ
