INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.21', 'translation', 'en', 'Latn', 'for a return of services or even with an expectation of fruit is said to be passionate. And that gift is described as dark', 'telang-1882');
