INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.23', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.23', 17, 23, 'Krishna', '679ca6f06de64f0ab3fca9936fd6537eb02324c07710ea04bc61976a5430579a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.23', 'original', 'sa', 'Deva', 'ॐतत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः।
ब्राह्मणास्तेन वेदाश्च यज्ञाश्च विहिताः पुरा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.23', 'transliteration', 'sa', 'Latn', 'OMtatsaditi nirdeśo brahmaṇastrividhaḥ smṛtaḥ
brāhmaṇāstena vedāśca yajñāśca vihitāḥ purā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.23', 'translation', 'en', 'Latn', 'and with contempt. Om, Tad, and Sat, this is said (to be) the threefold designation of the Brahman . By that, the Brāhmaṇas and the Vedas and sacrifices were created in olden times.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.23', 'vedic-scriptures', 'BG17.23', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.23', 'telang-1882', 'Chapter 17; aligned against BG17.23', 'English translation witness');
