INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.24', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.24', 17, 24, 'Krishna', 'b6f7c14f41f47d8dc6a84cf5adc389404027580d47b9e55007ed9af35108d342', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.24', 'original', 'sa', 'Deva', 'तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः।
प्रवर्तन्ते विधानोक्ताः सततं ब्रह्मवादिनाम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.24', 'transliteration', 'sa', 'Latn', 'tasmādomityudāhṛtya yajñadānatapaḥkriyāḥ
