INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.24', 'translation', 'en', 'Latn', 'Hence, the performance by those who study the Brahman, of sacrifices, gifts, and penances, prescribed by the ordinances (of scripture), always commence after saying ''Om.''', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.24', 'vedic-scriptures', 'BG17.24', 'Devanagari and IAST digital witness');
