INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.25', 'original', 'sa', 'Deva', 'तदित्यनभिसन्धाय फलं यज्ञतपःक्रियाः।
दानक्रियाश्च विविधाः क्रियन्ते मोक्षकाङ्क्षिभिः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.25', 'transliteration', 'sa', 'Latn', 'tadityanabhisandhāya phalaṃ yajñatapaḥkriyāḥ
dānakriyāśca vividhāḥ kriyante mokṣakāṅkṣibhiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.25', 'translation', 'en', 'Latn', 'Those who desire final emancipation perform the various acts of sacrifice and penance, and the various acts of gift, without expectation of fruit, after (saying) ''Tad.''', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.25', 'vedic-scriptures', 'BG17.25', 'Devanagari and IAST digital witness');
