INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.26', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.26', 17, 26, 'Krishna', '3f2d8246adc38fb1391c6705cd02f9ef552a12ce39b5cdaa8ce0cacc675647a1', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.26', 'original', 'sa', 'Deva', 'सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते।
प्रशस्ते कर्मणि तथा सच्छब्दः पार्थ युज्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.26', 'transliteration', 'sa', 'Latn', 'sadbhāve sādhubhāve ca sadityetatprayujyate
praśaste karmaṇi tathā sacchabdaḥ pārtha yujyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.26', 'translation', 'en', 'Latn', '''Sat'' is employed to express existence and goodness and likewise, O son of Pṛthā! the word ''Sat'' is used to express an auspicious act.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.26', 'vedic-scriptures', 'BG17.26', 'Devanagari and IAST digital witness');
