INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.27', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.27', 17, 27, 'Krishna', '02e08a306ad3b38a60b3c7a2bf4c87f1cc12b3a003016604082aef5755d4feea', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.27', 'original', 'sa', 'Deva', 'यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते।
कर्म चैव तदर्थीयं सदित्येवाभिधीयते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.27', 'transliteration', 'sa', 'Latn', 'yajñe tapasi dāne ca sthitiḥ saditi cocyate
karma caiva tadarthīyaṃ sadityevābhidhīyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.27', 'translation', 'en', 'Latn', 'Constancy in (making) sacrifices. penances, and gifts, is called ''Sat;'' and (all) action, too, of which that is the object, is also called ''Sat.'' Whatever oblation is offered', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.27', 'vedic-scriptures', 'BG17.27', 'Devanagari and IAST digital witness');
