INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.17.28', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.17.28', 17, 28, 'Krishna', '935d2e5e9da8164b84bf90ed1b64b0daa7ce0ee8be9e0edc668a8220e4c0878d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.28', 'original', 'sa', 'Deva', 'अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत्।
असदित्युच्यते पार्थ न च तत्प्रेत्य नो इह ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.28', 'transliteration', 'sa', 'Latn', 'aśraddhayā hutaṃ dattaṃ tapastaptaṃ kṛtaṃ ca yat
asadityucyate pārtha na ca tatprepya no iha', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.17.28', 'translation', 'en', 'Latn', 'whatever is given whatever penance is performed and whatever is done without faith that O son of Pṛthā! is called ''Asat,'' and that is nought both after death and here.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.17.28', 'vedic-scriptures', 'BG17.28', 'Devanagari and IAST digital witness');
