INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.1', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.1', 18, 1, 'Arjuna', '050b72bd979295c3a812a7860d2dbf1f096bde0081955edf591274d7aa9e0997', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.1', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
संन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम्।
त्यागस्य च हृषीकेश पृथक्केशिनिषूदन ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.1', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
saṃnyāsasya mahābāho tattvamicchāmi veditum
tyāgasya ca hṛṣīkeśa pṛthakkeśiniṣūdana', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.1', 'translation', 'en', 'Latn', 'O you of mighty arms! O Hṛṣīkeśa! O destroyer of Keśin! I wish to know the truth about renunciation and abandonment distinctly.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.1', 'vedic-scriptures', 'BG18.1', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.1', 'telang-1882', 'Chapter 18; aligned against BG18.1', 'English translation witness');
