INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.2', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.2', 18, 2, 'Krishna', 'ef27b173cfd87483699e3b2ef2f84cbb30dbd02c813c37ce0705974cd3a4b51e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.2', 'original', 'sa', 'Deva', 'श्रीभगवानुवाच।
काम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः।
सर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.2', 'transliteration', 'sa', 'Latn', 'śrībhagavānuvāca
kāmyānāṃ karmaṇāṃ nyāsaṃ saṃnyāsaṃ kavayo viduḥ
sarvakarmaphalatyāgaṃ prāhustyāgaṃ vicakṣaṇāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.2', 'translation', 'en', 'Latn', 'By renunciation the sages understand the rejection of actions done with desires. The wise call the abandonment of the fruit of all actions (by the name) abandonment.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.2', 'vedic-scriptures', 'BG18.2', 'Devanagari and IAST digital witness');
