INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.3', 'original', 'sa', 'Deva', 'त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः।
यज्ञदानतपःकर्म न त्याज्यमिति चापरे ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.3', 'transliteration', 'sa', 'Latn', 'tyājyaṃ doṣavadityeke karma prāhurmanīṣiṇaḥ
yajñadānatapaḥkarma na tyājyamiti cāpare', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.3', 'translation', 'en', 'Latn', 'Some wise men say, that action should be abandoned as being full of evil and others that the actions of sacrifice gift', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.3', 'vedic-scriptures', 'BG18.3', 'Devanagari and IAST digital witness');
