INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.4', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.4', 18, 4, 'Krishna', '86d2e37dd53bb7516fcde9bb77ba2ec151c6895712a1e033f05bd3a06906240c', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.4', 'original', 'sa', 'Deva', 'निश्चयं शृणु मे तत्र त्यागे भरतसत्तम।
त्यागो हि पुरुषव्याघ्र त्रिविधः सम्प्रकीर्तितः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.4', 'transliteration', 'sa', 'Latn', 'niścayaṃ śṛṇu me tatra tyāge bharatasattama
tyāgo hi puruṣavyāghra trividhaḥ samprakīrtitaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.4', 'translation', 'en', 'Latn', 'and penance should not be abandoned. As to that abandonment O best of the descendants of Bharata! listen to my decision for abandonment, O bravest of men! is described (to be) threefold.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.4', 'vedic-scriptures', 'BG18.4', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.4', 'telang-1882', 'Chapter 18; aligned against BG18.4', 'English translation witness');
