INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.5', 'original', 'sa', 'Deva', 'यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत्।
यज्ञो दानं तपश्चैव पावनानि मनीषिणाम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.5', 'transliteration', 'sa', 'Latn', 'yajñadānatapaḥkarma na tyājyaṃ kāryameva tat
yajño dānaṃ tapaścaiva pāvanāni manīṣiṇām', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.5', 'translation', 'en', 'Latn', 'The actions of sacrifice, gift, and penance should not be abandoned they must needs be performed', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.5', 'vedic-scriptures', 'BG18.5', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.5', 'telang-1882', 'Chapter 18; aligned against BG18.5', 'English translation witness');
