INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.6', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.6', 18, 6, 'Krishna', '24383ad2579712fdf2bd89359a86d83939b93b9013ca525691c91b4fe27d24ea', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.6', 'original', 'sa', 'Deva', 'एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च।
कर्तव्यानीति मे पार्थ निश्चितं मतमुत्तमम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.6', 'transliteration', 'sa', 'Latn', 'etānyapi tu karmāṇi saṅgaṃ tyaktvā phalāni ca
kartavyānīti me pārtha niścitaṃ matamuttamam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.6', 'translation', 'en', 'Latn', 'for sacrifices, gifts, and penances are means of sanctification to the wise. But even these actions, O son of Pṛthā! should be performed, abandoning attachment and fruit such is my excellent and decided opinion.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.6', 'vedic-scriptures', 'BG18.6', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.6', 'telang-1882', 'Chapter 18; aligned against BG18.6', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.6', 'एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च।
कर्तव्यानीति मे पार्थ निश्चितं मतमुत्तमम् ॥', 'etānyapi tu karmāṇi saṅgaṃ tyaktvā phalāni ca
kartavyānīti me pārtha niścitaṃ matamuttamam', 'for sacrifices, gifts, and penances are means of sanctification to the wise. But even these actions, O son of Pṛthā! should be performed, abandoning attachment and fruit such is my excellent and decided opinion.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.7', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.7', 18, 7, 'Krishna', '562fce8374a86ad5c59d96dcf18674ce7835d75c562797c8caca734a8656eb0e', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.7', 'original', 'sa', 'Deva', 'नियतस्य तु संन्यासः कर्मणो नोपपद्यते।
मोहात्तस्य परित्यागस्तामसः परिकीर्तितः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.7', 'transliteration', 'sa', 'Latn', 'niyatasya tu saṃnyāsaḥ karmaṇo nopapadyate
mohāttasya parityāgastāmasaḥ parikīrtitaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.7', 'translation', 'en', 'Latn', 'The renunciation of prescribed action is not proper. Its abandonment through delusion is described as of the quality of darkness. When a man abandons action merely as being troublesome', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.7', 'vedic-scriptures', 'BG18.7', 'Devanagari and IAST digital witness');
