INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.8', 'original', 'sa', 'Deva', 'दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत्।
