INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.9', 'original', 'sa', 'Deva', 'कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन।
सङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.9', 'transliteration', 'sa', 'Latn', 'kāryamityeva yatkarma niyataṃ kriyate.arjuna
saṅgaṃ tyaktvā phalaṃ caiva sa tyāgaḥ sāttviko mataḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.9', 'translation', 'en', 'Latn', 'he does not obtain the fruit of abandonment by making (such) passionate abandonment. When prescribed action is performed O Arjuna ! abandoning attachment and fruit also merely because it ought to be performed that is deemed (to be) a good abandonment. He who is possessed of abandonment being full of goodness and talented and having', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.9', 'vedic-scriptures', 'BG18.9', 'Devanagari and IAST digital witness');
