INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.10', 'original', 'sa', 'Deva', 'न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते।
त्यागी सत्त्वसमाविष्टो मेधावी छिन्नसंशयः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.10', 'transliteration', 'sa', 'Latn', 'na dveṣṭyakuśalaṃ karma kuśale nānuṣajjate
