INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.11', 'original', 'sa', 'Deva', 'न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः।
यस्तु कर्मफलत्यागी स त्यागीत्यभिधीयते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.11', 'transliteration', 'sa', 'Latn', 'na hi dehabhṛtā śakyaṃ tyaktuṃ karmāṇyaśeṣataḥ
yastu karmaphalatyāgī sa tyāgītyabhidhīyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.11', 'translation', 'en', 'Latn', 'is not averse from unpleasant actions is not attached to pleasant (ones). Since no embodied (being) can abandon actions without exception, he is said to be possessed of abandonment, who abandons the fruit of action.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.11', 'vedic-scriptures', 'BG18.11', 'Devanagari and IAST digital witness');
