INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.13', 'translation', 'en', 'Latn', 'Learn from me, O you of mighty arms! these five causes of the completion of all actions, declared in the Sāṅkhya system.', 'telang-1882');
