INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.14', 'original', 'sa', 'Deva', 'अधिष्ठानं तथा कर्ता करणं च पृथग्विधम्।
विविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.14', 'transliteration', 'sa', 'Latn', 'adhiṣṭhānaṃ tathā kartā karaṇaṃ ca pṛthagvidham
vividhāśca pṛthakceṣṭā daivaṃ caivātra pañcamam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.14', 'translation', 'en', 'Latn', 'The substratum, the agent likewise, the various sorts of organs, and the various and distinct movements, and with these the deities, too, as the fifth. Whatever action just or otherwise', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.14', 'vedic-scriptures', 'BG18.14', 'Devanagari and IAST digital witness');
