INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.16', 'transliteration', 'sa', 'Latn', 'tatraivaṃ sati kartāramātmānaṃ kevalaṃ tu yaḥ
