INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.16', 'translation', 'en', 'Latn', 'who being of an unrefined understanding sees the agent in the immaculate self', 'telang-1882');
