INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.16', 'तत्रैवं सति कर्तारमात्मानं केवलं तु यः।
पश्यत्यकृतबुद्धित्वान्न स पश्यति दुर्मतिः ॥', 'tatraivaṃ sati kartāramātmānaṃ kevalaṃ tu yaḥ
paśyatyakṛtabuddhitvānna sa paśyati durmatiḥ', 'who being of an unrefined understanding sees the agent in the immaculate self');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.17', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.17', 18, 17, 'Krishna', '66641de2aeb255e4909bd22a3ff45289409547fd249fe4edbf2d599515c5adf5', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.17', 'original', 'sa', 'Deva', 'यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते।
हत्वाऽपि स इमाँल्लोकान्न हन्ति न निबध्यते ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.17', 'transliteration', 'sa', 'Latn', 'yasya nāhaṃkṛto bhāvo buddhiryasya na lipyate
hatvā.api sa imā.Nllokānna hanti na nibadhyate', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.17', 'translation', 'en', 'Latn', 'sees not (rightly). He who has no feeling of egoism, and whose mind is not tainted, even though he kills (all) these people, kills not, is not fettered, (by the action).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.17', 'vedic-scriptures', 'BG18.17', 'Devanagari and IAST digital witness');
