INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.18', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.18', 18, 18, 'Krishna', '7a88edee7a5e33961ea0a86d547eba82dffdaefadf26f4aa0aef4d7be2cc826a', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.18', 'original', 'sa', 'Deva', 'ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना।
करणं कर्म कर्तेति त्रिविधः कर्मसंग्रहः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.18', 'transliteration', 'sa', 'Latn', 'jñānaṃ jñeyaṃ parijñātā trividhā karmacodanā
karaṇaṃ karma karteti trividhaḥ karmasaṃgrahaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.18', 'translation', 'en', 'Latn', 'Knowledge, the object of knowledge, the knower—threefold is the prompting to action. The instrument, the action, the agent, thus in brief is action threefold.', 'telang-1882');
