INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.19', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.19', 18, 19, 'Krishna', '47ed960284b4563d7b230dda3e8dd0c829d7a31c49f8f0d12e2054524b9cf96f', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.19', 'original', 'sa', 'Deva', 'ज्ञानं कर्म च कर्ताच त्रिधैव गुणभेदतः।
प्रोच्यते गुणसङ्ख्याने यथावच्छृणु तान्यपि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.19', 'transliteration', 'sa', 'Latn', 'jñānaṃ karma ca kartāca tridhaiva guṇabhedataḥ
procyate guṇasaṅkhyāne yathāvacchṛṇu tānyapi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.19', 'translation', 'en', 'Latn', 'Knowledge and action and agent are declared in the enumeration of qualities (to be) of three classes only, according to the difference of qualities. Hear about these also as they really are.', 'telang-1882');
