INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.20', 'original', 'sa', 'Deva', 'सर्वभूतेषु येनैकं भावमव्ययमीक्षते।
अविभक्तं विभक्तेषु तज्ज्ञानं विद्धि सात्त्विकम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.20', 'transliteration', 'sa', 'Latn', 'sarvabhūteṣu yenaikaṃ bhāvamavyayamīkṣate
