INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.20', 'translation', 'en', 'Latn', 'Know that knowledge to be good, by which (a man) sees one entity, inexhaustible, and not different in all things (apparently) different (from one another).', 'telang-1882');
