INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.21', 'transliteration', 'sa', 'Latn', 'pṛthaktvena tu yajjñānaṃ nānābhāvānpṛthagvidhān
