INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.21', 'translation', 'en', 'Latn', 'Know that knowledge to be passionate which is (based) on distinctions (between different entities) which sees in all things various entities of different kinds. And that is described as dark', 'telang-1882');
