INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.23', 'transliteration', 'sa', 'Latn', 'niyataṃ saṅgarahitamarāgadveṣataḥ kṛtam
