INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.23', 'translation', 'en', 'Latn', 'and insignificant. That action is called good which is prescribed which is devoid of attachment which is not done from (motives of) affection or aversion, (and which is done) by one not wishing for the fruit. That is described as passionate', 'telang-1882');
