INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.30', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.30', 18, 30, 'Krishna', 'aa47c4c630808b5ca0f922aa3ba767dbe7c3302484929a2683408eb8a705a4f8', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.30', 'original', 'sa', 'Deva', 'प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये।
बन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.30', 'transliteration', 'sa', 'Latn', 'pravṛttiṃ ca nivṛttiṃ ca kāryākārye bhayābhaye
bandhaṃ mokṣaṃ ca yā vetti buddhiḥ sā pārtha sāttvikī', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.30', 'translation', 'en', 'Latn', 'O son of Pṛthā! is good which understands action and inaction what ought to be done and what ought not to be done danger and the absence of danger emancipation and bondage. That intelligence O son of Pṛthā! is passionate', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.30', 'vedic-scriptures', 'BG18.30', 'Devanagari and IAST digital witness');
