INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.35', 'translation', 'en', 'Latn', 'O son of Pṛthā! by which an undiscerning man does not give up sleep fear sorrow despondency and folly.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.35', 'vedic-scriptures', 'BG18.35', 'Devanagari and IAST digital witness');
