INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.35', 'यया स्वप्नं भयं शोकं विषादं मदमेव च।
न विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी ॥', 'yayā svapnaṃ bhayaṃ śokaṃ viṣādaṃ madameva ca
na vimuñcati durmedhā dhṛtiḥ sā pārtha tāmasī', 'O son of Pṛthā! by which an undiscerning man does not give up sleep fear sorrow despondency and folly.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.36', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.36', 18, 36, 'Krishna', '5c7fec1b8ad7df013a45a696817305b65afa851e3347fa2a0ee7674642b90a5f', 'first review verified; second review pending', 0);
