INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.37', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.37', 18, 37, 'Krishna', '54f6d637a7a65c4674498d1157188618bb59cd6598c2ffb98c32587e365ec46b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.37', 'original', 'sa', 'Deva', 'यत्तदग्रे विषमिव परिणामेऽमृतोपमम्।
तत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.37', 'transliteration', 'sa', 'Latn', 'yattadagre viṣamiva pariṇāme.amṛtopamam
tatsukhaṃ sāttvikaṃ proktamātmabuddhiprasādajam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.37', 'translation', 'en', 'Latn', 'O chief of the descendants of Bharata! bear from me about the three sorts of happiness. That happiness is called good in which one is pleased after repetition (of enjoyment) and reaches the close of all misery which is like poison first and comparable to nectar in the long run and which is produced from a clear knowledge of the self. That happiness is called passionate', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.37', 'vedic-scriptures', 'BG18.37', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.37', 'telang-1882', 'Chapter 18; aligned against BG18.37', 'English translation witness');
