INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.40', 'original', 'sa', 'Deva', 'न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः।
सत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्त्रिभिर्गुणैः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.40', 'transliteration', 'sa', 'Latn', 'na tadasti pṛthivyāṃ vā divi deveṣu vā punaḥ
sattvaṃ prakṛtijairmuktaṃ yadebhiḥ syāttribhirguṇaiḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.40', 'translation', 'en', 'Latn', 'both at first and in its consequences. There is no entity either on earth or in heaven among the gods, which is free from these three qualities born of nature.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.40', 'vedic-scriptures', 'BG18.40', 'Devanagari and IAST digital witness');
