INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.42', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.42', 18, 42, 'Krishna', '6a681d8e558d4b25c8c1c8c8748530b6638f2b1bbff616f45e6c7e1a4ea8e66b', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.42', 'original', 'sa', 'Deva', 'शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च।
ज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.42', 'transliteration', 'sa', 'Latn', 'śamo damastapaḥ śaucaṃ kṣāntirārjavameva ca
jñānaṃ vijñānamāstikyaṃ brahmakarma svabhāvajam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.42', 'translation', 'en', 'Latn', 'Tranquillity, restraint of the senses, penance, purity, forgiveness, straightforwardness, also knowledge, experience, and belief (in a future world), this is the natural duty of Brāhmaṇas.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.42', 'vedic-scriptures', 'BG18.42', 'Devanagari and IAST digital witness');
