INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.44', 'original', 'sa', 'Deva', 'कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम्।
परिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.44', 'transliteration', 'sa', 'Latn', 'kṛṣigaurakṣyavāṇijyaṃ vaiśyakarma svabhāvajam
