INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.44', 'translation', 'en', 'Latn', 'Agriculture, tending cattle, trade, (this) is the natural duty of Vaiśyas, And the natural duty of Śūdras, too, consists in service. (Every) man intent on his own respective duties obtains perfection.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.44', 'vedic-scriptures', 'BG18.44', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.44', 'telang-1882', 'Chapter 18; aligned against BG18.44', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.44', 'कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम्।
परिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम् ॥', 'kṛṣigaurakṣyavāṇijyaṃ vaiśyakarma svabhāvajam
paricaryātmakaṃ karma śūdrasyāpi svabhāvajam', 'Agriculture, tending cattle, trade, (this) is the natural duty of Vaiśyas, And the natural duty of Śūdras, too, consists in service. (Every) man intent on his own respective duties obtains perfection.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.45', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.45', 18, 45, 'Krishna', 'a8fb8e9eee605121c0ad2c6d5a4c205d693cddbd4d3dd05c64656a7f5abfdb44', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.45', 'original', 'sa', 'Deva', 'स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः।
स्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.45', 'transliteration', 'sa', 'Latn', 'sve sve karmaṇyabhirataḥ saṃsiddhiṃ labhate naraḥ
svakarmanirataḥ siddhiṃ yathā vindati tacchṛṇu', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.45', 'translation', 'en', 'Latn', 'Listen, now, how one intent on one''s own duty obtains perfection.', 'telang-1882');
