INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.46', 'original', 'sa', 'Deva', 'यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम्।
स्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.46', 'transliteration', 'sa', 'Latn', 'yataḥ pravṛttirbhūtānāṃ yena sarvamidaṃ tatam
svakarmaṇā tamabhyarcya siddhiṃ vindati mānavaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.46', 'translation', 'en', 'Latn', 'Worshipping, by (the performance of) his own duty, him from whom all things proceed, and by whom all this is permeated, a man obtains perfection.', 'telang-1882');
