INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.47', 'original', 'sa', 'Deva', 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।
स्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.47', 'transliteration', 'sa', 'Latn', 'śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt
svabhāvaniyataṃ karma kurvannāpnoti kilbiṣam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.47', 'translation', 'en', 'Latn', 'One''s duty, though defective, is better than another''s duty well performed. Performing the duty prescribed by nature, one does not incur sin.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.47', 'vedic-scriptures', 'BG18.47', 'Devanagari and IAST digital witness');
