INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.48', 'original', 'sa', 'Deva', 'सहजं कर्म कौन्तेय सदोषमपि न त्यजेत्।
सर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.48', 'transliteration', 'sa', 'Latn', 'sahajaṃ karma kaunteya sadoṣamapi na tyajet
sarvārambhā hi doṣeṇa dhūmenāgnirivāvṛtāḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.48', 'translation', 'en', 'Latn', 'O son of Kuntī ! one should not abandon a natural duty though tainted with evil for all actions are enveloped by evil, as fire by smoke.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.48', 'vedic-scriptures', 'BG18.48', 'Devanagari and IAST digital witness');
