INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.49', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.49', 18, 49, 'Krishna', 'ba67a71739fb914a18402ba854be403ef4aabde2118a29ff8801da65c3f78d25', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.49', 'original', 'sa', 'Deva', 'असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः।
नैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.49', 'transliteration', 'sa', 'Latn', 'asaktabuddhiḥ sarvatra jitātmā vigataspṛhaḥ
naiṣkarmyasiddhiṃ paramāṃ saṃnyāsenādhigacchati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.49', 'translation', 'en', 'Latn', 'One who is self-restrained, whose understanding is unattached everywhere, from whom affections have departed, obtains the supreme perfection of freedom from action by renunciation.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.49', 'vedic-scriptures', 'BG18.49', 'Devanagari and IAST digital witness');
