INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.50', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.50', 18, 50, 'Krishna', 'b2444f1bb94d3210c49893795c604405722d8303e2f0a0ae8ed283f4e8f89e9d', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.50', 'original', 'sa', 'Deva', 'सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे।
समासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.50', 'transliteration', 'sa', 'Latn', 'siddhiṃ prāpto yathā brahma tathāpnoti nibodha me
samāsenaiva kaunteya niṣṭhā jñānasya yā parā', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.50', 'translation', 'en', 'Latn', 'Learn from me, only in brief, O son of Kuntī! how one who has obtained perfection attains the Brahman , which is the highest culmination of knowledge.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.50', 'vedic-scriptures', 'BG18.50', 'Devanagari and IAST digital witness');
