INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.51', 'original', 'sa', 'Deva', 'बुद्ध्या विशुद्धया युक्तो धृत्यात्मानं नियम्य च।
