INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.51', 'transliteration', 'sa', 'Latn', 'buddhyā viśuddhayā yukto dhṛtyātmānaṃ niyamya ca
