INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.52', 'translation', 'en', 'Latn', 'who eats little whose speech body and mind are restrained who is always intent on meditation and mental abstraction and has recourse to unconcern', 'telang-1882');
