INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.54', 'transliteration', 'sa', 'Latn', 'brahmabhūtaḥ prasannātmā na śocati na kāṅkṣati
