INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.54', 'translation', 'en', 'Latn', 'and (all) belongings has no (thought that this or that is) mine and who is tranquil becomes fit for assimilation with the Brahman. Thus reaching the Brahman, and with a tranquil self, he grieves not, wishes not', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.54', 'vedic-scriptures', 'BG18.54', 'Devanagari and IAST digital witness');
