INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.54', 'ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति।
समः सर्वेषु भूतेषु मद्भक्तिं लभते पराम् ॥', 'brahmabhūtaḥ prasannātmā na śocati na kāṅkṣati
samaḥ sarveṣu bhūteṣu madbhaktiṃ labhate parām', 'and (all) belongings has no (thought that this or that is) mine and who is tranquil becomes fit for assimilation with the Brahman. Thus reaching the Brahman, and with a tranquil self, he grieves not, wishes not');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.55', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.55', 18, 55, 'Krishna', 'c7e2d7662eb6ce2117dd87a7c4334756910dcf72e67198ff12eefa5fb7954675', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.55', 'original', 'sa', 'Deva', 'भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।
ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.55', 'transliteration', 'sa', 'Latn', 'bhaktyā māmabhijānāti yāvānyaścāsmi tattvataḥ
tato māṃ tattvato jñātvā viśate tadanantaram', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.55', 'translation', 'en', 'Latn', 'but being alike to all beings, obtains the highest devotion to me. By (that) devotion he truly understands who I am and how great. And then understanding me truly, he forthwith enters into my (essence).', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.55', 'vedic-scriptures', 'BG18.55', 'Devanagari and IAST digital witness');
