INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.56', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.56', 18, 56, 'Krishna', '07cf73d09471f0acfa604f9d73692554a250891f52973837cdf638f655a2d4a9', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.56', 'original', 'sa', 'Deva', 'सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः।
मत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.56', 'transliteration', 'sa', 'Latn', 'sarvakarmāṇyapi sadā kurvāṇo madvyapāśrayaḥ
matprasādādavāpnoti śāśvataṃ padamavyayam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.56', 'translation', 'en', 'Latn', 'Even performing all actions, always depending on me, he, through my favour, obtains the imperishable and eternal seat.', 'telang-1882');
