INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.57', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.57', 18, 57, 'Krishna', '09b77a2b6ef191980c7607bbac2ef8181be1741455c9a155e20290e49f7ce310', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.57', 'original', 'sa', 'Deva', 'चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः।
बुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.57', 'transliteration', 'sa', 'Latn', 'cetasā sarvakarmāṇi mayi saṃnyasya matparaḥ
buddhiyogamupāśritya maccittaḥ satataṃ bhava', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.57', 'translation', 'en', 'Latn', 'Dedicating in thought all actions to me, be constantly given up to me, (placing) your thoughts on me, through recourse to mental abstraction.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.57', 'vedic-scriptures', 'BG18.57', 'Devanagari and IAST digital witness');
