INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.58', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.58', 18, 58, 'Krishna', '6a43529ce1d36865cf64b89677265fc5ff95e779ace708c09e5528f7504fb251', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.58', 'original', 'sa', 'Deva', 'मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।
अथ चेत्त्वमहंकारान्न श्रोष्यसि विनङ्क्ष्यसि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.58', 'transliteration', 'sa', 'Latn', 'maccittaḥ sarvadurgāṇi matprasādāttariṣyasi
atha cettvamahaṃkārānna śroṣyasi vinaṅkṣyasi', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.58', 'translation', 'en', 'Latn', '(Placing) your thoughts on me, you will cross over all difficulties by my favour. But if you will not listen through egotism, you will be ruined.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.58', 'vedic-scriptures', 'BG18.58', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.58', 'telang-1882', 'Chapter 18; aligned against BG18.58', 'English translation witness');
INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.58', 'मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।
अथ चेत्त्वमहंकारान्न श्रोष्यसि विनङ्क्ष्यसि ॥', 'maccittaḥ sarvadurgāṇi matprasādāttariṣyasi
atha cettvamahaṃkārānna śroṣyasi vinaṅkṣyasi', '(Placing) your thoughts on me, you will cross over all difficulties by my favour. But if you will not listen through egotism, you will be ruined.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.59', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.59', 18, 59, 'Krishna', '57b80339227d05163a01cb2bcc96bfd1aee452617417d58cf0de6ca19bec2992', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.59', 'original', 'sa', 'Deva', 'यदहंकारमाश्रित्य न योत्स्य इति मन्यसे।
मिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.59', 'transliteration', 'sa', 'Latn', 'yadahaṃkāramāśritya na yotsya iti manyase
mithyaiṣa vyavasāyaste prakṛtistvāṃ niyokṣyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.59', 'translation', 'en', 'Latn', 'If entertaining egotism, you think that you may not fight, vain, indeed, is that resolution of yours. Nature will constrain you. That', 'telang-1882');
