INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.60', 'original', 'sa', 'Deva', 'स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।
