INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.60', 'transliteration', 'sa', 'Latn', 'svabhāvajena kaunteya nibaddhaḥ svena karmaṇā
