INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.60', 'translation', 'en', 'Latn', 'O son of Kuntī! which through delusion you do not wish to do you will do involuntarily tied down by your own duty flowing from your nature.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.60', 'vedic-scriptures', 'BG18.60', 'Devanagari and IAST digital witness');
