INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.62', 'original', 'sa', 'Deva', 'तमेव शरणं गच्छ सर्वभावेन भारत।
तत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.62', 'transliteration', 'sa', 'Latn', 'tameva śaraṇaṃ gaccha sarvabhāvena bhārata
tatprasādātparāṃ śāntiṃ sthānaṃ prāpsyasi śāśvatam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.62', 'translation', 'en', 'Latn', 'O Arjuna! is seated in the region of the heart of all beings turning round all beings (as though) mounted on a machine by his delusion. With him O descendant of Bharata! seek shelter in every way by his favour you will obtain the highest tranquillity, the eternal seat.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.62', 'vedic-scriptures', 'BG18.62', 'Devanagari and IAST digital witness');
