INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.63', 'transliteration', 'sa', 'Latn', 'iti te jñānamākhyātaṃ guhyādguhyataraṃ mayā
