INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.63', 'translation', 'en', 'Latn', 'Thus have I declared to you the knowledge more mysterious than any mystery. Ponder over it thoroughly, and then act as you like.', 'telang-1882');
