INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.66', 'transliteration', 'sa', 'Latn', 'sarvadharmānparityajya māmekaṃ śaraṇaṃ vraja
