INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.66', 'translation', 'en', 'Latn', 'Forsaking all duties, come to me as (your) sole refuge. I will release you from all sins. Be not grieved.', 'telang-1882');
