INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.67', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.67', 18, 67, 'Krishna', '88da6be9c55379eb9b54a58e7da4f01ff360197f40de10ab3ecef7cfe570c639', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.67', 'original', 'sa', 'Deva', 'इदं ते नातपस्काय नाभक्ताय कदाचन।
न चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.67', 'transliteration', 'sa', 'Latn', 'idaṃ te nātapaskāya nābhaktāya kadācana
na cāśuśrūṣave vācyaṃ na ca māṃ yo.abhyasūyati', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.67', 'translation', 'en', 'Latn', 'This you should never declare to one who performs no penance who is not a devotee nor to one who does not wait on (some preceptor) nor yet to one who calumniates me.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.67', 'vedic-scriptures', 'BG18.67', 'Devanagari and IAST digital witness');
