INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.68', 'original', 'sa', 'Deva', 'य इदं परमं गुह्यं मद्भक्तेष्वभिधास्यति।
