INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.68', 'transliteration', 'sa', 'Latn', 'ya idaṃ paramaṃ guhyaṃ madbhakteṣvabhidhāsyati
