INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.68', 'translation', 'en', 'Latn', 'He who, with the highest devotion to me, will proclaim this supreme mystery among my devotees, will come to me, freed from (all) doubt.', 'telang-1882');
