INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.69', 'original', 'sa', 'Deva', 'न च तस्मान्मनुष्येषु कश्चिन्मे प्रियकृत्तमः।
भविता न च मे तस्मादन्यः प्रियतरो भुवि ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.69', 'transliteration', 'sa', 'Latn', 'na ca tasmānmanuṣyeṣu kaścinme priyakṛttamaḥ
