INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.69', 'translation', 'en', 'Latn', 'No one amongst men is superior to him in doing what is dear to me. And there will never be another on earth dearer to me than he. And he who will study this holy dialogue of ours will', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.69', 'vedic-scriptures', 'BG18.69', 'Devanagari and IAST digital witness');
