INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.72', 'original', 'sa', 'Deva', 'कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा।
