INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.72', 'transliteration', 'sa', 'Latn', 'kaccidetacchrutaṃ pārtha tvayaikāgreṇa cetasā
