INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.72', 'translation', 'en', 'Latn', 'who with faith and without carping will listen (to this) will be freed (from sin) and attain to the holy regions of those who perform pious acts. Have you listened to this O son of Pṛthā! with a mind (fixed) on (this) one point only? Has your delusion (caused) by ignorance been destroyed O Dhanañjaya?', 'telang-1882');
