INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.73', 'original', 'sa', 'Deva', 'अर्जुन उवाच।
नष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।
स्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.73', 'transliteration', 'sa', 'Latn', 'arjuna uvāca
naṣṭo mohaḥ smṛtirlabdhā tvatprasādānmayācyuta
sthito.asmi gatasandehaḥ kariṣye vacanaṃ tava', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.73', 'translation', 'en', 'Latn', 'Destroyed is my delusion by your favour, O undegraded one! I (now) recollect myself. I stand freed from doubts. I will do your bidding.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.73', 'vedic-scriptures', 'BG18.73', 'Devanagari and IAST digital witness');
