INSERT INTO passages_fts (canonical_ref, devanagari, iast, english) VALUES ('gita.18.73', 'अर्जुन उवाच।
नष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।
स्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव ॥', 'arjuna uvāca
naṣṭo mohaḥ smṛtirlabdhā tvatprasādānmayācyuta
sthito.asmi gatasandehaḥ kariṣye vacanaṃ tava', 'Destroyed is my delusion by your favour, O undegraded one! I (now) recollect myself. I stand freed from doubts. I will do your bidding.');
INSERT OR REPLACE INTO passages (id, edition_id, corpus_version_id, canonical_ref, chapter, verse, speaker, checksum, review_status, release_eligible) VALUES ('gita.18.74', 'gita-standard-700', 'gita-1.0.0-rc.1', 'gita.18.74', 18, 74, 'Sanjaya', 'b766d0500c70f449bc1fb2177cf1070125e33ea39c2fce4b64e79df9304cddc2', 'first review verified; second review pending', 0);
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.74', 'original', 'sa', 'Deva', 'सञ्जय उवाच।
इत्यहं वासुदेवस्य पार्थस्य च महात्मनः।
संवादमिममश्रौषमद्भुतं रोमहर्षणम् ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.74', 'transliteration', 'sa', 'Latn', 'sañjaya uvāca
ityahaṃ vāsudevasya pārthasya ca mahātmanaḥ
saṃvādamimamaśrauṣamadbhutaṃ romaharṣaṇam', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.74', 'translation', 'en', 'Latn', 'Thus did I hear this dialogue between Vāsudeva and the high-minded son of Pṛthā, (a dialogue) wonderful and causing the hair to stand on end.', 'telang-1882');
