INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.75', 'original', 'sa', 'Deva', 'व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम्।
