INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.75', 'translation', 'en', 'Latn', 'By the favour of Vyāsa I heard this highest mystery, (this) devotion from Kṛṣṇa himself the lord of the possessors of mystic power who proclaimed it in person.', 'telang-1882');
