INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.76', 'original', 'sa', 'Deva', 'राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम्।
केशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.76', 'transliteration', 'sa', 'Latn', 'rājansaṃsmṛtya saṃsmṛtya saṃvādamimamadbhutam
keśavārjunayoḥ puṇyaṃ hṛṣyāmi ca muhurmuhuḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.76', 'translation', 'en', 'Latn', 'O king! remembering and (again) remembering this wonderful and holy dialogue of Keśava and Arjuna', 'telang-1882');
