INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.77', 'original', 'sa', 'Deva', 'तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः।
विस्मयो मे महान् राजन्हृष्यामि च पुनः पुनः ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.77', 'transliteration', 'sa', 'Latn', 'tacca saṃsmṛtya saṃsmṛtya rūpamatyadbhutaṃ hareḥ
vismayo me mahān rājanhṛṣyāmi ca punaḥ punaḥ', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.77', 'translation', 'en', 'Latn', 'I rejoice over and over again. And remembering and (again) remembering that excessively wonderful form of Hari also great is my amazement O king! and I rejoice over and over again.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.77', 'vedic-scriptures', 'BG18.77', 'Devanagari and IAST digital witness');
