INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.78', 'original', 'sa', 'Deva', 'यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः।
तत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम ॥', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.78', 'transliteration', 'sa', 'Latn', 'yatra yogeśvaraḥ kṛṣṇo yatra pārtho dhanurdharaḥ
tatra śrīrvijayo bhūtirdhruvā nītirmatirmama', 'vedic-scriptures');
INSERT OR REPLACE INTO text_representations (passage_id, kind, language, script, content, source_id) VALUES ('gita.18.78', 'translation', 'en', 'Latn', 'Wherever (is) Kṛṣṇa the lord of the possessors of mystic power wherever (is the (great) archer the son of Prithā there in my opinion (are) fortune victory prosperity and eternal justice.', 'telang-1882');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.78', 'vedic-scriptures', 'BG18.78', 'Devanagari and IAST digital witness');
INSERT OR REPLACE INTO passage_sources (passage_id, source_id, locator, role) VALUES ('gita.18.78', 'telang-1882', 'Chapter 18; aligned against BG18.78', 'English translation witness');
